'use client';

import React, { use } from 'react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { GAMES_CATALOG } from '@/lib/games-data';
import { GameSubNavbar } from '@/components/layout/game-sub-navbar';
import { TeamProfileView } from '@/components/teams/team-profile-view';
import { initialTeams } from '@/lib/data-store';
import { Button } from '@/components/ui/button';

interface TeamPageProps {
  params: Promise<{ gameSlug: string; teamId: string }>;
}

export default function DedicatedTeamProfilePage({ params }: TeamPageProps) {
  const { gameSlug, teamId } = use(params);
  const router = useRouter();

  const [fetchedTeam, setFetchedTeam] = React.useState<any>(null);

  // Support game slugs including csgo / cs2 alias
  let game = GAMES_CATALOG[gameSlug];
  if (!game && (gameSlug === 'cs2' || gameSlug === 'csgo')) {
    game = GAMES_CATALOG['csgo'];
  }

  React.useEffect(() => {
    fetch(`/api/teams`)
      .then((res) => res.json())
      .then((data) => {
        if (data.success && Array.isArray(data.teams)) {
          const matched = data.teams.find(
            (t: any) =>
              t.id?.toLowerCase() === teamId.toLowerCase() ||
              t.tag?.toLowerCase() === teamId.toLowerCase() ||
              t.name?.toLowerCase()?.replace(/\s+/g, '-') === teamId.toLowerCase()
          );
          if (matched) setFetchedTeam(matched);
        }
      })
      .catch((err) => console.error('Error fetching team page data:', err));
  }, [teamId]);

  // Find team by ID, slugified name, or tag (Fallback matching)
  const normalizedTeamId = teamId.toLowerCase();
  const defaultTeam = initialTeams.find((t) =>
    t.id.toLowerCase() === normalizedTeamId ||
    t.tag.toLowerCase() === normalizedTeamId ||
    t.name.toLowerCase().replace(/\s+/g, '-') === normalizedTeamId
  ) || {
    id: teamId,
    name: 'Escuadra eSports',
    tag: 'TP',
    gameSlug: gameSlug as any,
    gameName: game?.name || 'EA SPORTS FC 26',
    captainId: 'usr-admin',
    captainName: 'Administrador',
    platform: 'CROSSPLAY',
    membersCount: 1,
    maxMembers: 45,
    color: game?.brandColor || '#00F0FF',
    logoText: 'TP',
    description: 'Escuadra oficial registrada en el circuito eSports.',
    logoUrl: '/images/default/logo-default.png',
    bannerUrl: '/images/default/banner-default.jpg',
    status: 'Escuadra Activa',
    disputando: 'Torneo Oficial',
    palmares: 'Club Registrado',
    vacantPositions: ['DFC', 'LI', 'MCD'],
    members: [],
  };

  const team = fetchedTeam || defaultTeam;

  if (!game) {
    return (
      <div className="max-w-4xl mx-auto px-4 py-24 text-center">
        <h1 className="text-3xl font-bold mb-4 text-[var(--text-heading)]">Juego no encontrado</h1>
        <p className="text-[var(--text-muted)] mb-6">El juego solicitado no existe en nuestro catálogo eSports.</p>
        <Link href="/">
          <Button variant="primary">Volver al Inicio</Button>
        </Link>
      </div>
    );
  }

  return (
    <div
      className="min-h-screen pb-20 relative transition-all duration-500 bg-[var(--bg-main)] text-[var(--text-primary)]"
      style={{
        '--game-brand': game.brandColor,
        '--game-accent': game.accentColor,
      } as React.CSSProperties}
    >
      {/* Game Sub Navbar with 'equipos' active section */}
      <GameSubNavbar
        game={game}
        activeSection="equipos"
        onSelectSection={(section) => {
          if (section === 'home') {
            router.push(`/${game.slug}`);
          } else {
            router.push(`/${game.slug}`);
          }
        }}
      />

      {/* Main Full Bleed Team Profile Banner Attached Directly to Sub-Navbar with Margin 0 / Padding 0 */}
      <div className="w-full pt-0 pb-6 relative">
        <TeamProfileView
          team={team}
          brandColor={game.brandColor}
          onBack={() => router.push(`/${game.slug}`)}
        />
      </div>
    </div>
  );
}

'use client';

import React, { use } from 'react';
import Link from 'next/link';
import { GAMES_CATALOG } from '@/lib/games-data';
import { GameSubNavbar } from '@/components/layout/game-sub-navbar';
import { PlayerProfileView, PlayerData } from '@/components/players/player-profile-view';
import { useAuth } from '@/components/providers/auth-provider';
import { Button } from '@/components/ui/button';

interface PlayerPageProps {
  params: Promise<{ gameSlug: string; playerId: string }>;
}

export default function DedicatedPlayerProfilePage({ params }: PlayerPageProps) {
  const { gameSlug, playerId } = use(params);
  const { currentUser } = useAuth();

  let game = GAMES_CATALOG[gameSlug];
  if (!game && (gameSlug === 'cs2' || gameSlug === 'csgo')) {
    game = GAMES_CATALOG['csgo'];
  }

  const normalizedId = playerId?.toLowerCase();
  const isSelf = normalizedId === 'me' || normalizedId === 'ficha' || (currentUser?.id && normalizedId === currentUser.id.toLowerCase());

  const [dbUser, setDbUser] = React.useState<any | null>(null);

  React.useEffect(() => {
    if (!playerId) return;
    fetch(`/api/users?id=${playerId}`)
      .then((res) => res.json())
      .then((data) => {
        if (data.success && data.user) {
          setDbUser(data.user);
        }
      })
      .catch((err) => console.error('Error fetching player by id:', err));
  }, [playerId]);

  const activeUser = isSelf ? currentUser : (dbUser || (currentUser?.id && currentUser.id.toLowerCase() === normalizedId ? currentUser : null));

  const validPositions = game?.positions || [];
  const rawPos = activeUser?.gameProfiles?.[gameSlug]?.position || (gameSlug === activeUser?.primaryGame ? activeUser?.position : undefined) || (validPositions.includes(activeUser?.position) ? activeUser?.position : undefined);
  const resolvedPosition = (rawPos && validPositions.includes(rawPos)) ? rawPos : validPositions[0] || 'DFC';

  const rawSecPos = activeUser?.gameProfiles?.[gameSlug]?.secondaryPosition || (gameSlug === activeUser?.primaryGame ? activeUser?.secondaryPosition : undefined);
  let resolvedSecPos: string | undefined = undefined;
  if (
    rawSecPos &&
    typeof rawSecPos === 'string' &&
    rawSecPos.trim() !== '' &&
    !['n/a', 'na', 'sin posición', 'sin posicion', 'ninguna', 'none', '-'].includes(rawSecPos.trim().toLowerCase()) &&
    rawSecPos.trim() !== resolvedPosition &&
    validPositions.includes(rawSecPos.trim())
  ) {
    resolvedSecPos = rawSecPos.trim();
  }

  // Known player catalog mapping
  const knownPlayers: Record<string, Partial<PlayerData>> = {
    'usr-srdelorean': { id: 'usr-srdelorean', name: 'SrDeLorean', gamertag: 'SrDeLorean', position: 'DC', teamName: 'LeguaYork eSp', rating: 9.8, status: 'Atleta Titular', bio: 'Capitán y delantero estelar de LeguaYork eSp. Especialista en definición y liderazgo táctico.' },
    'srdelorean': { id: 'usr-srdelorean', name: 'SrDeLorean', gamertag: 'SrDeLorean', position: 'DC', teamName: 'LeguaYork eSp', rating: 9.8, status: 'Atleta Titular', bio: 'Capitán y delantero estelar de LeguaYork eSp. Especialista en definición y liderazgo táctico.' },
    'usr-sgjotta': { id: 'usr-sgjotta', name: 'SG Jotta', gamertag: 'SG_Jotta', position: 'DFC', teamName: 'San Lorenzo eSp', rating: 9.6, status: 'Atleta Titular', bio: 'Defensa central infranqueable de San Lorenzo eSp. Dominio del juego aéreo y cobertura limpia.' },
    'sg-jotta': { id: 'usr-sgjotta', name: 'SG Jotta', gamertag: 'SG_Jotta', position: 'DFC', teamName: 'San Lorenzo eSp', rating: 9.6, status: 'Atleta Titular', bio: 'Defensa central infranqueable de San Lorenzo eSp. Dominio del juego aéreo y cobertura limpia.' },
    'usr-aczinomeme': { id: 'usr-aczinomeme', name: 'AcZinoMeme', gamertag: 'AcZinoMeme', position: 'MC', teamName: 'Highfield XX', rating: 9.4, status: 'Atleta Titular', bio: 'Mediocampista organizador de Highfield XX. Visión de pase de gol y recuperación de balón.' },
    'aczinomeme': { id: 'usr-aczinomeme', name: 'AcZinoMeme', gamertag: 'AcZinoMeme', position: 'MC', teamName: 'Highfield XX', rating: 9.4, status: 'Atleta Titular', bio: 'Mediocampista organizador de Highfield XX. Visión de pase de gol y recuperación de balón.' },
    'usr-gabot': { id: 'usr-gabot', name: 'T_TGaboT_T', gamertag: 'T_TGaboT_T', position: 'POR', teamName: 'Sangre Nueva FC', rating: 9.5, status: 'Atleta Titular', bio: 'Guardameta titular de Sangre Nueva FC. Reflejos bajo palos y salida de balón con el pie.' },
    't_tgabot_t': { id: 'usr-gabot', name: 'T_TGaboT_T', gamertag: 'T_TGaboT_T', position: 'POR', teamName: 'Sangre Nueva FC', rating: 9.5, status: 'Atleta Titular', bio: 'Guardameta titular de Sangre Nueva FC. Reflejos bajo palos y salida de balón con el pie.' },
  };

  const matchedKnown = knownPlayers[normalizedId];

  // Construct player profile data dynamically
  const player: PlayerData = {
    id: playerId,
    name: activeUser?.name || matchedKnown?.name || playerId.replace(/[-_]/g, ' ').toUpperCase(),
    gamertag: activeUser?.gamertag || matchedKnown?.gamertag || playerId,
    position: resolvedPosition,
    secondaryPosition: resolvedSecPos,
    teamName: activeUser?.teamName || matchedKnown?.teamName || 'Escuadra Registrada',
    rating: Number(activeUser?.rating) || matchedKnown?.rating || 89,
    platform: activeUser?.platform || 'CROSSPLAY',
    gameSlug: gameSlug,
    status: activeUser?.status || matchedKnown?.status || 'Atleta Activo en Circuito',
    bio: activeUser?.biografia || matchedKnown?.bio || `Deportista eSports oficial compitiendo en el circuito profesional de ${game?.name || gameSlug.toUpperCase()}.`,
    gameId: activeUser?.gameProfiles?.[gameSlug]?.gameId || `${gameSlug.toUpperCase()}-ID #${playerId.substring(0, 6)}`,
    nacionalidad: activeUser?.nacionalidad || 'Chile',
    instagram: activeUser?.instagram,
    twitch: activeUser?.twitch,
    youtube: activeUser?.youtube,
    discord: activeUser?.discord,
    whatsapp: activeUser?.whatsapp,
    website: activeUser?.website,
    avatarUrl: activeUser?.avatarUrl || activeUser?.foto || matchedKnown?.avatarUrl || '/images/default/logo-default.png',
    bannerUrl: activeUser?.bannerUrl || matchedKnown?.bannerUrl || '/images/default/banner-default.jpg',
    stats: {
      matches: 42,
      goals: 24,
      assists: 15,
      mvps: 8,
      winrate: '79%',
    },
  };

  if (!game) {
    return (
      <div className="max-w-4xl mx-auto px-4 py-24 text-center">
        <h1 className="text-3xl font-bold mb-4 text-[var(--text-heading)]">Juego no encontrado</h1>
        <p className="text-[var(--text-muted)] mb-6">El juego solicitado no existe en nuestro catálogo eSports.</p>
        <Link href="/">
          <Button variant="primary">Volver al Inicio</Button>
        </Link>
      </div>
    );
  }

  return (
    <div
      className="min-h-screen pb-20 relative transition-all duration-500 bg-[var(--bg-main)] text-[var(--text-primary)]"
      style={{
        '--game-brand': game.brandColor,
        '--game-accent': game.accentColor,
      } as React.CSSProperties}
    >
      {/* Game Sub Navbar with 'jugadores' active section */}
      <GameSubNavbar game={game} activeSection="jugadores" />

      {/* Main Full Bleed Player Profile Banner Attached Directly to Sub-Navbar with Margin 0 / Padding 0 */}
      <div className="w-full pt-0 pb-6 relative">
        <PlayerProfileView player={player} brandColor={game.brandColor} />
      </div>
    </div>
  );
}

import React from 'react';
import Link from 'next/link';
import { queryDB } from '@/lib/db';
import { GAMES_CATALOG } from '@/lib/games-data';
import { Trophy } from 'lucide-react';

import { GameSubNavbar } from '@/components/layout/game-sub-navbar';
import { PublicCompetitionDetailView } from '@/components/tournaments/public-competition-detail-view';

export const revalidate = 0;

export default async function PublicCompetitionDetailPage({
  params,
}: {
  params: Promise<{ gameSlug: string; orgId: string; compId: string }>;
}) {
  const { gameSlug, orgId, compId } = await params;
  const gameConfig = GAMES_CATALOG[gameSlug] || GAMES_CATALOG['eafc26'];

  // Clean compId matching (supports exact compId or prefix matching)
  const compRows = await queryDB<any>(
    `SELECT c.*, 
            COALESCE(o.name, u_org.name, 'Organización Oficial') as org_name, 
            COALESCE(o.logo_url, u_org.logo_url, '/images/default/logo-default.png') as org_logo, 
            COALESCE(o.banner_url, u_org.banner_url, '/images/default/banner-default.jpg') as org_banner 
     FROM competitions c 
     LEFT JOIN users u ON c.organizer_id = u.id
     LEFT JOIN organizations o ON c.organization_id = o.id 
     LEFT JOIN organizations u_org ON u.organization_id = u_org.id
     WHERE (c.id = ? OR c.id LIKE ?) 
       AND (c.organization_id = ? OR u.organization_id = ? OR ? = 'all')
       AND c.game_slug = ?`,
    [compId, `${compId}%`, orgId, orgId, orgId, gameSlug]
  );

  if (!compRows || compRows.length === 0) {
    return (
      <div
        className="min-h-screen pb-20 relative transition-all duration-500 text-[var(--text-primary)] bg-[var(--bg-main)]"
        style={{
          '--game-brand': gameConfig.brandColor,
          '--game-accent': gameConfig.accentColor,
        } as React.CSSProperties}
      >
        <GameSubNavbar game={gameConfig} activeSection="organizaciones" />
        <div className="p-8 flex items-center justify-center">
          <div className="text-center space-y-4">
            <Trophy className="w-16 h-16 mx-auto text-[var(--text-muted)] opacity-50" />
            <h1 className="text-2xl font-black text-[var(--text-heading)] uppercase">Competencia no encontrada</h1>
            <Link href={`/${gameSlug}/organizacion/${orgId}`} className="text-[var(--accent-cyan)] hover:underline text-sm font-bold block">
              Volver a la Organización
            </Link>
          </div>
        </div>
      </div>
    );
  }

  const competition = compRows[0];
  const actualCompId = competition.id;

  const [teamRows, matchRows] = await Promise.all([
    queryDB<any>(
      `SELECT ct.*, t.logo_url as team_logo, t.captain_name 
       FROM competition_teams ct 
       LEFT JOIN teams t ON ct.team_id = t.id 
       WHERE ct.competition_id = ? AND ct.status = 'CONFIRMADO'`,
      [actualCompId]
    ),
    queryDB<any>(
      `SELECT m.*, 
              th.name as home_team_name, 
              th.tag as home_team_tag, 
              th.logo_url as home_logo, 
              ta.name as away_team_name, 
              ta.tag as away_team_tag, 
              ta.logo_url as away_logo 
       FROM matches m 
       LEFT JOIN teams th ON (m.team_home_id = th.id OR m.home_team_id = th.id) 
       LEFT JOIN teams ta ON (m.team_away_id = ta.id OR m.away_team_id = ta.id) 
       WHERE m.competition_id = ? OR m.tournament_id = ? 
       ORDER BY COALESCE(m.matchday_number, m.matchday, 1) ASC, m.created_at ASC`,
      [actualCompId, actualCompId]
    ),
  ]);

  return (
    <div
      className="min-h-screen pb-20 relative transition-all duration-500 text-[var(--text-primary)] bg-[var(--bg-main)]"
      style={{
        '--game-brand': gameConfig.brandColor,
        '--game-accent': gameConfig.accentColor,
      } as React.CSSProperties}
    >
      <GameSubNavbar game={gameConfig} activeSection="organizaciones" />

      <div className="relative w-full min-h-screen">
        <div className="standard-page-wrapper pt-0">
          <PublicCompetitionDetailView
            gameSlug={gameSlug}
            orgId={orgId}
            gameConfig={gameConfig}
            competition={competition}
            teams={teamRows}
            matches={matchRows}
          />
        </div>
      </div>
    </div>
  );
}

import React from 'react';
import Link from 'next/link';
import { queryDB } from '@/lib/db';
import { Building2 } from 'lucide-react';

import { GameSubNavbar } from '@/components/layout/game-sub-navbar';
import { GAMES_CATALOG } from '@/lib/games-data';
import { OrganizationProfileView } from '@/components/tournaments/organization-profile-view';

export default async function OrganizacionPage({ params }: { params: Promise<{ gameSlug: string; orgId: string }> }) {
  const { gameSlug, orgId } = await params;
  const gameConfig = GAMES_CATALOG[gameSlug] || GAMES_CATALOG['eafc26'];

  // 1. Fetch Organization Details
  const orgs = await queryDB<any>(
    `SELECT * FROM organizations WHERE id = ?`,
    [orgId]
  );
  const orgRaw = orgs[0];

  if (!orgRaw) {
    return (
      <div
        className="min-h-screen pb-20 relative transition-all duration-500 text-[var(--text-primary)] bg-[var(--bg-main)]"
        style={{
          '--game-brand': gameConfig.brandColor,
          '--game-accent': gameConfig.accentColor,
        } as React.CSSProperties}
      >
        <GameSubNavbar game={gameConfig} activeSection="organizaciones" />
        <div className="p-8 flex items-center justify-center">
          <div className="text-center space-y-4">
            <Building2 className="w-16 h-16 mx-auto text-[var(--text-muted)] opacity-50" />
            <h1 className="text-2xl font-black text-[var(--text-heading)] uppercase">Organización no encontrada</h1>
            <Link href={`/${gameSlug}/organizaciones`} className="text-[var(--accent-cyan)] hover:underline text-sm font-bold block">
              Volver al directorio
            </Link>
          </div>
        </div>
      </div>
    );
  }

  // Parse JSON fields safely
  const org = {
    ...orgRaw,
    logoUrl: orgRaw.logo_url || orgRaw.logoUrl || '/images/default/logo-default.png',
    bannerUrl: orgRaw.banner_url || orgRaw.bannerUrl || gameConfig.bannerUrl || '/images/default/banner-default.jpg',
    foundedYear: orgRaw.founded_year || orgRaw.foundedYear || '2022',
    allowedGames: orgRaw.allowed_games ? (typeof orgRaw.allowed_games === 'string' ? JSON.parse(orgRaw.allowed_games) : orgRaw.allowed_games) : ['eafc26', 'valorant'],
    socialMedia: orgRaw.redes_sociales ? (typeof orgRaw.redes_sociales === 'string' ? JSON.parse(orgRaw.redes_sociales) : orgRaw.redes_sociales) : {},
  };

  // 2. Fetch Competitions owned by this Org
  const competitions = await queryDB<any>(
    `SELECT c.*, 
            (SELECT COUNT(*) FROM matches m WHERE m.competition_id = c.id OR m.tournament_id = c.id) as total_matches,
            (SELECT COUNT(*) FROM matches m WHERE (m.competition_id = c.id OR m.tournament_id = c.id) AND m.status = 'FINALIZADO') as finished_matches
     FROM competitions c 
     LEFT JOIN users u ON c.organizer_id = u.id
     WHERE (c.organization_id = ? OR u.organization_id = ?) 
       AND c.game_slug = ? 
       AND c.status != 'Borrador' 
     ORDER BY c.created_at DESC`,
    [orgId, orgId, gameSlug]
  );

  // 3. Fetch Assigned Organizers
  const organizers = await queryDB<any>(
    `SELECT id, name, gamertag, email, role, avatar_url 
     FROM users 
     WHERE organization_id = ? AND role = 'Organizador'`,
    [orgId]
  );

  // 4. Fetch Affiliated Teams
  const teams = await queryDB<any>(
    `SELECT t.*, COALESCE(t.members_count, 1) as player_count
     FROM teams t 
     WHERE t.organization_id = ? OR t.game_slug = ?
     ORDER BY t.name ASC 
     LIMIT 12`,
    [orgId, gameSlug]
  );

  // 5. Fetch Recent & Live Matches
  const matches = await queryDB<any>(
    `SELECT m.*, 
            c.name as competition_name,
            COALESCE(th.name, m.home_team_name) as home_team_name,
            COALESCE(th.tag, UPPER(LEFT(COALESCE(th.name, m.home_team_name, 'LOC'), 3))) as home_team_tag,
            th.logo_url as home_logo,
            COALESCE(ta.name, m.away_team_name) as away_team_name,
            COALESCE(ta.tag, UPPER(LEFT(COALESCE(ta.name, m.away_team_name, 'VIS'), 3))) as away_team_tag,
            ta.logo_url as away_logo
     FROM matches m
     LEFT JOIN competitions c ON (m.competition_id = c.id OR m.tournament_id = c.id)
     LEFT JOIN teams th ON (m.team_home_id = th.id OR m.home_team_id = th.id)
     LEFT JOIN teams ta ON (m.team_away_id = ta.id OR m.away_team_id = ta.id)
     LEFT JOIN users u ON c.organizer_id = u.id
     WHERE (c.organization_id = ? OR u.organization_id = ?)
       AND c.game_slug = ?
     ORDER BY m.scheduled_at DESC
     LIMIT 8`,
    [orgId, orgId, gameSlug]
  );

  return (
    <div
      className="min-h-screen pb-20 relative transition-all duration-500 text-[var(--text-primary)] bg-[var(--bg-main)]"
      style={{
        '--game-brand': gameConfig.brandColor,
        '--game-accent': gameConfig.accentColor,
      } as React.CSSProperties}
    >
      <GameSubNavbar game={gameConfig} activeSection="organizaciones" />

      <div className="relative w-full min-h-screen">
        <div className="standard-page-wrapper pt-0">
          <OrganizationProfileView
            gameSlug={gameSlug}
            gameConfig={gameConfig}
            org={org}
            competitions={competitions}
            organizers={organizers}
            teams={teams}
            matches={matches}
          />
        </div>
      </div>
    </div>
  );
}

import { queryDB } from '@/lib/db';
import { authorizationErrorResponse, requireRequestActor } from '@/lib/auth-server';
import { teamCreateBodySchema, teamUpdateBodySchema } from '@/lib/api-schemas';
import { canManageTeam, isAdministrator } from '@/lib/authorization';
import {
  TeamRow,
  mapTeamRowToData,
  apiSuccess,
  apiError,
  parsePaginationParams,
  buildPaginationMeta,
} from '@/lib/api-types';
import { createTeamService, updateManagedTeamService } from '@/lib/services';

async function loadTeamScope(teamId: string) {
  const teams = await queryDB<{
    organization_id: string | null;
    captain_id: string | null;
    encargados_json: string | null;
  }>('SELECT organization_id, captain_id, encargados_json FROM teams WHERE id = ? LIMIT 1', [teamId]);
  const team = teams[0];
  if (!team) return null;

  const managers = await queryDB<{ user_id: string }>(
    `SELECT user_id FROM team_members
      WHERE team_id = ? AND role_in_team IN ('Capitan', 'Capitán', 'Encargado', 'DT / Analyst', 'Manager', 'Co-Capitán')`,
    [teamId],
  );
  return {
    organizationId: team.organization_id,
    captainId: team.captain_id,
    managerIds: managers.map((manager) => manager.user_id),
  };
}

// GET /api/teams — List teams with optional game filter and pagination
export async function GET(request: Request) {
  const { searchParams } = new URL(request.url);
  const gameSlug = searchParams.get('gameSlug');
  const { page, limit } = parsePaginationParams(searchParams);

  try {
    let whereSql = '';
    const params: (string | number)[] = [];

    if (gameSlug && !['ALL', 'all', 'TODOS', 'todas'].includes(gameSlug)) {
      whereSql = ' WHERE game_slug = ?';
      params.push(gameSlug);
    }

    // Count total
    const countResult = await queryDB<{ total: number }>(`SELECT COUNT(*) as total FROM teams${whereSql}`, [...params]);
    const total = countResult[0]?.total || 0;

    // Paginated query
    const offset = (page - 1) * limit;
    const rows = await queryDB<TeamRow>(
      `SELECT * FROM teams${whereSql} ORDER BY created_at DESC LIMIT ? OFFSET ?`,
      [...params, limit, offset]
    );

    const teams = rows.map(mapTeamRowToData);
    const meta = buildPaginationMeta(page, limit, total);

    return apiSuccess({ teams }, undefined, meta);
  } catch {
    // If table doesn't exist yet, return clean empty list
    return apiSuccess({ teams: [] });
  }
}

// POST /api/teams — Create team
export async function POST(request: Request) {
  try {
    const actor = await requireRequestActor(request);

    const parsedBody = teamCreateBodySchema.safeParse(await request.json());
    if (!parsedBody.success) return apiError('Nombre y tag del equipo son requeridos', 400);
    const body = parsedBody.data;
    const { id, name, tag, gameSlug, captainId, captainName, platform, color, logoText, logoUrl, bannerUrl, description, vacantPositions } = body;

    if (!name || !tag) {
      return apiError('Nombre y tag del equipo son requeridos', 400);
    }

    const teamId = id || undefined;
    const teamDesc = description || 'Escuadra oficial del circuito eSports.';

    // Check if user already owns a team in this discipline
    const existingById = teamId
      ? await queryDB<{ id: string }>('SELECT id FROM teams WHERE id = ? LIMIT 1', [teamId])
      : [];
    if (existingById.length > 0) {
      return apiError('Ya existe un equipo con ese ID', 409, 'DUPLICATE_TEAM');
    }

    const effectiveCaptainId = isAdministrator(actor) && captainId ? captainId : actor.userId;
    const captainUsers = await queryDB<{ name: string; gamertag: string }>(
      'SELECT name, gamertag FROM users WHERE id = ? LIMIT 1',
      [effectiveCaptainId],
    );
    const effectiveCaptainName = isAdministrator(actor) && captainName
      ? captainName
      : (captainUsers[0]?.gamertag || captainUsers[0]?.name || 'Capitán');
    const allowedGames = ['eafc26', 'valorant', 'csgo', 'lol', 'rocketleague', 'fortnite'] as const;
    const effectiveGameSlug = allowedGames.find((slug) => slug === gameSlug) || 'eafc26';
    const allowedPlatforms = ['PS5', 'PS4', 'XBOX', 'PC', 'CROSSPLAY'] as const;
    const effectivePlatform = allowedPlatforms.find((item) => item === platform) || 'CROSSPLAY';
    const result = await createTeamService({
      id: teamId,
      name,
      tag: tag || 'TP',
      gameSlug: effectiveGameSlug,
      platform: effectivePlatform,
      color: color || '#00F0FF',
      logoText: logoText || 'TP',
      logoUrl: logoUrl || null,
      bannerUrl: bannerUrl || null,
      description: teamDesc,
      vacantPositions: vacantPositions || [],
    }, effectiveCaptainId, effectiveCaptainName);
    if (!result.success) return apiError(result.error || 'No se pudo crear el equipo', 409, result.code);
    return apiSuccess({ team: result.team }, 'Equipo creado exitosamente');
  } catch (error: unknown) {
    const authResponse = authorizationErrorResponse(error);
    if (authResponse) return authResponse;
    console.error('Teams POST error:', error);
    const message = error instanceof Error ? error.message : 'Error guardando equipo';
    return apiError(message, 500);
  }
}

// PUT /api/teams — Update team
export async function PUT(request: Request) {
  try {
    const actor = await requireRequestActor(request);
    const parsedBody = teamUpdateBodySchema.safeParse(await request.json());
    if (!parsedBody.success) return apiError('ID del club requerido', 400);
    const body = parsedBody.data;
    const { id, name, tag, description, platform, clubIdEa, socialMedia, color, logoText, logoUrl, bannerUrl, status, gameSlug, captainId, captainName } = body;

    const teamId = (id || '').trim().slice(0, 36);
    if (!teamId) {
      return apiError('ID del club requerido', 400);
    }

    // Check if team exists and enforce ownership before applying changes
    const existingRows = await queryDB<TeamRow>('SELECT * FROM teams WHERE id = ?', [teamId]);
    const existingTeam = existingRows[0];
    if (!existingTeam) {
      return apiError('Equipo no encontrado', 404);
    }
    const t = existingTeam;
    const teamScope = await loadTeamScope(teamId);
    if (!teamScope || !canManageTeam(actor, teamScope)) {
      return apiError('No tienes permisos para gestionar este equipo', 403, 'FORBIDDEN');
    }

    const safeName = (name ?? t?.name ?? 'Escuadra Pro').slice(0, 100);
    const safeTag = (tag ?? t?.tag ?? 'TP').slice(0, 10);
    const safeDescription = description ?? t.description ?? 'Escuadra oficial del circuito eSports.';
    const safePlatform = (platform ?? t?.platform ?? 'CROSSPLAY').slice(0, 20);
    const safeColor = (color ?? t?.color ?? '#00F0FF').slice(0, 20);
    const safeLogoText = (logoText ?? t?.logo_text ?? safeTag ?? 'TP').slice(0, 5);
    const safeStatus = status ?? t.status ?? 'Escuadra Activa';
    const safeLogoUrl = (logoUrl && typeof logoUrl === 'string' && logoUrl.trim() !== '') ? logoUrl : (t?.logo_url || '');
    const safeBannerUrl = (bannerUrl && typeof bannerUrl === 'string' && bannerUrl.trim() !== '') ? bannerUrl : (t?.banner_url || '');
    const safeGameSlug = (gameSlug || t?.game_slug || 'eafc26').slice(0, 50);
    let safeCaptainId = (isAdministrator(actor) ? captainId : null) ?? t.captain_id ?? actor.userId;
    safeCaptainId = safeCaptainId.slice(0, 36);
    const safeCaptainName = ((isAdministrator(actor) ? captainName : null) ?? t.captain_name ?? actor.userId).slice(0, 100);

    // Validate captain exists
    try {
      const userCheck = await queryDB<{ id: string }>('SELECT id FROM users WHERE id = ?', [safeCaptainId]);
      if (!userCheck || userCheck.length === 0) {
        const firstUser = await queryDB<{ id: string }>('SELECT id FROM users ORDER BY created_at ASC LIMIT 1');
        if (firstUser && firstUser.length > 0) {
          safeCaptainId = firstUser[0].id;
        }
      }
    } catch { /* ignore */ }

    const result = await updateManagedTeamService(teamId, {
      name: safeName,
      tag: safeTag,
      description: safeDescription,
      platform: safePlatform,
      color: safeColor,
      logoText: safeLogoText,
      status: safeStatus,
      clubIdEa: clubIdEa || '',
      logoUrl: safeLogoUrl,
      bannerUrl: safeBannerUrl,
      captainId: isAdministrator(actor) && captainId !== undefined ? safeCaptainId : undefined,
      captainName: isAdministrator(actor) && captainName !== undefined ? safeCaptainName : undefined,
      gameSlug: safeGameSlug,
    });
    if (!result.success) return apiError(result.error || 'No se pudo actualizar el equipo', 409);

    return apiSuccess({
      team: {
        id: teamId, name: safeName, tag: safeTag, gameSlug: safeGameSlug,
        platform: safePlatform, color: safeColor, logoText: safeLogoText,
        description: safeDescription, status: safeStatus,
        logoUrl: safeLogoUrl, bannerUrl: safeBannerUrl,
      }
    }, 'Ajustes del club actualizados con éxito');
  } catch (error: unknown) {
    const authResponse = authorizationErrorResponse(error);
    if (authResponse) return authResponse;
    console.error('Teams PUT error:', error);
    const message = error instanceof Error ? error.message : 'Error guardando equipo';
    return apiError(message, 500);
  }
}

'use client';

import React, { useState, useEffect } from 'react';
import { useAuth } from '@/components/providers/auth-provider';
import { PageHeader } from '@/components/ui/page-header';
import { Settings } from 'lucide-react';
import { ClubSettingsView } from '@/components/club/club-settings-view';
import { TeamData } from '@/lib/data-store';

export default function ClubAjustesPage() {
  const { currentUser, activeGameSlug } = useAuth();
  const [userTeam, setUserTeam] = useState<TeamData | null>(null);

  const fetchTeam = () => {
    fetch(`/api/teams?gameSlug=${activeGameSlug || 'eafc26'}`)
      .then((res) => res.json())
      .then((data) => {
        if (data.success && Array.isArray(data.teams)) {
          const found = data.teams.find(
            (t: TeamData) =>
              t.id === currentUser?.teamId ||
              (currentUser?.teamName && t.name.toLowerCase() === currentUser.teamName.toLowerCase()) ||
              t.captainId === currentUser?.id
          );
          if (found) {
            setUserTeam(found);
          }
        }
      })
      .catch((err) => console.error('Error fetching team for club settings:', err));
  };

  useEffect(() => {
    fetchTeam();
  }, [activeGameSlug, currentUser]);

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-8 animate-in fade-in duration-300">
      <PageHeader
        badgeText="Configuración de Marca & Identidad Institucional"
        badgeIcon={<Settings className="w-3.5 h-3.5 text-purple-400" />}
        title="AJUSTES DEL"
        highlightTitle="CLUB."
        description="Modifica el logo oficial WebP, banner panorámico de portada, etiqueta tag, redes sociales y parámetros eSports de la escuadra en MySQL."
      />

      <ClubSettingsView
        team={userTeam}
        activeGameSlug={activeGameSlug || 'eafc26'}
        refetchTeams={fetchTeam}
      />
    </div>
  );
}

'use client';

import React, { useState, useTransition } from 'react';
import Link from 'next/link';
import { GAMES_CATALOG } from '@/lib/games-data';
import { CompetitionData, CompetitionTeamData } from '@/app/actions/competitions';
import {
  enrollTeamAction,
  removeEnrolledTeamAction,
  generateFixtureAction,
  updateCompetitionStatusAction,
  CompetitionStatus,
} from '@/app/actions/competitions';
import { CrudAlertBanner, useCrudNotifier } from '@/components/ui/crud-alert';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Card } from '@/components/ui/card';
import {
  Trophy, Calendar, Shield, Settings, Plus, Trash2, ArrowLeft, Play, Swords
} from 'lucide-react';

interface CompetitionDetailClientProps {
  competition: CompetitionData;
  enrolledTeams: CompetitionTeamData[];
  availableTeams: any[];
  matches: any[];
}

export function CompetitionDetailClient({
  competition,
  enrolledTeams,
  availableTeams,
  matches,
}: CompetitionDetailClientProps) {
  const [activeTab, setActiveTab] = useState<'fixture' | 'standings' | 'teams' | 'settings'>('fixture');
  const [selectedTeamToEnroll, setSelectedTeamToEnroll] = useState<string>('');
  const [isPending, startTransition] = useTransition();
  const { crudState, startOperation, endSuccess, endError, resetAlert } = useCrudNotifier();

  const gameConfig = GAMES_CATALOG[competition.game_slug] || GAMES_CATALOG['eafc26'];
  const brandColor = gameConfig?.brandColor || '#00F0FF';

  // 1. Inscribir Equipo
  const handleEnrollTeam = () => {
    if (!selectedTeamToEnroll) return;
    const teamObj = availableTeams.find((t) => t.id === selectedTeamToEnroll);
    if (!teamObj) return;

    startOperation(`Inscripción de Equipo: ${teamObj.name}`);
    startTransition(async () => {
      const res = await enrollTeamAction(competition.id, teamObj.id, teamObj.name, teamObj.tag);
      if (res.success) {
        setSelectedTeamToEnroll('');
        endSuccess(res.message || 'Equipo inscrito correctamente.');
      } else {
        endError(res.error || 'Error al inscribir equipo.');
      }
    });
  };

  // 2. Retirar Equipo
  const handleRemoveTeam = (teamId: string, teamName: string) => {
    startOperation(`Retiro de Equipo: ${teamName}`);
    startTransition(async () => {
      const res = await removeEnrolledTeamAction(competition.id, teamId);
      if (res.success) {
        endSuccess(res.message || 'Equipo retirado.');
      } else {
        endError(res.error || 'Error al retirar equipo.');
      }
    });
  };

  // 3. Generar Fixture
  const handleGenerateFixture = () => {
    startOperation(`Generación de Fixture: ${competition.name}`);
    startTransition(async () => {
      const res = await generateFixtureAction(competition.id);
      if (res.success) {
        endSuccess((res as any).message || 'Fixture generado exitosamente.');
      } else {
        endError(res.error || 'Error al generar fixture.');
      }
    });
  };

  // 4. Cambiar Estado
  const handleStatusChange = (newStatus: CompetitionStatus) => {
    startOperation(`Cambio de Estado a: ${newStatus}`);
    startTransition(async () => {
      const res = await updateCompetitionStatusAction(competition.id, newStatus);
      if (res.success) {
        endSuccess(res.message || 'Estado actualizado.');
      } else {
        endError(res.error || 'Error al actualizar estado.');
      }
    });
  };

  // Standings calculation mock based on matches
  const standingsMap: Record<string, { name: string; tag: string; pj: number; pg: number; pe: number; pp: number; gf: number; gc: number; pts: number }> = {};
  enrolledTeams.forEach((t) => {
    standingsMap[t.team_id] = { name: t.team_name, tag: t.team_tag || 'TEAM', pj: 0, pg: 0, pe: 0, pp: 0, gf: 0, gc: 0, pts: 0 };
  });

  matches.forEach((m) => {
    if (m.status === 'TERMINADO' && m.reported_score_home !== null && m.reported_score_away !== null) {
      const h = standingsMap[m.home_team_id];
      const a = standingsMap[m.away_team_id];
      if (h && a) {
        h.pj += 1;
        a.pj += 1;
        h.gf += m.reported_score_home;
        h.gc += m.reported_score_away;
        a.gf += m.reported_score_away;
        a.gc += m.reported_score_home;

        if (m.reported_score_home > m.reported_score_away) {
          h.pg += 1;
          h.pts += 3;
          a.pp += 1;
        } else if (m.reported_score_home < m.reported_score_away) {
          a.pg += 1;
          a.pts += 3;
          h.pp += 1;
        } else {
          h.pe += 1;
          a.pe += 1;
          h.pts += 1;
          a.pts += 1;
        }
      }
    }
  });

  const standingsList = Object.values(standingsMap).sort((a, b) => b.pts - a.pts || (b.gf - b.gc) - (a.gf - a.gc));

  // Filter available teams that are not yet enrolled
  const enrolledSet = new Set(enrolledTeams.map((t) => t.team_id));
  const availableToEnroll = availableTeams.filter((t) => !enrolledSet.has(t.id));

  // Group matches by matchday
  const matchesByMatchday: Record<number, any[]> = {};
  matches.forEach((m) => {
    const num = m.matchday_number || m.matchday || 1;
    if (!matchesByMatchday[num]) matchesByMatchday[num] = [];
    matchesByMatchday[num].push(m);
  });

  return (
    <div className="space-y-6">
      <CrudAlertBanner state={crudState} onClose={resetAlert} />

      {/* Header Banner & Breadcrumb */}
      <div className="flex items-center justify-between">
        <Link
          href="/dashboard/competencias"
          className="text-xs font-bold text-slate-400 hover:text-cyan-400 flex items-center gap-1.5 transition-colors"
        >
          <ArrowLeft className="w-4 h-4" />
          <span>Volver al Listado de Competencias</span>
        </Link>

        <Badge variant={competition.status === 'Activo' ? 'emerald' : competition.status === 'Borrador' ? 'gold' : 'rose'} className="text-xs uppercase font-mono font-black">
          {competition.status}
        </Badge>
      </div>

      {/* Competition Identity Card */}
      <Card className="p-6 bg-slate-950 border border-purple-500/30 space-y-4 shadow-2xl relative overflow-hidden">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div className="flex items-center gap-4">
            <div
              className="w-16 h-16 rounded-2xl bg-slate-900 border-2 flex items-center justify-center font-black text-2xl shadow-xl flex-shrink-0"
              style={{ borderColor: brandColor, color: brandColor }}
            >
              {gameConfig?.icon || '🏆'}
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h1 className="text-xl sm:text-2xl font-black text-white uppercase tracking-wider">{competition.name}</h1>
                <span className="px-2 py-0.5 rounded text-[10px] font-mono font-bold uppercase bg-purple-950 text-purple-300 border border-purple-500/40">
                  {gameConfig?.name}
                </span>
              </div>
              <p className="text-xs text-slate-400 font-mono mt-1 flex items-center gap-3 flex-wrap">
                <span>Formato: <strong className="text-cyan-300">{competition.mode_format}</strong></span>
                <span>• Inicio: <strong className="text-emerald-400">{new Date(competition.fecha_inicio).toLocaleDateString('es-ES')}</strong></span>
                <span>• Término: <strong className="text-slate-300">{competition.fecha_termino ? new Date(competition.fecha_termino).toLocaleDateString('es-ES') : 'TBD (Nullable)'}</strong></span>
              </p>
            </div>
          </div>

          {/* Quick Action Button: Generar Fixture */}
          <Button
            onClick={handleGenerateFixture}
            disabled={isPending || enrolledTeams.length < 2}
            className="bg-emerald-600 hover:bg-emerald-500 text-slate-950 font-black text-xs px-4 py-3 rounded-xl shadow-xl flex items-center gap-2"
          >
            <Play className="w-4 h-4 fill-slate-950" />
            <span>Generar / Regenerar Fixture</span>
          </Button>
        </div>
      </Card>

      {/* Tabs Navigation */}
      <div className="flex items-center gap-2 border-b border-white/10 pb-3 overflow-x-auto scrollbar-none">
        <button
          onClick={() => setActiveTab('fixture')}
          className={`px-4 py-2.5 rounded-xl text-xs font-black transition-all flex items-center gap-2 flex-shrink-0 ${
            activeTab === 'fixture' ? 'bg-cyan-500 text-slate-950 shadow-lg' : 'bg-slate-900 border border-white/10 text-slate-300'
          }`}
        >
          <Calendar className="w-4 h-4" />
          1. Fixture & Partidos ({matches.length})
        </button>

        <button
          onClick={() => setActiveTab('standings')}
          className={`px-4 py-2.5 rounded-xl text-xs font-black transition-all flex items-center gap-2 flex-shrink-0 ${
            activeTab === 'standings' ? 'bg-purple-600 text-white shadow-lg' : 'bg-slate-900 border border-white/10 text-slate-300'
          }`}
        >
          <Trophy className="w-4 h-4" />
          2. Tabla de Posiciones
        </button>

        <button
          onClick={() => setActiveTab('teams')}
          className={`px-4 py-2.5 rounded-xl text-xs font-black transition-all flex items-center gap-2 flex-shrink-0 ${
            activeTab === 'teams' ? 'bg-emerald-600 text-slate-950 shadow-lg' : 'bg-slate-900 border border-white/10 text-slate-300'
          }`}
        >
          <Shield className="w-4 h-4" />
          3. Inscripción de Equipos ({enrolledTeams.length})
        </button>

        <button
          onClick={() => setActiveTab('settings')}
          className={`px-4 py-2.5 rounded-xl text-xs font-black transition-all flex items-center gap-2 flex-shrink-0 ${
            activeTab === 'settings' ? 'bg-amber-600 text-white shadow-lg' : 'bg-slate-900 border border-white/10 text-slate-300'
          }`}
        >
          <Settings className="w-4 h-4" />
          4. Configuración & Estado
        </button>
      </div>

      {/* TAB 1: FIXTURE & CALENDARIO */}
      {activeTab === 'fixture' && (
        <div className="space-y-6">
          {Object.keys(matchesByMatchday).length === 0 ? (
            <Card className="p-8 text-center bg-slate-950 border border-white/10 space-y-3">
              <Swords className="w-10 h-10 text-slate-500 mx-auto" />
              <h3 className="text-sm font-black uppercase text-white">No se ha generado el fixture todavía</h3>
              <p className="text-xs text-slate-400 max-w-md mx-auto">
                Inscribe al menos 2 equipos en la pestaña de inscripción y presiona &quot;Generar Fixture&quot; para construir el calendario automático.
              </p>
            </Card>
          ) : (
            Object.entries(matchesByMatchday).map(([jornada, matchGroup]) => (
              <div key={jornada} className="space-y-3">
                <h3 className="text-xs font-black uppercase text-cyan-400 tracking-wider flex items-center gap-2">
                  <Calendar className="w-3.5 h-3.5" />
                  Jornada {jornada} ({matchGroup.length} Partidos)
                </h3>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                  {matchGroup.map((m) => {
                    const homeName = m.home_team_name || m.home_team_id || m.team_home_id || 'Equipo Local';
                    const awayName = m.away_team_name || m.away_team_id || m.team_away_id || 'Equipo Visitante';
                    const homeScore = m.reported_score_home ?? m.score_home;
                    const awayScore = m.reported_score_away ?? m.score_away;
                    const isTerminado = m.status === 'TERMINADO' && homeScore !== null && awayScore !== null;

                    return (
                      <div key={m.id} className="p-3.5 rounded-xl bg-slate-950 border border-white/10 flex items-center justify-between gap-3 shadow-md">
                        <div className="flex-1 text-right font-black text-xs text-white truncate">
                          {homeName}
                        </div>

                        <div className="px-3 py-1 rounded-lg bg-slate-900 border border-purple-500/40 font-mono text-xs font-bold text-center flex-shrink-0">
                          {isTerminado ? (
                            <span className="text-emerald-400 font-black">{homeScore} - {awayScore}</span>
                          ) : (
                            <span className="text-slate-400">VS</span>
                          )}
                        </div>

                        <div className="flex-1 text-left font-black text-xs text-white truncate">
                          {awayName}
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            ))
          )}
        </div>
      )}

      {/* TAB 2: TABLA DE POSICIONES */}
      {activeTab === 'standings' && (
        <Card className="p-4 bg-slate-950 border border-white/10 overflow-x-auto">
          <table className="w-full text-left text-xs font-mono">
            <thead>
              <tr className="border-b border-white/10 text-slate-400 text-[10px] uppercase">
                <th className="p-2"># Pos</th>
                <th className="p-2">Escuadra</th>
                <th className="p-2 text-center">PJ</th>
                <th className="p-2 text-center">PG</th>
                <th className="p-2 text-center">PE</th>
                <th className="p-2 text-center">PP</th>
                <th className="p-2 text-center">GF</th>
                <th className="p-2 text-center">GC</th>
                <th className="p-2 text-center">DIF</th>
                <th className="p-2 text-center text-cyan-400 font-black">PTS</th>
              </tr>
            </thead>
            <tbody>
              {standingsList.map((st, idx) => (
                <tr key={st.name} className="border-b border-white/5 hover:bg-slate-900/50">
                  <td className="p-2 font-bold text-slate-400">{idx + 1}</td>
                  <td className="p-2 font-black text-white">{st.name} <span className="text-[10px] text-cyan-400">[{st.tag}]</span></td>
                  <td className="p-2 text-center text-slate-300">{st.pj}</td>
                  <td className="p-2 text-center text-emerald-400 font-bold">{st.pg}</td>
                  <td className="p-2 text-center text-amber-400">{st.pe}</td>
                  <td className="p-2 text-center text-rose-400">{st.pp}</td>
                  <td className="p-2 text-center text-slate-300">{st.gf}</td>
                  <td className="p-2 text-center text-slate-300">{st.gc}</td>
                  <td className="p-2 text-center text-slate-300">{st.gf - st.gc}</td>
                  <td className="p-2 text-center font-black text-cyan-300 text-sm">{st.pts}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </Card>
      )}

      {/* TAB 3: INSCRIPCIÓN DE EQUIPOS */}
      {activeTab === 'teams' && (
        <div className="space-y-6">
          {/* Formulario de Agregar Equipo Existente */}
          <Card className="p-4 bg-slate-950 border border-purple-500/30 space-y-3">
            <h3 className="text-xs font-black uppercase text-purple-300 flex items-center gap-2">
              <Plus className="w-4 h-4 text-purple-400" />
              Inscribir Club Existente en esta Competencia
            </h3>

            <div className="flex flex-col sm:flex-row items-center gap-3">
              <select
                value={selectedTeamToEnroll}
                onChange={(e) => setSelectedTeamToEnroll(e.target.value)}
                className="w-full sm:flex-1 p-2.5 rounded-xl bg-slate-900 border border-white/10 text-white font-mono text-xs outline-none"
              >
                <option value="">-- Seleccionar Equipo Disponible --</option>
                {availableToEnroll.map((t) => (
                  <option key={t.id} value={t.id}>
                    {t.name} [{t.tag}] — ({t.platform})
                  </option>
                ))}
              </select>

              <Button
                onClick={handleEnrollTeam}
                disabled={isPending || !selectedTeamToEnroll}
                className="w-full sm:w-auto bg-purple-600 hover:bg-purple-500 text-white font-black text-xs px-5 py-2.5 rounded-xl shadow-lg"
              >
                Inscribir Club
              </Button>
            </div>
          </Card>

          {/* Lista de Equipos Inscritos */}
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
            {enrolledTeams.map((t) => (
              <div key={t.id} className="p-3.5 rounded-xl bg-slate-950 border border-white/10 flex items-center justify-between shadow-md">
                <div className="flex items-center gap-3">
                  <div className="w-8 h-8 rounded-lg bg-slate-900 border border-emerald-500/40 flex items-center justify-center font-black text-xs text-emerald-400">
                    {t.team_tag || 'TEAM'}
                  </div>
                  <div>
                    <h4 className="font-black text-xs text-white">{t.team_name}</h4>
                    <span className="text-[10px] font-mono text-emerald-400 font-bold">✓ {t.status}</span>
                  </div>
                </div>

                <Button
                  size="sm"
                  variant="ghost"
                  onClick={() => handleRemoveTeam(t.team_id, t.team_name)}
                  className="text-xs text-rose-400 hover:bg-rose-950 p-2"
                  title="Retirar equipo"
                >
                  <Trash2 className="w-3.5 h-3.5" />
                </Button>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* TAB 4: CONFIGURACIÓN & ESTADOS (SOFT DELETE) */}
      {activeTab === 'settings' && (
        <Card className="p-6 bg-slate-950 border border-white/10 space-y-4">
          <h3 className="text-sm font-black uppercase text-white flex items-center gap-2">
            <Settings className="w-4 h-4 text-amber-400" />
            Control de Estado de la Competencia (Soft Delete)
          </h3>

          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3 pt-2">
            <Button
              onClick={() => handleStatusChange('Borrador')}
              disabled={competition.status === 'Borrador'}
              className="bg-amber-950 text-amber-300 border border-amber-500/40 hover:bg-amber-900 text-xs font-black py-3 rounded-xl"
            >
              Set a BORRADOR
            </Button>

            <Button
              onClick={() => handleStatusChange('Activo')}
              disabled={competition.status === 'Activo'}
              className="bg-emerald-950 text-emerald-300 border border-emerald-500/40 hover:bg-emerald-900 text-xs font-black py-3 rounded-xl"
            >
              Set a ACTIVO
            </Button>

            <Button
              onClick={() => handleStatusChange('Finalizado')}
              disabled={competition.status === 'Finalizado'}
              className="bg-purple-950 text-purple-300 border border-purple-500/40 hover:bg-purple-900 text-xs font-black py-3 rounded-xl"
            >
              Set a FINALIZADO
            </Button>

            <Button
              onClick={() => handleStatusChange('Deshabilitado')}
              disabled={competition.status === 'Deshabilitado'}
              className="bg-rose-950 text-rose-300 border border-rose-500/40 hover:bg-rose-900 text-xs font-black py-3 rounded-xl"
            >
              DESHABILITAR (Soft Delete)
            </Button>
          </div>
        </Card>
      )}
    </div>
  );
}

'use client';

import React, { useState, useTransition } from 'react';
import { useSearchParams, useRouter, usePathname } from 'next/navigation';
import { GAMES_CATALOG } from '@/lib/games-data';
import { CompetitionData, CompetitionTeamData } from '@/app/actions/competitions';
import {
  enrollTeamAction,
  enrollIndividualAthleteAction,
  removeEnrolledTeamAction,
  updateCompetitionStatusAction,
  CompetitionStatus,
} from '@/app/actions/competitions';
import { FixtureGenerator } from './fixture-generator';
import { FixtureScheduleView } from '@/components/tournaments/fixture-schedule-view';
import { ClassificationView } from '@/components/tournaments/classification-view';
import { CrudAlertBanner, useCrudNotifier } from '@/components/ui/crud-alert';
import { Button } from '@/components/ui/button';
import { Card } from '@/components/ui/card';
import {
  Trophy, Calendar, Shield, Settings, Users, Plus, Trash2, Activity, Zap, Check, UserCheck
} from 'lucide-react';

interface CompetitionTabsProps {
  competition: CompetitionData;
  enrolledTeams: CompetitionTeamData[];
  availableTeams: any[];
  availableUsers?: any[];
  isIndividual?: boolean;
  matches: any[];
}

export type CompetitionTabType = 'dashboard' | 'fixture' | 'standings' | 'teams' | 'settings';

export function CompetitionTabs({
  competition,
  enrolledTeams,
  availableTeams,
  availableUsers = [],
  isIndividual = false,
  matches,
}: CompetitionTabsProps) {
  const searchParams = useSearchParams();
  const router = useRouter();
  const pathname = usePathname();

  // Persistir la pestaña activa en la URL (?tab=...)
  const activeTab = (searchParams.get('tab') as CompetitionTabType) || 'dashboard';

  const setActiveTab = (tab: CompetitionTabType) => {
    const params = new URLSearchParams(searchParams.toString());
    params.set('tab', tab);
    router.push(`${pathname}?${params.toString()}`, { scroll: false });
  };

  const [selectedTeamToEnroll, setSelectedTeamToEnroll] = useState<string>('');
  const [isPending, startTransition] = useTransition();
  const { crudState, startOperation, endSuccess, endError, resetAlert } = useCrudNotifier();

  const gameConfig = GAMES_CATALOG[competition.game_slug] || GAMES_CATALOG['eafc26'];

  // Metrics calculation
  const totalMatches = matches.length;
  const playedMatches = matches.filter((m) => m.status === 'TERMINADO' || m.status === 'FINALIZADO').length;
  const pendingMatches = totalMatches - playedMatches;
  const progressPercent = totalMatches > 0 ? Math.round((playedMatches / totalMatches) * 100) : 0;

  // 1. Inscribir Equipo
  const handleEnrollTeam = () => {
    if (!selectedTeamToEnroll) return;
    const teamObj = availableTeams.find((t) => t.id === selectedTeamToEnroll);
    if (!teamObj) return;

    startOperation(`Inscripción de Equipo: ${teamObj.name}`);
    startTransition(async () => {
      const res = await enrollTeamAction(competition.id, teamObj.id, teamObj.name, teamObj.tag);
      if (res.success) {
        setSelectedTeamToEnroll('');
        endSuccess(res.message || 'Equipo inscrito correctamente.');
      } else {
        endError(res.error || 'Error al inscribir equipo.');
      }
    });
  };

  // 1.1 Inscribir Atleta Individual (1v1 / 2v2 / Solo / Duos)
  const handleEnrollAthlete = () => {
    if (!selectedTeamToEnroll) return;
    const userObj = availableUsers.find((u) => u.id === selectedTeamToEnroll);
    if (!userObj) return;

    startOperation(`Inscripción de Atleta: ${userObj.gamertag || userObj.name}`);
    startTransition(async () => {
      const res = await enrollIndividualAthleteAction(competition.id, userObj.id, userObj.name, userObj.gamertag);
      if (res.success) {
        setSelectedTeamToEnroll('');
        endSuccess(res.message || 'Atleta inscrito correctamente.');
      } else {
        endError(res.error || 'Error al inscribir atleta.');
      }
    });
  };

  // 2. Retirar Equipo
  const handleRemoveTeam = (teamId: string, teamName: string) => {
    startOperation(`Retiro de Equipo: ${teamName}`);
    startTransition(async () => {
      const res = await removeEnrolledTeamAction(competition.id, teamId);
      if (res.success) {
        endSuccess(res.message || 'Equipo retirado.');
      } else {
        endError(res.error || 'Error al retirar equipo.');
      }
    });
  };

  // 3. Cambiar Estado
  const handleStatusChange = (newStatus: CompetitionStatus) => {
    startOperation(`Cambio de Estado a: ${newStatus}`);
    startTransition(async () => {
      const res = await updateCompetitionStatusAction(competition.id, newStatus);
      if (res.success) {
        endSuccess(res.message || 'Estado actualizado.');
      } else {
        endError(res.error || 'Error al actualizar estado.');
      }
    });
  };

  // Standings calculation
  const standingsMap: Record<string, { name: string; tag: string; pj: number; pg: number; pe: number; pp: number; gf: number; gc: number; pts: number }> = {};
  enrolledTeams.forEach((t) => {
    standingsMap[t.team_id] = { name: t.team_name, tag: t.team_tag || 'TEAM', pj: 0, pg: 0, pe: 0, pp: 0, gf: 0, gc: 0, pts: 0 };
  });

  matches.forEach((m) => {
    const isFinished = m.status === 'TERMINADO' || m.status === 'FINALIZADO';
    const hScore = m.reported_score_home ?? m.score_home;
    const aScore = m.reported_score_away ?? m.score_away;

    if (isFinished && hScore !== null && aScore !== null) {
      const h = standingsMap[m.home_team_id];
      const a = standingsMap[m.away_team_id];
      if (h && a) {
        h.pj += 1;
        a.pj += 1;
        h.gf += hScore;
        h.gc += aScore;
        a.gf += aScore;
        a.gc += hScore;

        if (hScore > aScore) {
          h.pg += 1;
          h.pts += 3;
          a.pp += 1;
        } else if (hScore < aScore) {
          a.pg += 1;
          a.pts += 3;
          h.pp += 1;
        } else {
          h.pe += 1;
          a.pe += 1;
          h.pts += 1;
          a.pts += 1;
        }
      }
    }
  });

  const enrolledSet = new Set(enrolledTeams.map((t) => t.team_id));
  const availableToEnroll = availableTeams.filter(
    (t) => !enrolledSet.has(t.id) && (t.game_slug === competition.game_slug || !t.game_slug)
  );

  const tabButtons = [
    { id: 'dashboard', label: '1. Dashboard (Resumen)', icon: Activity, color: '#A855F7' },
    { id: 'fixture', label: '2. Fixture y Partidos', icon: Calendar, color: '#00F0FF' },
    { id: 'standings', label: '3. Tabla de Posiciones', icon: Trophy, color: '#F59E0B' },
    { id: 'teams', label: `4. Inscripción de Clubes (${enrolledTeams.length})`, icon: Users, color: '#10B981' },
    { id: 'settings', label: '5. Configuración y Estado', icon: Settings, color: '#EF4444' },
  ];

  return (
    <div className="space-y-6">
      <CrudAlertBanner state={crudState} onClose={resetAlert} />

      {/* SISTEMA DE 5 PESTAÑAS HORIZONTALES (ESTILO ESPORTS CON BORDES NEÓN) */}
      <div className="flex items-center gap-2 border-b border-[var(--border-card)] pb-3 overflow-x-auto scrollbar-none font-mono">
        {tabButtons.map((tb) => {
          const isActive = activeTab === tb.id;
          const Icon = tb.icon;
          return (
            <button
              key={tb.id}
              onClick={() => setActiveTab(tb.id as CompetitionTabType)}
              className={`px-4 py-2.5 rounded-xl text-xs font-black transition-all flex items-center gap-2 flex-shrink-0 border ${
                isActive
                  ? 'bg-[var(--bg-main)] shadow-xl scale-[1.02]'
                  : 'bg-[var(--bg-card)] text-[var(--text-muted)] border-[var(--border-card)] hover:border-[var(--border-card-hover)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-card-hover)]'
              }`}
              style={{
                borderColor: isActive ? tb.color : undefined,
                boxShadow: isActive ? `0 0 15px color-mix(in srgb, ${tb.color} 30%, transparent)` : undefined,
                color: isActive ? tb.color : undefined,
              }}
            >
              <Icon className="w-4 h-4" />
              <span>{tb.label}</span>
            </button>
          );
        })}
      </div>

      {/* 📌 PESTAÑA 1: DASHBOARD (RESUMEN) */}
      {activeTab === 'dashboard' && (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 animate-in fade-in duration-200">
          {/* Card 1: Reglas y Sistema */}
          <Card className="p-5 bg-[var(--bg-card)] backdrop-blur-md border border-[var(--border-card)] space-y-3 shadow-xl">
            <div className="flex items-center justify-between border-b border-[var(--border-card)] pb-2.5">
              <h3 className="text-xs font-black uppercase text-purple-400 tracking-wider flex items-center gap-2">
                <Shield className="w-4 h-4 text-purple-400" />
                Reglas y Sistema
              </h3>
              <span className="text-[10px] font-mono text-[var(--accent-cyan)] font-bold uppercase">eSports Spec</span>
            </div>
            <div className="space-y-2 text-xs font-mono">
              <div className="flex items-center justify-between text-[var(--text-secondary)]">
                <span className="text-[var(--text-muted)]">Modalidad:</span>
                <strong className="text-[var(--text-heading)] bg-[var(--bg-main)] px-2 py-0.5 rounded border border-[var(--border-card)]">{competition.mode_format}</strong>
              </div>
              <div className="flex items-center justify-between text-[var(--text-secondary)]">
                <span className="text-[var(--text-muted)]">Tipo de Torneo:</span>
                <strong className="text-[var(--text-heading)] bg-[var(--bg-main)] px-2 py-0.5 rounded border border-[var(--border-card)] uppercase">
                  {competition.mode_format?.toLowerCase().includes('playoff') ? 'PLAYOFF' : competition.mode_format?.toLowerCase().includes('hibrid') ? 'LIGA HÍBRIDA' : 'LIGA'}
                </strong>
              </div>
              <div className="flex items-center justify-between text-[var(--text-secondary)]">
                <span className="text-[var(--text-muted)]">Plataforma Oficial:</span>
                <strong className="text-[var(--accent-cyan)] font-bold">CROSSPLAY</strong>
              </div>

              {(competition.mode_format || '').toUpperCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").includes('HIBRID') && (
                <div className="flex items-center justify-between text-[var(--text-secondary)]">
                  <span className="text-[var(--text-muted)]">Clasifican a Playoffs:</span>
                  <strong className="text-amber-400 font-bold">Top {(competition as any).qualifiers_per_group || 2} de cada grupo</strong>
                </div>
              )}

              <div className="flex items-center justify-between text-[var(--text-secondary)]">
                <span className="text-[var(--text-muted)]">Formato de Partido:</span>
                <strong className="text-emerald-400 font-bold">
                  {competition.match_mode === 'IdaVuelta' ? 'Ida y Vuelta' : 'Partido Único'}
                </strong>
              </div>
              <div className="flex items-center justify-between text-[var(--text-secondary)]">
                <span className="text-[var(--text-muted)]">Auto-Avance:</span>
                <strong className="text-rose-400 font-bold">Manual</strong>
              </div>
            </div>
          </Card>

          {/* Card 2: Progreso de Competición */}
          <Card className="p-5 bg-[var(--bg-card)] backdrop-blur-md border border-[var(--border-card)] space-y-3 shadow-xl flex flex-col justify-between">
            <div>
              <div className="flex items-center justify-between border-b border-[var(--border-card)] pb-2.5">
                <h3 className="text-xs font-black uppercase text-[var(--accent-cyan)] tracking-wider flex items-center gap-2">
                  <Activity className="w-4 h-4 text-[var(--accent-cyan)]" />
                  Progreso de Competición
                </h3>
                <span className="text-[10px] font-mono text-emerald-400 font-bold">{progressPercent}%</span>
              </div>
              <div className="space-y-3 mt-3">
                <div className="flex items-center justify-between text-xs font-mono font-bold">
                  <span className="text-[var(--text-secondary)]">Progreso Total:</span>
                  <span className="text-[var(--accent-cyan)]">{playedMatches} / {totalMatches} Partidos Jugados</span>
                </div>
                <div className="w-full h-3 rounded-full bg-[var(--bg-main)] border border-[var(--border-card)] overflow-hidden relative">
                  <div className="h-full bg-gradient-to-r from-purple-500 via-cyan-400 to-emerald-400 transition-all duration-500 rounded-full" style={{ width: `${progressPercent}%` }} />
                </div>
              </div>
            </div>
            <div className="text-[10px] font-mono text-[var(--text-muted)] bg-[var(--bg-main)] p-2 rounded-lg border border-[var(--border-card)] mt-2">
              💡 Actualización automática tras el visto bueno de actas en Matchday.
            </div>
          </Card>

          {/* Card 3: Métricas Rápidas */}
          <Card className="p-5 bg-[var(--bg-card)] backdrop-blur-md border border-[var(--border-card)] space-y-3 shadow-xl">
            <div className="flex items-center justify-between border-b border-[var(--border-card)] pb-2.5">
              <h3 className="text-xs font-black uppercase text-emerald-400 tracking-wider flex items-center gap-2">
                <Zap className="w-4 h-4 text-emerald-400" />
                Métricas Rápidas
              </h3>
              <span className="text-[10px] font-mono text-purple-400 font-bold">{enrolledTeams.length} Clubes</span>
            </div>
            <div className="grid grid-cols-3 gap-2 pt-1 text-center font-mono">
              <div className="p-2.5 rounded-xl bg-[var(--bg-main)] border border-[var(--border-card)]">
                <span className="text-[10px] text-[var(--text-muted)] block uppercase">Jugados</span>
                <strong className="text-emerald-400 text-lg font-black">{playedMatches}</strong>
              </div>
              <div className="p-2.5 rounded-xl bg-[var(--bg-main)] border border-[var(--border-card)]">
                <span className="text-[10px] text-[var(--text-muted)] block uppercase">Pendientes</span>
                <strong className="text-amber-400 text-lg font-black">{pendingMatches}</strong>
              </div>
              <div className="p-2.5 rounded-xl bg-[var(--bg-main)] border border-[var(--border-card)]">
                <span className="text-[10px] text-[var(--text-muted)] block uppercase">Completado</span>
                <strong className="text-[var(--accent-cyan)] text-lg font-black">{progressPercent}%</strong>
              </div>
            </div>
          </Card>
        </div>
      )}

      {/* ⚙️ PESTAÑA 2: FIXTURE Y PARTIDOS (MOMENTO FIXTURE OFICIAL & SCHEDULE VIEW SIN FILTROS REPETIDOS) */}
      {activeTab === 'fixture' && (
        <div className="space-y-6 animate-in fade-in duration-200">
          <FixtureGenerator competition={competition} enrolledTeams={enrolledTeams} matches={matches} />

          <div className="pt-4 border-t border-[var(--border-card)] space-y-4">
            <div className="flex items-center justify-between">
              <h3 className="text-sm font-black uppercase text-[var(--accent-cyan)] tracking-wider flex items-center gap-2">
                <Calendar className="w-4 h-4 text-[var(--accent-cyan)]" />
                CALENDARIO & JORNADAS DE ESTA COMPETENCIA
              </h3>
            </div>
            <FixtureScheduleView
              game={gameConfig}
              initialTournName={competition.name}
              initialTournId={competition.id}
              hideOrgFilter={true}
              hideCompFilter={true}
              hideSearchFilter={true}
              hideHeader={true}
            />
          </div>
        </div>
      )}

      {/* 🏆 PESTAÑA 3: TABLA DE POSICIONES (STANDINGS VIEW OFICIAL DE CLASIFICACIÓN SIN FILTROS REPETIDOS) */}
      {activeTab === 'standings' && (
        <div className="animate-in fade-in duration-200 space-y-4">
          <ClassificationView
            game={gameConfig}
            initialTournName={competition.name}
            initialTournId={competition.id}
            hideOrgFilter={true}
            hideCompFilter={true}
            hideSearchFilter={true}
            hideHeader={true}
          />
        </div>
      )}

      {/* 🛡️ PESTAÑA 4: INSCRIPCIÓN DE CLUBES O ATLETAS INDIVIDUALES */}
      {activeTab === 'teams' && (
        <div className="space-y-6 animate-in fade-in duration-200">
          {/* Formulario Selector */}
          <Card className="p-5 bg-[var(--bg-card)] backdrop-blur-md border border-emerald-500/40 space-y-3 shadow-2xl">
            <h3 className="text-xs font-black uppercase text-emerald-400 flex items-center gap-2">
              {isIndividual ? <UserCheck className="w-4 h-4 text-amber-400" /> : <Plus className="w-4 h-4 text-emerald-400" />}
              {isIndividual
                ? `Inscribir Atleta / Jugador Directo (Modalidad Individual ${competition.mode_format})`
                : `Inscribir Club Existente (Modalidad Equipos ${competition.mode_format})`}
            </h3>

            <div className="flex flex-col sm:flex-row items-center gap-3">
              {isIndividual ? (
                <select
                  value={selectedTeamToEnroll}
                  onChange={(e) => setSelectedTeamToEnroll(e.target.value)}
                  className="w-full sm:flex-1 p-2.5 rounded-xl input-theme font-mono text-xs outline-none focus:border-amber-500"
                >
                  <option value="" className="bg-[#0b101b] text-slate-100">
                    -- Seleccionar Jugador / Atleta Disponible ({availableUsers.length} disponibles) --
                  </option>
                  {availableUsers.map((u) => (
                    <option key={u.id} value={u.id} className="bg-[#0b101b] text-slate-100">
                      👤 {u.name} ({u.gamertag || 'Sin Gamertag'}) — Pos: {u.position || 'General'}
                    </option>
                  ))}
                </select>
              ) : (
                <select
                  value={selectedTeamToEnroll}
                  onChange={(e) => setSelectedTeamToEnroll(e.target.value)}
                  className="w-full sm:flex-1 p-2.5 rounded-xl input-theme font-mono text-xs outline-none focus:border-emerald-500"
                >
                  <option value="" className="bg-[#0b101b] text-slate-100">-- Seleccionar Equipo de {gameConfig.name} ({availableToEnroll.length} disponibles) --</option>
                  {availableToEnroll.map((t) => (
                    <option key={t.id} value={t.id} className="bg-[#0b101b] text-slate-100">
                      🛡️ {t.name} [{t.tag}] — ({t.platform})
                    </option>
                  ))}
                </select>
              )}

              <Button
                onClick={isIndividual ? handleEnrollAthlete : handleEnrollTeam}
                disabled={isPending || !selectedTeamToEnroll}
                className={`w-full sm:w-auto font-black text-xs px-6 py-2.5 rounded-xl shadow-lg flex items-center gap-2 ${
                  isIndividual
                    ? 'bg-amber-500 hover:bg-amber-400 text-slate-950'
                    : 'bg-emerald-600 hover:bg-emerald-500 text-slate-950'
                }`}
              >
                <Plus className="w-4 h-4" />
                <span>{isIndividual ? 'Inscribir Atleta' : 'Inscribir Club'}</span>
              </Button>
            </div>
          </Card>

          {/* Grid de Clubes Confirmados */}
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
            {enrolledTeams.map((t) => (
              <div key={t.id} className="p-3.5 rounded-xl bg-[var(--bg-card)] backdrop-blur-md border border-[var(--border-card)] flex items-center justify-between shadow-md">
                <div className="flex items-center gap-3">
                  <div className="w-9 h-9 rounded-xl bg-[var(--bg-main)] border border-emerald-500/40 flex items-center justify-center font-black text-xs text-emerald-400 shadow-md">
                    {t.team_tag || 'TEAM'}
                  </div>
                  <div>
                    <h4 className="font-black text-xs text-[var(--text-heading)]">{t.team_name}</h4>
                    <span className="text-[10px] font-mono text-emerald-400 font-bold flex items-center gap-1">
                      <Check className="w-3 h-3 text-emerald-400" />
                      CONFIRMADO
                    </span>
                  </div>
                </div>

                <Button
                  size="sm"
                  variant="ghost"
                  onClick={() => handleRemoveTeam(t.team_id, t.team_name)}
                  className="text-xs text-rose-400 hover:bg-rose-950 p-2"
                  title="Retirar equipo"
                >
                  <Trash2 className="w-3.5 h-3.5" />
                </Button>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* ⚙️ PESTAÑA 5: CONFIGURACIÓN Y ESTADO */}
      {activeTab === 'settings' && (
        <Card className="p-6 bg-[var(--bg-card)] backdrop-blur-md border border-[var(--border-card)] space-y-4 shadow-2xl animate-in fade-in duration-200">
