            >
              <Plus className="w-4 h-4" />
              <span>Nueva Organización</span>
            </Button>
          </div>

          <DataTable
            columns={[
              {
                header: 'Organización',
                cell: (r) => (
                  <div className="flex items-center gap-3">
                    {r.logo_url ? (
                      <Image
                        src={r.logo_url}
                        alt={r.name}
                        width={32}
