'use client';

import React, { useState, useEffect } from 'react';
import { GameConfig } from '@/lib/games-data';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Select } from '@/components/ui/select';
import { Avatar } from '@/components/ui/avatar';
import { FilterBar } from '@/components/ui/filter-bar';
import { 
  Users, UserPlus, FileText, Layers, Ban, CheckSquare, Search, Send, Clock, X, Trophy
} from 'lucide-react';
import { useAuth } from '@/components/providers/auth-provider';
import { CrudAlertBanner, useCrudNotifier } from '@/components/ui/crud-alert';
import {
  getNewTeamSquadAction,
  getNewPlayerInscriptionsMatrixAction,
  expelPlayerFromSquadAction
} from '@/app/actions/new-squads';
import {
  issueNewContractOfferService,
  getSentContractsByTeamAction
} from '@/app/actions/new-transfers';
import { getAllPlayersForContractOfferAction } from '@/app/actions/squads'; // reuse the simple search

export function NewSquadManagementView({ game }: { game: GameConfig }) {
  const { currentUser, userTeams } = useAuth();
  const { crudState, startOperation, endSuccess, endError, resetAlert } = useCrudNotifier();

  const [activeTab, setActiveTab] = useState<'roster' | 'recruit' | 'contracts' | 'matrix'>('roster');

  const myTeam = userTeams?.find(t => t.captainId === currentUser?.id) || userTeams?.[0];
  const teamId = myTeam?.id;

  const [squad, setSquad] = useState<any[]>([]);
  const [matrix, setMatrix] = useState<any[]>([]);
  const [contracts, setContracts] = useState<any[]>([]);
  const [searchablePlayers, setSearchablePlayers] = useState<any[]>([]);

  // Roster Filters
  const [rosterSearch, setRosterSearch] = useState('');
  const [rosterOrgFilter, setRosterOrgFilter] = useState('ALL');

  // Recruit Form
  const [selectedPlayer, setSelectedPlayer] = useState<any>(null);
  const [recruitSearch, setRecruitSearch] = useState('');
  const [selectedOrgs, setSelectedOrgs] = useState<string[]>([]);
  const availableOrgs = ['comunidad amc', 'gamer cup', 'pgl', 'fgl']; // Stub or fetch from team comps

  useEffect(() => {
    if (teamId) {
      loadData();
    }
  }, [teamId, activeTab]);

  const loadData = async () => {
    if (!teamId) return;
    try {
      if (activeTab === 'roster') {
        const res = await getNewTeamSquadAction(teamId);
        if (res.success) setSquad(res.squad);
      } else if (activeTab === 'matrix') {
        const res = await getNewPlayerInscriptionsMatrixAction(teamId);
        if (res.success) setMatrix(res.data);
      } else if (activeTab === 'contracts') {
        const res = await getSentContractsByTeamAction(teamId);
        if (res.success) setContracts(res.offers);
      } else if (activeTab === 'recruit') {
        const res = await getAllPlayersForContractOfferAction(game.slug, recruitSearch);
        if (res.success) {
          // Asegurar que el capitán actual y los miembros actuales del equipo estén disponibles para ser seleccionados
          // Esto soluciona el problema de "no me deja enviarme contrato a mi mismo" haciendo que sea súper obvio.
          const allPlayers = [...res.players];

          // Si el usuario actual no está en la lista (por ej. debido al límite de 100), lo agregamos arriba
          if (currentUser && !allPlayers.find(p => p.id === currentUser.id)) {
            allPlayers.unshift({
              id: currentUser.id,
              name: currentUser.name,
              gamertag: currentUser.gamertag,
              avatar_url: currentUser.avatarUrl,
              foto: currentUser.foto,
              position: currentUser.position || 'DFC'
            });
          }
          setSearchablePlayers(allPlayers);
        }
      }
    } catch (err) {}
  };

  const handleIssueContract = async () => {
    if (!selectedPlayer || selectedOrgs.length === 0) return;
    startOperation('Emitir Contrato');
    try {
      const res = await issueNewContractOfferService(
        teamId!,
        selectedPlayer.id,
        currentUser?.id || '',
        selectedOrgs,
        'DFC',
        game.slug
      );
      if (res.success) {
        endSuccess(res.message || 'Contrato emitido exitosamente.');
        setSelectedPlayer(null);
        setSelectedOrgs([]);
        loadData();
      } else {
        endError(res.error || 'Error');
      }
    } catch (err: any) {
      endError(err.message || 'Error desconocido');
    }
  };

  const handleExpel = async (userId: string, orgName?: string) => {
    startOperation('Desvincular');
    try {
      const res = await expelPlayerFromSquadAction(teamId!, userId, orgName);
      if (res.success) {
        endSuccess(res.message || 'Jugador desvinculado.');
        loadData();
      } else {
        endError(res.error || 'Error al expulsar');
      }
    } catch (err: any) {
      endError(err.message || 'Error desconocido');
    }
  };

  const toggleOrgSelection = (org: string) => {
    if (selectedOrgs.includes(org)) {
      setSelectedOrgs(selectedOrgs.filter(o => o !== org));
    } else {
      setSelectedOrgs([...selectedOrgs, org]);
    }
  };

  // Derived filtered roster
  const filteredSquad = squad.filter(p => {
    const matchSearch = p.user_name?.toLowerCase().includes(rosterSearch.toLowerCase()) || p.gamertag?.toLowerCase().includes(rosterSearch.toLowerCase());
    const matchOrg = rosterOrgFilter === 'ALL' || p.original_orgs?.includes(rosterOrgFilter);
    return matchSearch && matchOrg;
  });

  return (
    <div className="space-y-6">
      <CrudAlertBanner state={crudState} onClose={resetAlert} />

      {/* TABS */}
      <div className="flex flex-wrap gap-2 mb-6">
        <Button variant={activeTab === 'roster' ? 'primary' : 'outline'} onClick={() => setActiveTab('roster')}>
          <Users className="w-4 h-4 mr-2" /> Plantilla Roster
        </Button>
        <Button variant={activeTab === 'recruit' ? 'primary' : 'outline'} onClick={() => setActiveTab('recruit')}>
          <UserPlus className="w-4 h-4 mr-2" /> Emitir Contrato
        </Button>
        <Button variant={activeTab === 'contracts' ? 'primary' : 'outline'} onClick={() => setActiveTab('contracts')}>
          <FileText className="w-4 h-4 mr-2" /> Contratos Enviados
        </Button>
        <Button variant={activeTab === 'matrix' ? 'primary' : 'outline'} onClick={() => setActiveTab('matrix')}>
          <Layers className="w-4 h-4 mr-2" /> Matriz de Organización
        </Button>
      </div>

      {/* ROSTER TAB */}
      {activeTab === 'roster' && (
        <div className="space-y-4">
          <div className="flex flex-col sm:flex-row gap-4 mb-6">
            <FilterBar 
              searchValue={rosterSearch} 
              onSearchChange={setRosterSearch} 
              searchPlaceholder="Buscar en plantilla..." 
              brandColor={game.brandColor} 
            />
            <select 
              className="bg-black/50 border border-white/10 rounded-md px-3 py-2 text-sm text-white focus:outline-none focus:ring-2 focus:ring-[var(--primary)]" 
              value={rosterOrgFilter} 
              onChange={e => setRosterOrgFilter(e.target.value)}
            >
              <option value="ALL">Todas las Organizaciones</option>
              {availableOrgs.map(o => <option key={o} value={o}>{o.toUpperCase()}</option>)}
            </select>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
            {filteredSquad.map(member => (
              <Card key={member.user_id} className="glass-card relative overflow-hidden group border-white/5 bg-black/40">
                <div className="p-4 flex flex-col items-center text-center space-y-3">
                  <Avatar className="w-16 h-16 border-2 border-[var(--primary)]" src={member.avatar_url || member.foto} fallback={member.user_name} />
                  <div>
                    <h3 className="font-bold text-lg">{member.user_name}</h3>
                    <p className="text-sm text-[var(--text-muted)]">{member.gamertag}</p>
                  </div>
                  <div className="flex flex-wrap justify-center gap-1">
                    {member.original_orgs?.map((o: string) => (
                      <Badge key={o} variant="slate" className="text-xs">{o.toUpperCase()}</Badge>
                    ))}
                  </div>
                  <Button variant="danger" size="sm" onClick={() => handleExpel(member.user_id)} className="w-full mt-2">
                    <Ban className="w-4 h-4 mr-2"/> Desvincular
                  </Button>
                </div>
              </Card>
            ))}
          </div>
        </div>
      )}

      {/* RECRUIT TAB */}
      {activeTab === 'recruit' && (
        <Card className="glass-card border-white/5 bg-black/40">
          <CardHeader>
            <CardTitle className="flex items-center gap-2"><UserPlus className="text-[var(--primary)]" /> Emitir Nuevo Contrato</CardTitle>
          </CardHeader>
          <CardContent className="space-y-6">
            {!selectedPlayer ? (
              <div className="space-y-4">
                <div className="flex gap-2">
                  <Input placeholder="Buscar por gamertag o nombre..." value={recruitSearch} onChange={e => setRecruitSearch(e.target.value)} className="bg-black/50" />
                  <Button onClick={loadData}><Search className="w-4 h-4" /></Button>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  {searchablePlayers.map(p => (
                    <div key={p.id} className="p-3 bg-black/30 border border-white/5 rounded-lg flex items-center justify-between hover:border-[var(--primary)]/50 transition-colors">
                      <div className="flex items-center gap-3">
                        <Avatar src={p.avatar_url} fallback={p.name} className="w-10 h-10" />
                        <div>
                          <p className="font-bold text-sm">{p.name}</p>
                          <p className="text-xs text-[var(--text-muted)]">{p.gamertag}</p>
                        </div>
                      </div>
                      <Button size="sm" onClick={() => setSelectedPlayer(p)}>Seleccionar</Button>
                    </div>
                  ))}
                </div>
              </div>
            ) : (
              <div className="space-y-6 animate-in fade-in">
                <div className="flex items-center gap-4 p-4 bg-[var(--primary)]/10 border border-[var(--primary)]/30 rounded-xl">
                  <Avatar src={selectedPlayer.avatar_url} fallback={selectedPlayer.name} className="w-12 h-12" />
                  <div>
                    <h3 className="font-bold">Contratando a {selectedPlayer.name}</h3>
                    <p className="text-sm opacity-80">Selecciona las organizaciones para el contrato:</p>
                  </div>
                  <Button variant="ghost" size="icon" className="ml-auto" onClick={() => setSelectedPlayer(null)}><X className="w-5 h-5"/></Button>
                </div>

                <div className="flex flex-wrap gap-3">
                  {availableOrgs.map(org => (
                    <div 
                      key={org} 
                      onClick={() => toggleOrgSelection(org)}
                      className={`cursor-pointer px-4 py-3 rounded-lg border flex items-center gap-2 transition-all ${
                        selectedOrgs.includes(org) ? 'bg-[var(--primary)]/20 border-[var(--primary)] text-white' : 'bg-black/40 border-white/10 text-white/60 hover:border-white/30'
                      }`}
                    >
                      {selectedOrgs.includes(org) ? <CheckSquare className="w-5 h-5 text-[var(--primary)]" /> : <div className="w-5 h-5 rounded border border-white/30" />}
                      <span className="font-medium uppercase text-sm">{org}</span>
                    </div>
                  ))}
                </div>

                <Button className="w-full" disabled={selectedOrgs.length === 0 || crudState.status === 'LOADING'} onClick={handleIssueContract}>
                  {crudState.status === 'LOADING' ? <Clock className="w-4 h-4 mr-2 animate-spin" /> : <Send className="w-4 h-4 mr-2" />}
                  Emitir Contrato para {selectedOrgs.length} Organización(es)
                </Button>
              </div>
            )}
          </CardContent>
        </Card>
      )}

      {/* CONTRACTS TAB */}
      {activeTab === 'contracts' && (
        <Card className="glass-card border-white/5 bg-black/40">
          <CardHeader>
            <CardTitle className="flex items-center gap-2"><FileText className="text-[var(--primary)]" /> Historial de Contratos Enviados</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="overflow-x-auto">
              <table className="w-full text-sm text-left">
                <thead className="text-xs text-[var(--text-muted)] uppercase bg-black/50">
                  <tr>
                    <th className="px-4 py-3">Jugador</th>
                    <th className="px-4 py-3">Organización</th>
                    <th className="px-4 py-3">Fecha</th>
                    <th className="px-4 py-3">Estado</th>
                  </tr>
                </thead>
                <tbody>
                  {contracts.map(c => {
                    const orgMatch = c.pitch_message?.match(/\[Organización:\s*([^\]]+)\]/i);
                    const orgName = orgMatch ? orgMatch[1] : 'General';
                    return (
                      <tr key={c.id} className="border-b border-white/5 hover:bg-white/5">
                        <td className="px-4 py-3 font-medium flex items-center gap-2">
                          <Avatar src={c.avatar_url} fallback={c.player_name} className="w-6 h-6" /> {c.player_name}
                        </td>
                        <td className="px-4 py-3 uppercase text-xs">
                          <Badge variant="slate">{orgName}</Badge>
                        </td>
                        <td className="px-4 py-3 text-[var(--text-muted)]">
                          {new Date(c.created_at).toLocaleString()}
                        </td>
                        <td className="px-4 py-3">
                          <Badge variant={
                            c.status === 'ACEPTADO' ? 'emerald' : 
                            c.status === 'RECHAZADO' ? 'rose' : 
                            c.status === 'CONCLUIDO' ? 'slate' : 'cyan'
                          }>
                            {c.status}
                          </Badge>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </CardContent>
        </Card>
      )}

      {/* MATRIX TAB */}
      {activeTab === 'matrix' && (
        <Card className="glass-card border-white/5 bg-black/40 overflow-hidden">
          <CardHeader>
            <CardTitle className="flex items-center gap-2"><Layers className="text-[var(--primary)]" /> Matriz de Organizaciones</CardTitle>
          </CardHeader>
          <div className="overflow-x-auto p-4">
            <table className="w-full text-sm">
              <thead>
                <tr>
                  <th className="p-3 text-left bg-black/60 rounded-tl-lg">Atleta</th>
                  {availableOrgs.map(org => (
                    <th key={org} className="p-3 text-center bg-black/40 border-l border-white/5 text-xs uppercase text-[var(--text-muted)]">
                      {org}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {matrix.map((row, idx) => (
                  <tr key={row.user_id} className={`border-b border-white/5 ${idx % 2 === 0 ? 'bg-black/20' : ''}`}>
                    <td className="p-3 font-medium border-r border-white/5">{row.user_name}</td>
                    {availableOrgs.map(org => {
                      const isActive = row.organizations.some((o: any) => o.name.toLowerCase() === org.toLowerCase());
                      return (
                        <td key={org} className="p-3 text-center border-l border-white/5">
                          {isActive ? (
                            <CheckSquare className="w-5 h-5 mx-auto text-[var(--primary)]" />
                          ) : (
                            <div className="w-5 h-5 mx-auto rounded border border-white/10 opacity-30" />
                          )}
                        </td>
                      );
                    })}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </Card>
      )}
    </div>
  );
}

'use client';

import React, { useState, useEffect, useCallback } from 'react';
import Link from 'next/link';
import { GameConfig } from '@/lib/games-data';
import { Card } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Select } from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';
import { Avatar } from '@/components/ui/avatar';
import { ModalForm } from '@/components/ui/modal-form';
import { ConfirmModal } from '@/components/ui/confirm-modal';
import { CrudAlertBanner, useCrudNotifier } from '@/components/ui/crud-alert';
import { useAuth } from '@/components/providers/auth-provider';
import {
  getTeamSquadAction,
  getAllPlayersForContractOfferAction,
  removePlayerFromSquadAction,
  updateSquadMemberJerseyAction,
  getPlayerInscriptionsMatrixAction,
  SquadMemberData,
} from '@/app/actions/squads';
import {
  sendClubContractOfferAction,
  getOutgoingOffersAction,
  cancelTransferOfferAction,
} from '@/app/actions/transfers';
import {
  Shield,
  Users,
  UserPlus,
  FileText,
  Building2,
  Search,
  Hash,
  Send,
  Loader2,
  Trash2,
  Clock,
  Ban,
  Layers,
  Trophy,
  MessageSquare,
  CheckSquare,
  Square,
  User,
} from 'lucide-react';

interface PlantillaManagementViewProps {
  game: GameConfig;
}

export function PlantillaManagementView({ game }: PlantillaManagementViewProps) {
  const gameSlug = game.slug || 'eafc26';
  const { currentUser, userTeams } = useAuth();
  const { crudState, startOperation, endSuccess, endError, resetAlert } = useCrudNotifier();

  // 1. Strictly determine the specific club managed by currentUser
  const myTeam = (userTeams || []).find((t: any) => {
    const slug = (t as any).game_slug || t.gameSlug || 'eafc26';
    if (slug !== gameSlug && gameSlug !== 'ALL') return false;

    const uId = currentUser?.id;
    const uName = currentUser?.name?.toLowerCase();
    const uGamer = currentUser?.gamertag?.toLowerCase();

    const cId = t.captain_id || t.captainId;
    const cName = (t.captain_name || t.captainName || '').toLowerCase();

    if (cId && cId === uId) return true;
    if (cName && (cName === uName || cName === uGamer)) return true;
    if (currentUser?.teamId && t.id === currentUser.teamId) return true;

    const encs = t.encargados || t.encargados_json;
    if (encs) {
      try {
        const arr = typeof encs === 'string' ? JSON.parse(encs) : encs;
        if (Array.isArray(arr)) {
          return arr.some((enc: any) => {
            if (typeof enc === 'string') return enc === uId || enc.toLowerCase() === uName || enc.toLowerCase() === uGamer;
            return (
              enc.id === uId ||
              (enc.name && uName && enc.name.toLowerCase() === uName) ||
              (enc.gamertag && uGamer && enc.gamertag.toLowerCase() === uGamer)
            );
          });
        }
      } catch (e) {}
    }

    if (currentUser?.role === 'Administrador' || currentUser?.role === 'Organizador') return true;
    return false;
  }) || (userTeams && userTeams.length > 0 ? userTeams[0] : null);

  const teamId = myTeam?.id || 'tm-1';
  const teamName = myTeam?.name || 'Escuadra Oficial';
  const teamTag = myTeam?.tag || 'CLUB';

  // Organizations state
  const [organizations, setOrganizations] = useState<any[]>([]);
  const [contractOrgs, setContractOrgs] = useState<any[]>([]);
  const [selectedOrgFilter, setSelectedOrgFilter] = useState<string>('ALL');
  const [activeTab, setActiveTab] = useState<'roster' | 'send_contracts' | 'sent_offers' | 'matrix'>('roster');

  // Roster & Players state
  const [squad, setSquad] = useState<SquadMemberData[]>([]);
  const [isLoadingSquad, setIsLoadingSquad] = useState(false);

  // All Players for Contract Offers (Tab 2)
  const [allPlayers, setAllPlayers] = useState<any[]>([]);
  const [searchPlayerQuery, setSearchPlayerQuery] = useState('');
  const [isLoadingAllPlayers, setIsLoadingAllPlayers] = useState(false);

  // Sent Offers state (Tab 3)
  const [outgoingOffers, setOutgoingOffers] = useState<any[]>([]);
  const [isLoadingOffers, setIsLoadingOffers] = useState(false);

  // Inscriptions Matrix state (Tab 4 for THIS club)
  const [inscriptionsMatrix, setInscriptionsMatrix] = useState<any[]>([]);
  const [isLoadingMatrix, setIsLoadingMatrix] = useState(false);
  const [matrixSearchQuery, setMatrixSearchQuery] = useState('');

  // Modals state
  const [editingMember, setEditingMember] = useState<SquadMemberData | null>(null);
  const [jerseyInput, setJerseyInput] = useState<string>('');
  const [isSubmittingJersey, setIsSubmittingJersey] = useState(false);

  const [removingMember, setRemovingMember] = useState<SquadMemberData | null>(null);

  // Contract Offer Modal State (with Multi-Select Checkboxes for Organizations)
  const [isContractModalOpen, setIsContractModalOpen] = useState(false);
  const [targetPlayer, setTargetPlayer] = useState<any | null>(null);
  const [contractPosition, setContractPosition] = useState<string>('DC');
  const [selectedContractOrgNames, setSelectedContractOrgNames] = useState<string[]>([]);
  const [contractTermsMessage, setContractTermsMessage] = useState<string>('');
  const [isSendingContract, setIsSendingContract] = useState(false);

  // Fetch Organizations & Filter Organizations with active tournaments in this gameSlug
  const fetchOrgsAndCompetitions = useCallback(async () => {
    try {
      const [orgRes, compRes] = await Promise.all([
        fetch('/api/admin/organizations').then((r) => r.json()).catch(() => ({ success: false, organizations: [] })),
        fetch('/api/tournaments').then((r) => r.json()).catch(() => ({ competitions: [] })),
      ]);

      const allOrgs = orgRes.success && Array.isArray(orgRes.organizations) ? orgRes.organizations : [];
      const comps = compRes.competitions || compRes.data?.competitions || [];

      // Filter organization IDs with active tournaments in this gameSlug
      const activeOrgIds = new Set(
        comps
          .filter((c: any) => (c.game_slug || c.gameSlug || 'eafc26') === gameSlug)
          .map((c: any) => c.organization_id || c.organizationId)
          .filter(Boolean)
      );

      setOrganizations(allOrgs);

      // Filtered Organizations for Contract Offer Modal (only orgs with active competitions in this game)
      const validForContract = allOrgs.filter((org: any) => activeOrgIds.size === 0 || activeOrgIds.has(org.id));
      const orgsList = validForContract.length > 0 ? validForContract : allOrgs;
      setContractOrgs(orgsList);
      if (orgsList.length > 0) {
        setSelectedContractOrgNames([orgsList[0].name]);
      }
    } catch (e) {
      console.error('Error cargando organizaciones y competencias:', e);
    }
  }, [gameSlug]);

  useEffect(() => {
    const timer = window.setTimeout(() => void fetchOrgsAndCompetitions(), 0);
    return () => window.clearTimeout(timer);
  }, [fetchOrgsAndCompetitions]);

  // Load Squad Roster for THIS Club
  const loadSquad = useCallback(async () => {
    if (!teamId) return;
    setIsLoadingSquad(true);
    try {
      const res = await getTeamSquadAction(teamId);
      if (res.success && res.squad) {
        setSquad(res.squad);
      } else {
        setSquad([]);
      }
    } catch (e) {
      console.error('Error cargando plantilla:', e);
    } finally {
      setIsLoadingSquad(false);
    }
  }, [teamId]);

  // Load ALL Players (Tab 2: shows all registered athletes in DB for this discipline)
  const loadAllPlayers = useCallback(async () => {
    setIsLoadingAllPlayers(true);
    try {
      const res = await getAllPlayersForContractOfferAction(gameSlug, searchPlayerQuery);
      let playersList = res.success && res.players ? res.players : [];

      if (currentUser) {
        const selfExists = playersList.some((p: any) => p.id === currentUser.id);
        if (!selfExists) {
          const matchesQuery = !searchPlayerQuery || 
            currentUser.name?.toLowerCase().includes(searchPlayerQuery.toLowerCase()) || 
            currentUser.gamertag?.toLowerCase().includes(searchPlayerQuery.toLowerCase());

          if (matchesQuery) {
            playersList = [
              {
                id: currentUser.id,
                name: currentUser.name || 'Mi Perfil Directivo',
                gamertag: currentUser.gamertag || currentUser.name || 'Atleta',
                email: currentUser.email || '',
                position: 'DFC',
                current_team_id: teamId,
                current_team_name: teamName,
                current_team_tag: teamTag,
              },
              ...playersList,
            ];
          }
        } else {
          // Move self to top of the list for easy access
          const selfObj = playersList.find((p: any) => p.id === currentUser.id);
          const rest = playersList.filter((p: any) => p.id !== currentUser.id);
          playersList = [selfObj, ...rest];
        }
      }

      setAllPlayers(playersList);
    } catch (e) {
      console.error('Error cargando todos los jugadores:', e);
    } finally {
      setIsLoadingAllPlayers(false);
    }
  }, [currentUser, gameSlug, searchPlayerQuery, teamId, teamName, teamTag]);

  // Load Sent Offers (Tab 3) for THIS Club
  const loadSentOffers = useCallback(async () => {
    if (!teamId) return;
    setIsLoadingOffers(true);
    try {
      const res = await getOutgoingOffersAction(teamId, gameSlug);
      if (res.success && res.data) {
        setOutgoingOffers(res.data);
      } else {
        setOutgoingOffers([]);
      }
    } catch (e) {
      console.error('Error cargando solicitudes enviadas:', e);
    } finally {
      setIsLoadingOffers(false);
    }
  }, [gameSlug, teamId]);

  // Load Inscriptions Matrix for THIS Club (Tab 4)
  const loadInscriptionsMatrix = useCallback(async () => {
    if (!teamId) return;
    setIsLoadingMatrix(true);
    try {
      const res = await getPlayerInscriptionsMatrixAction(teamId, gameSlug);
      if (res.success && res.data) {
        setInscriptionsMatrix(res.data);
      } else {
        setInscriptionsMatrix([]);
      }
    } catch (e) {
      console.error('Error cargando matriz de inscripciones del club:', e);
    } finally {
      setIsLoadingMatrix(false);
    }
  }, [gameSlug, teamId]);

  useEffect(() => {
    if (!teamId) return;
    const timer = window.setTimeout(() => {
      void Promise.all([loadSquad(), loadAllPlayers(), loadSentOffers()]);
    }, 0);
    return () => window.clearTimeout(timer);
  }, [loadAllPlayers, loadSentOffers, loadSquad, teamId]);

  useEffect(() => {
    if (activeTab !== 'matrix' || !teamId) return;
    const timer = window.setTimeout(() => void loadInscriptionsMatrix(), 0);
    return () => window.clearTimeout(timer);
  }, [activeTab, loadInscriptionsMatrix, teamId]);

  useEffect(() => {
    if (searchPlayerQuery !== undefined) {
      const timer = setTimeout(loadAllPlayers, 300);
      return () => clearTimeout(timer);
    }
  }, [loadAllPlayers, searchPlayerQuery]);

  // Roster filtered by Organization (Tab 1)
  const filteredSquad = squad.filter((member) => {
    if (selectedOrgFilter === 'ALL') return true;
    const orgIds = ((member as any).organization_ids || '').split(',');
    const orgNames = ((member as any).organization_names || '').split(',');
    return (
      orgIds.includes(selectedOrgFilter) ||
      orgNames.includes(selectedOrgFilter) ||
      orgNames.some((n: string) => n.trim().toLowerCase() === selectedOrgFilter.trim().toLowerCase())
    );
  });

  // Action: Save Jersey Number (# Dorsal)
  const handleSaveJersey = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingMember) return;
    setIsSubmittingJersey(true);
    startOperation(`Asignación de Dorsal #${jerseyInput || 'Sin Número'} para ${editingMember.user_name}`);

    const num = jerseyInput ? parseInt(jerseyInput, 10) : null;

    try {
      const res = await updateSquadMemberJerseyAction(editingMember.id, num);
      if (res.success) {
        setEditingMember(null);
        endSuccess(`El dorsal #${num || '—'} fue asignado exitosamente a ${editingMember.user_name}.`);
        loadSquad();
      } else {
        endError(res.error || 'Error al actualizar dorsal.');
      }
    } catch (e: any) {
      endError(e?.message || 'Error de conexión al guardar dorsal.');
    } finally {
      setIsSubmittingJersey(false);
    }
  };

  // Action: Remove Player from Squad
  const handleConfirmRemovePlayer = async () => {
    if (!removingMember || !teamId) return;
    startOperation(`Baja y Desvinculación de Jugador: ${removingMember.user_name}`);

    try {
      const res = await removePlayerFromSquadAction(teamId, removingMember.user_id);
      if (res.success) {
        setRemovingMember(null);
        endSuccess(`El jugador ${removingMember.user_name} (@${removingMember.gamertag}) fue dado de baja de la plantilla.`);
        loadSquad();
        loadAllPlayers();
      } else {
        endError(res.error || 'Error al desvincular jugador de la escuadra.');
      }
    } catch (e: any) {
      endError(e?.message || 'Error de conexión al dar de baja al jugador.');
    }
  };

  // Toggle Organization Checkbox in Modal
  const toggleOrgSelection = (orgName: string) => {
    setSelectedContractOrgNames((prev) =>
      prev.includes(orgName) ? prev.filter((name) => name !== orgName) : [...prev, orgName]
    );
  };

  const handleSelectAllOrgs = () => {
    setSelectedContractOrgNames(contractOrgs.map((o) => o.name));
  };

  const handleDeselectAllOrgs = () => {
    setSelectedContractOrgNames([]);
  };

  // Action: Send Contract Offer (with Multi-Select Checkboxes per Organization)
  const handleSendContract = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!targetPlayer || !teamId || !currentUser) return;
    if (selectedContractOrgNames.length === 0) {
      alert('Debes seleccionar al menos una Organización para emitir la propuesta de contrato.');
      return;
    }
    setIsSendingContract(true);
    startOperation(`Emisión de ${selectedContractOrgNames.length} Oferta(s) de Contrato para ${targetPlayer.name} (@${targetPlayer.gamertag})`);

    try {
      const res = await sendClubContractOfferAction({
        teamId,
        playerUserId: targetPlayer.id,
        offeredByUserId: currentUser.id,
        position: contractPosition,
        organizationIds: selectedContractOrgNames,
        pitchMessage: contractTermsMessage || `Propuesta formal de contrato para unirse a ${teamName}.`,
        gameSlug,
      });

      if (res.success) {
        setIsContractModalOpen(false);
        setTargetPlayer(null);
        setContractTermsMessage('');
        endSuccess(`Se emitieron ${selectedContractOrgNames.length} contrato(s) independiente(s) por Organización para ${targetPlayer.name}.`);
        loadSentOffers();
      } else {
        endError(res.error || 'Error al enviar contratos.');
      }
    } catch (e: any) {
      endError(e?.message || 'Error al enviar propuestas de contrato.');
    } finally {
      setIsSendingContract(false);
    }
  };

  // Action: Cancel Sent Offer
  const handleCancelOffer = async (offerId: string, playerName: string) => {
    startOperation(`Cancelación de Oferta de Contrato enviada a ${playerName}`);
    try {
      const res = await cancelTransferOfferAction(offerId);
      if (res.success) {
        endSuccess(`La propuesta de contrato a ${playerName} fue revocada.`);
        loadSentOffers();
      } else {
        endError(res.error || 'Error al cancelar propuesta.');
      }
    } catch (e: any) {
      endError(e?.message || 'Error al cancelar oferta.');
    }
  };

  // Filter matrix by query
  const filteredMatrix = inscriptionsMatrix.filter((item) => {
    if (!matrixSearchQuery) return true;
    const q = matrixSearchQuery.toLowerCase();
    return (
      item.user_name?.toLowerCase().includes(q) ||
      item.gamertag?.toLowerCase().includes(q)
    );
  });

  return (
    <div className="space-y-6 pt-3 sm:pt-4 font-sans">
      {/* BANNER DE NOTIFICACIONES CRUD */}
      <CrudAlertBanner state={crudState} onClose={resetAlert} />

      {/* BANNER PRINCIPAL EXCLUSIVO DEL CLUB */}
      <Card className="p-4 bg-[var(--bg-card)] border border-[var(--border-card)] space-y-3 shadow-xl rounded-2xl">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div className="flex items-center gap-3">
            <div className="w-12 h-12 rounded-xl bg-[var(--bg-main)] border border-[var(--border-card)] flex items-center justify-center font-black text-sm text-[var(--accent-purple)] shadow-md">
              {teamTag}
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h2 className="text-lg font-black uppercase text-[var(--text-heading)] tracking-wide">{teamName}</h2>
                <Badge variant="violet" className="text-[10px] font-mono uppercase font-bold">
                  🛡️ Tu Escuadra Oficial
                </Badge>
              </div>
              <span className="text-xs font-mono text-[var(--text-muted)] block mt-0.5">
                Capitán Directivo: <strong className="text-[var(--accent-purple)]">{(myTeam as any)?.captain_name || myTeam?.captainName || currentUser?.name}</strong> • Disciplina: <span className="text-[var(--accent-cyan)] font-bold uppercase">{game.name}</span>
              </span>
            </div>
          </div>

          {/* Filtro por Organización del Torneo */}
          <div className="flex items-center gap-2 sm:w-72 shrink-0">
            <Building2 className="w-4 h-4 text-[var(--accent-purple)] shrink-0" />
            <div className="w-full">
              <label className="text-[10px] font-mono font-bold uppercase text-[var(--text-muted)] block mb-0.5">
                Filtrar Roster por Organización:
              </label>
              <Select
                value={selectedOrgFilter}
                onChange={(e) => setSelectedOrgFilter(e.target.value)}
