                    </Link>

                    <Link
                      href="/mensajes"
                      onClick={() => setIsUserMenuOpen(false)}
                      className="flex items-center gap-2.5 p-2 rounded-xl text-[var(--text-secondary)] hover:text-[var(--text-heading)] hover:bg-[var(--bg-card-hover)] transition-all"
                    >
                      <MessageSquare className="w-4 h-4 text-emerald-400" />
                      Centro de Mensajes
                    </Link>

                    {myTeamInActiveDiscipline && (
                      <button
                        onClick={() => {
                          setIsUserMenuOpen(false);
                          setIsClubManageOpen(true);
                        }}
                        className="w-full text-left flex items-center gap-2.5 p-2 rounded-xl text-purple-300 bg-purple-500/10 hover:bg-purple-500/20 border border-purple-500/30 transition-all font-bold"
                      >
                        <Shield className="w-4 h-4 text-purple-400" />
                        <span>Opciones del Club (Gestión Capitán/Staff)</span>
                      </button>
                    )}

                    <button
                      onClick={() => {
                        setIsUserMenuOpen(false);
                        logout();
                        router.push('/login');
                      }}
                      className="w-full text-left flex items-center gap-2.5 p-2 rounded-xl text-rose-400 hover:bg-rose-500/10 transition-colors pt-2 border-t border-[var(--border-card)] mt-1"
                    >
                      <LogOut className="w-4 h-4" />
                      Cerrar Sesión
                    </button>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      </header>

      {/* Create Team Modal Dialog */}
      <CreateTeamModal
        isOpen={isCreateTeamOpen}
        defaultGameSlug={activeGameSlug}
        onClose={() => setIsCreateTeamOpen(false)}
        onSuccess={(team) => {
          router.push(`/${team.gameSlug}/equipos/${team.id}`);
        }}
      />

      {/* Club Management Modal Dialog Pre-Filtered for Active Discipline */}
      {myTeamInActiveDiscipline && (
        <ClubManagementModal
          team={myTeamInActiveDiscipline}
          isOpen={isClubManageOpen}
          onClose={() => setIsClubManageOpen(false)}
        />
      )}
    </>
  );
}

'use client';

import React, { useState } from 'react';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { useAuth } from '@/components/providers/auth-provider';
import { GameConfig } from '@/lib/games-data';
import { initialTeams } from '@/lib/data-store';
import {
  Gamepad2, User, Shield, Home, Trophy, Award, ArrowRightLeft, Users, Star, PieChart, Database, Sparkles, Settings, FileText, BarChart2, LayoutDashboard
} from 'lucide-react';

export type MobileSubnavSegment = 'game' | 'athlete' | 'club';

interface MobileResponsiveSubnavbarProps {
  game: GameConfig;
  activeSection?: string;
  onSelectSection?: (section: any) => void;
}

export function MobileResponsiveSubnavbar({ game, onSelectSection }: MobileResponsiveSubnavbarProps) {
  const pathname = usePathname();
  const { currentUser, userTeams, isAuthenticated } = useAuth();
  const [activeSegment, setActiveSegment] = useState<MobileSubnavSegment>('game');

  const roleStr = (currentUser?.role || '').toLowerCase();
  const isAdminOrOrganizer = roleStr === 'administrador' || roleStr === 'admin' || roleStr === 'organizador';

  // Check if user has team in THIS active discipline
  const teamsPool = userTeams && userTeams.length > 0 ? userTeams : initialTeams;
  const myTeam = teamsPool.find(
    (t) =>
      t.gameSlug === game.slug &&
      (t.captainName?.toLowerCase() === currentUser?.name?.toLowerCase() ||
        t.captainName?.toLowerCase() === currentUser?.gamertag?.toLowerCase() ||
        t.id === currentUser?.teamId)
  );

  // 1. Game Sections
  const gameSections = [
    { id: 'home', label: 'Home', href: `/${game.slug}`, icon: <Home className="w-3.5 h-3.5" /> },
    { id: 'organizaciones', label: 'Torneos', href: `/${game.slug}/organizaciones`, icon: <Trophy className="w-3.5 h-3.5" /> },
    { id: 'equipos', label: 'Equipos', href: `/${game.slug}/equipos`, icon: <Users className="w-3.5 h-3.5" /> },
    { id: 'clasificacion', label: 'Clasificación', href: `/${game.slug}/clasificacion`, icon: <Award className="w-3.5 h-3.5" /> },
    { id: 'traspasos', label: 'Fichajes', href: `/${game.slug}/traspasos`, icon: <ArrowRightLeft className="w-3.5 h-3.5" /> },
    { id: 'tops', label: 'Tops', href: `/${game.slug}/tops`, icon: <Star className="w-3.5 h-3.5" /> },
    { id: 'infografia', label: 'Stats', href: `/${game.slug}/infografia`, icon: <PieChart className="w-3.5 h-3.5" /> },
    { id: 'datos', label: 'Datos', href: `/${game.slug}/datos`, icon: <Database className="w-3.5 h-3.5" /> },
  ];

  const userId = currentUser?.id || 'usr-1784762163316';

  // 2. Athlete User Options
  const athleteOptions = [
    { id: 'dashboard', label: 'Dashboard', href: `/${game.slug}/jugadores/${userId}`, icon: <LayoutDashboard className="w-3.5 h-3.5" /> },
    { id: 'stats', label: 'Mis Stats', href: `/${game.slug}/stats`, icon: <BarChart2 className="w-3.5 h-3.5" /> },
    { id: 'ofertas', label: 'Mis Ofertas', href: `/${game.slug}/ofertas`, icon: <FileText className="w-3.5 h-3.5" /> },
    { id: 'ajustes', label: 'Ajustes', href: `/${game.slug}/atleta-ajustes`, icon: <Settings className="w-3.5 h-3.5" /> },
  ];

  // 3. Club Captain Options
  const clubOptions = [
    { id: 'dashboard', label: 'Dashboard', href: myTeam ? `/${game.slug}/equipos/${myTeam.id}` : `/${game.slug}/ajustes`, icon: <LayoutDashboard className="w-3.5 h-3.5" /> },
    { id: 'plantilla', label: 'Plantilla', href: `/${game.slug}/plantilla`, icon: <Users className="w-3.5 h-3.5" /> },
    { id: 'reclutamiento', label: 'Vacantes', href: `/${game.slug}/reclutamiento`, icon: <Sparkles className="w-3.5 h-3.5" /> },
    { id: 'matchday', label: 'Matchday', href: `/${game.slug}/matchday`, icon: <Award className="w-3.5 h-3.5" /> },
    { id: 'ajustes', label: 'Ajustes', href: `/${game.slug}/ajustes`, icon: <Settings className="w-3.5 h-3.5" /> },
  ];

  return (
    <div className="block md:hidden w-full bg-slate-950 border-b border-[var(--border-card)] shadow-lg">

      {/* 1. Top Mobile Segmented Controller (1 Row) */}
      <div className="flex items-center justify-around border-b border-white/10 p-1 bg-slate-900/90 text-xs font-black">

        {/* Segment 1: JUEGO */}
        <button
          onClick={() => setActiveSegment('game')}
          className={`flex-1 py-1.5 px-2 rounded-lg transition-all flex items-center justify-center gap-1.5 ${
            activeSegment === 'game'
              ? 'bg-cyan-500 text-slate-950 shadow-md font-black'
              : 'text-slate-400 hover:text-white'
          }`}
        >
          <Gamepad2 className="w-3.5 h-3.5" />
          <span>Juego</span>
        </button>

        {/* Segment 2: ATLETA (Users) */}
        {!isAdminOrOrganizer && isAuthenticated && (
          <button
            onClick={() => setActiveSegment('athlete')}
            className={`flex-1 py-1.5 px-2 rounded-lg transition-all flex items-center justify-center gap-1.5 ${
              activeSegment === 'athlete'
                ? 'bg-cyan-500 text-slate-950 shadow-md font-black'
                : 'text-slate-400 hover:text-white'
            }`}
          >
            <User className="w-3.5 h-3.5" />
            <span>Atleta</span>
          </button>
        )}

        {/* Segment 3: CLUB (Captains) */}
        {!isAdminOrOrganizer && isAuthenticated && myTeam && (
          <button
            onClick={() => setActiveSegment('club')}
            className={`flex-1 py-1.5 px-2 rounded-lg transition-all flex items-center justify-center gap-1.5 ${
              activeSegment === 'club'
                ? 'bg-purple-600 text-white shadow-md font-black'
                : 'text-slate-400 hover:text-white'
            }`}
          >
            <Shield className="w-3.5 h-3.5 text-purple-400" />
            <span>Club</span>
          </button>
        )}

      </div>

      {/* 2. Active Segment Scrollable Options Bar */}
      <div className="py-2 px-3 flex items-center gap-1.5 overflow-x-auto scrollbar-none touch-pan-x">

        {/* Render JUEGO Options */}
        {activeSegment === 'game' &&
          gameSections.map((sec) => {
            const isActive = pathname === sec.href || (sec.id === 'home' && pathname === `/${game.slug}`);
            return (
              <Link
                key={sec.id}
                href={sec.href}
                onClick={() => onSelectSection && onSelectSection(sec.id)}
                className={`px-3 py-1 rounded-xl text-xs font-extrabold flex items-center gap-1.5 whitespace-nowrap flex-shrink-0 border transition-all ${
                  isActive
                    ? 'bg-cyan-500 text-slate-950 border-cyan-400 shadow-md font-black'
                    : 'bg-slate-900/80 text-slate-300 border-white/10 hover:bg-slate-800'
                }`}
              >
                {sec.icon}
                <span>{sec.label}</span>
              </Link>
            );
          })}

        {/* Render ATLETA Options */}
        {activeSegment === 'athlete' &&
          athleteOptions.map((opt) => {
            const isActive = pathname === opt.href;
            return (
              <Link
                key={opt.id}
                href={opt.href}
                className={`px-3 py-1 rounded-xl text-xs font-extrabold flex items-center gap-1.5 whitespace-nowrap flex-shrink-0 border transition-all ${
                  isActive
                    ? 'bg-cyan-500 text-slate-950 border-cyan-400 shadow-md font-black'
                    : 'bg-cyan-950/70 text-cyan-200 border-cyan-500/40 hover:bg-cyan-900'
                }`}
              >
                {opt.icon}
                <span>{opt.label}</span>
              </Link>
            );
          })}

        {/* Render CLUB Options */}
        {activeSegment === 'club' &&
          clubOptions.map((opt) => {
            const isActive = pathname === opt.href;
            return (
              <Link
                key={opt.id}
                href={opt.href}
                className={`px-3 py-1 rounded-xl text-xs font-extrabold flex items-center gap-1.5 whitespace-nowrap flex-shrink-0 border transition-all ${
                  isActive
                    ? 'bg-purple-600 text-white border-purple-400 shadow-md font-black'
                    : 'bg-purple-950/70 text-purple-200 border-purple-500/40 hover:bg-purple-900'
                }`}
              >
                {opt.icon}
                <span>{opt.label}</span>
              </Link>
            );
          })}

      </div>
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { useAuth } from '@/components/providers/auth-provider';
import { initialTeams } from '@/lib/data-store';
import { Shield, Users, Sparkles, Award, Settings, LayoutDashboard, SlidersHorizontal } from 'lucide-react';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { ClubManagementModal } from '@/components/teams/club-management-modal';

export function TeamClubSubnavbar() {
  const pathname = usePathname();
  const { currentUser, activeGameSlug, userTeams } = useAuth();
  const [isClubManageOpen, setIsClubManageOpen] = useState(false);

  if (!currentUser) return null;

  const uId = currentUser.id;
  const uName = currentUser.name?.toLowerCase();
  const uGamer = currentUser.gamertag?.toLowerCase();

  const teamsPool = userTeams && userTeams.length > 0 ? userTeams : initialTeams;

  // Filter team where user is Captain or Encargado or Admin
  const isUserTeamManager = (t: any) => {
    if (!t) return false;
    const slug = (t as any).game_slug || t.gameSlug || 'eafc26';
    if (slug !== activeGameSlug && activeGameSlug !== 'ALL') return false;

    const cId = t.captain_id || t.captainId;
    const cName = (t.captain_name || t.captainName || '').toLowerCase();

    // 1. Official Captain Check
    if (cId && cId === uId) return true;
    if (cName && (cName === uName || cName === uGamer)) return true;
    if (currentUser.teamId && t.id === currentUser.teamId) return true;

    // 2. N Encargados Check
    const encs = t.encargados || t.encargados_json;
    if (encs) {
      try {
        const arr = typeof encs === 'string' ? JSON.parse(encs) : encs;
        if (Array.isArray(arr)) {
          const isEnc = arr.some((enc: any) => {
            if (typeof enc === 'string') return enc === uId || enc.toLowerCase() === uName || enc.toLowerCase() === uGamer;
            return (
              enc.id === uId ||
              (enc.name && uName && enc.name.toLowerCase() === uName) ||
              (enc.gamertag && uGamer && enc.gamertag.toLowerCase() === uGamer)
            );
          });
          if (isEnc) return true;
        }
      } catch {}
    }

    // 3. Fallback for Admin/Organizer
    if (currentUser.role === 'Administrador' || currentUser.role === 'Organizador') {
      return true;
    }

    return false;
  };

  const myTeam = teamsPool.find(isUserTeamManager);
  if (!myTeam) return null;

  const teamOptions = [
    { href: `/${activeGameSlug}/equipos/${myTeam.id}`, label: 'Dashboard Club', icon: <LayoutDashboard className="w-3.5 h-3.5" /> },
    { href: `/${activeGameSlug}/plantilla`, label: 'Plantilla Roster', icon: <Users className="w-3.5 h-3.5" />, badge: `${myTeam.membersCount || 0}` },
    { href: `/${activeGameSlug}/reclutamiento`, label: 'Vacantes & Fichajes', icon: <Sparkles className="w-3.5 h-3.5" /> },
    { href: `/${activeGameSlug}/matchday`, label: 'Convocatorias', icon: <Award className="w-3.5 h-3.5" /> },
    { href: `/${activeGameSlug}/ajustes`, label: 'Ajustes Club', icon: <Settings className="w-3.5 h-3.5" /> },
  ];

  return (
    <>
      <div className="w-full bg-slate-950/90 border-b border-purple-500/30 backdrop-blur-md z-20 py-1.5 px-4 sm:px-6 lg:px-8 shadow-sm">
        <div className="max-w-7xl mx-auto flex items-center justify-between gap-3 overflow-x-auto scrollbar-none">

          {/* Label Badge */}
          <div className="flex items-center gap-2 flex-shrink-0">
            <span className="text-[10px] font-black uppercase text-purple-400 tracking-wider flex items-center gap-1">
              <Shield className="w-3.5 h-3.5 text-purple-400" />
              🛡️ OPCIONES DEL EQUIPO (CLUB):
            </span>
            <Badge variant="violet" className="text-[9px] px-2 py-0.5 font-mono font-black uppercase shadow-sm">
              {myTeam.name}
            </Badge>

            <Button
              size="sm"
              onClick={() => setIsClubManageOpen(true)}
              className="text-[10px] font-mono font-bold bg-purple-600 hover:bg-purple-500 text-white h-6 px-2 rounded-lg flex items-center gap-1 shadow-md ml-1"
            >
              <SlidersHorizontal className="w-3 h-3" />
              <span>Gestión Rápida</span>
            </Button>
          </div>

          {/* Action Link Pills */}
          <div className="flex items-center gap-1.5 overflow-x-auto scrollbar-none">
            {teamOptions.map((opt) => {
              const isActive = pathname === opt.href;
              return (
                <Link
                  key={opt.href}
                  href={opt.href}
                  className={`px-3 py-1 rounded-xl text-xs font-extrabold transition-all flex items-center gap-1.5 flex-shrink-0 shadow-sm border ${
                    isActive
                      ? 'bg-purple-600 text-white border-purple-400 font-black shadow-md'
                      : 'bg-purple-950/70 hover:bg-purple-900 border-purple-500/40 text-purple-200'
                  }`}
                >
                  {opt.icon}
                  <span>{opt.label}</span>
                  {opt.badge && (
                    <span className="text-[9px] font-mono font-black px-1 rounded bg-slate-950 text-purple-300">
                      {opt.badge}
                    </span>
                  )}
                </Link>
              );
            })}
          </div>

        </div>
      </div>

      {/* Modal interactivo de gestion de club */}
      {isClubManageOpen && (
        <ClubManagementModal
          isOpen={isClubManageOpen}
          onClose={() => setIsClubManageOpen(false)}
          team={myTeam}
        />
      )}
    </>
  );
}

