'use client';

import React, { useState, useEffect } from 'react';
import { TeamData, UserProfile } from '@/lib/data-store';
import { GAMES_CATALOG } from '@/lib/games-data';
import { useAuth } from '@/components/providers/auth-provider';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Avatar } from '@/components/ui/avatar';
import {
  Shield, Users, Plus, Trash2, CheckCircle2, UserCheck, Settings, Sparkles, X, Award, Check
} from 'lucide-react';

export type TeamTabOption = 'EQUIPO_ROSTER' | 'EQUIPO_RECLUTAMIENTO' | 'EQUIPO_MATCHDAY' | 'EQUIPO_AJUSTES';

interface TeamManagementModalProps {
  team: TeamData;
  isOpen: boolean;
  onClose: () => void;
  initialTab?: TeamTabOption;
  onUpdateTeam?: (updatedTeam: TeamData) => void;
}

export function TeamManagementModal({
  team,
  isOpen,
  onClose,
  initialTab = 'EQUIPO_ROSTER',
  onUpdateTeam,
}: TeamManagementModalProps) {
  const { currentUser } = useAuth();
  const [activeTab, setActiveTab] = useState<TeamTabOption>(initialTab);

  useEffect(() => {
    if (initialTab) {
      setActiveTab(initialTab);
    }
  }, [initialTab]);

  const [currentTeam, setCurrentTeam] = useState<TeamData>(team);
  const [newVacantInput, setNewVacantInput] = useState('');
  const [successNotice, setSuccessNotice] = useState('');

  const [membersList, setMembersList] = useState<UserProfile[]>(
    team.members && team.members.length > 0
      ? team.members
      : [
          currentUser || {
            id: 'usr-current',
            name: 'Sebastián Rodríguez',
            gamertag: 'SrDeLorean',
            role: 'Capitán',
            primaryGame: 'eafc26',
            platform: 'CROSSPLAY',
            position: 'DFC',
            status: 'En Escuadra',
            rating: '9.8',
          },
          {
            id: 'usr-m1',
            name: 'Lucas Benítez',
            gamertag: 'Vhaex_CS',
            role: 'Jugador',
            primaryGame: 'csgo',
            platform: 'PC',
            position: 'AWPer',
            status: 'En Escuadra',
            rating: '9.4',
          },
          {
            id: 'usr-m2',
            name: 'Joaquín Silva',
            gamertag: 'SG Jotta',
            role: 'Jugador',
            primaryGame: 'eafc26',
            platform: 'PS5',
            position: 'DC',
            status: 'En Escuadra',
            rating: '9.6',
          },
        ]
  );

  const [starters, setStarters] = useState<string[]>([membersList[0]?.id || 'usr-current']);

  if (!isOpen) return null;

  const gameObj = GAMES_CATALOG[currentTeam.gameSlug] || GAMES_CATALOG['eafc26'];

  const handleAddVacant = () => {
    if (!newVacantInput.trim()) return;
    const updatedVacants = [...currentTeam.vacantPositions, newVacantInput.trim().toUpperCase()];
    const updated = { ...currentTeam, vacantPositions: updatedVacants };
    setCurrentTeam(updated);
    if (onUpdateTeam) onUpdateTeam(updated);
    setNewVacantInput('');
    setSuccessNotice('Vacante de reclutamiento agregada exitosamente');
    setTimeout(() => setSuccessNotice(''), 3000);
  };

  const handleRemoveVacant = (posToRemove: string) => {
    const updatedVacants = currentTeam.vacantPositions.filter((p) => p !== posToRemove);
    const updated = { ...currentTeam, vacantPositions: updatedVacants };
    setCurrentTeam(updated);
    if (onUpdateTeam) onUpdateTeam(updated);
  };

  const handleToggleStarter = (id: string) => {
    if (starters.includes(id)) {
      setStarters(starters.filter((s) => s !== id));
    } else {
      setStarters([...starters, id]);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/85 backdrop-blur-md p-4 overflow-y-auto">
      <div className="w-full max-w-3xl glass-panel p-6 sm:p-8 rounded-3xl border border-purple-500/40 space-y-6 shadow-2xl animate-in fade-in zoom-in-95 my-8">

        {/* Header */}
        <div className="flex items-center justify-between border-b border-[var(--border-card)] pb-4">
          <div className="flex items-center gap-3">
            <div
              className="w-12 h-12 rounded-2xl bg-slate-950 border-2 flex items-center justify-center font-black text-xl shadow-xl flex-shrink-0"
              style={{ borderColor: currentTeam.color || '#00F0FF', color: currentTeam.color || '#00F0FF' }}
            >
              {currentTeam.logoText}
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h3 className="text-xl font-black uppercase text-white">
                  {currentTeam.name}
                </h3>
                <Badge variant="violet">🛡️ Panel de Gestión del Club</Badge>
              </div>
              <p className="text-xs text-[var(--text-secondary)] font-medium">
                Administración exclusiva de plantilla, vacantes de reclutamiento y convocatorias de {gameObj.name}
              </p>
            </div>
          </div>

          <button onClick={onClose} className="p-1 rounded-xl text-[var(--text-muted)] hover:text-white">
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Success Notice */}
        {successNotice && (
          <div className="p-3 rounded-xl bg-emerald-950/90 border border-emerald-500/50 text-emerald-300 text-xs font-bold flex items-center gap-2">
            <CheckCircle2 className="w-4 h-4 text-emerald-400" />
            <span>{successNotice}</span>
          </div>
        )}

        {/* Team Management Only Tabs Strip */}
        <div className="flex items-center gap-2 overflow-x-auto scrollbar-none p-1 rounded-2xl bg-slate-950 border border-purple-500/30">
          <button
            onClick={() => setActiveTab('EQUIPO_ROSTER')}
            className={`px-4 py-2 rounded-xl text-xs font-black uppercase transition-all flex items-center gap-1.5 flex-shrink-0 ${
              activeTab === 'EQUIPO_ROSTER'
                ? 'bg-purple-600 text-white shadow-md'
                : 'text-[var(--text-secondary)] hover:text-white'
            }`}
          >
            <Users className="w-3.5 h-3.5" />
            Plantilla & Roster ({membersList.length})
          </button>

          <button
            onClick={() => setActiveTab('EQUIPO_RECLUTAMIENTO')}
            className={`px-4 py-2 rounded-xl text-xs font-black uppercase transition-all flex items-center gap-1.5 flex-shrink-0 ${
              activeTab === 'EQUIPO_RECLUTAMIENTO'
                ? 'bg-amber-500 text-slate-950 shadow-md'
                : 'text-[var(--text-secondary)] hover:text-white'
            }`}
          >
            <Sparkles className="w-3.5 h-3.5" />
            Reclutamiento ({currentTeam.vacantPositions.length})
          </button>

          <button
            onClick={() => setActiveTab('EQUIPO_MATCHDAY')}
            className={`px-4 py-2 rounded-xl text-xs font-black uppercase transition-all flex items-center gap-1.5 flex-shrink-0 ${
              activeTab === 'EQUIPO_MATCHDAY'
                ? 'bg-emerald-500 text-slate-950 shadow-md'
                : 'text-[var(--text-secondary)] hover:text-white'
            }`}
          >
            <Award className="w-3.5 h-3.5" />
            Alineación Matchday ({starters.length})
          </button>

          <button
            onClick={() => setActiveTab('EQUIPO_AJUSTES')}
            className={`px-4 py-2 rounded-xl text-xs font-black uppercase transition-all flex items-center gap-1.5 flex-shrink-0 ${
              activeTab === 'EQUIPO_AJUSTES'
                ? 'bg-slate-800 text-white shadow-md'
                : 'text-[var(--text-secondary)] hover:text-white'
            }`}
          >
            <Settings className="w-3.5 h-3.5" />
            Ajustes Club
          </button>
        </div>

        {/* TAB 1: PLANTILLA ROSTER POR TORNEO / COMPETENCIA */}
        {activeTab === 'EQUIPO_ROSTER' && (
          <div className="space-y-4">
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 p-3 rounded-2xl bg-slate-900 border border-purple-500/30">
              <div>
                <span className="text-[10px] font-black uppercase text-purple-400 block tracking-wider">
                  🏆 Competencia / Torneo Activo
                </span>
                <span className="text-xs font-black text-white block">
                  Liga Élite Pro 11v11 2026 ({gameObj.name})
                </span>
              </div>

              <div className="flex items-center gap-2">
                <Badge variant="cyan" className="font-mono font-bold text-xs">
                  Plantilla Habilitada: {membersList.length} Atletas
                </Badge>
              </div>
            </div>

            <div className="p-3 rounded-xl bg-purple-950/40 border border-purple-500/30 text-purple-300 text-[11px] font-medium leading-relaxed">
              💡 <strong>Regla de Inscripción Multi-Torneo:</strong> Las plantillas se registran por torneo específico. Un atleta puede integrar esta plantilla para la <em>Liga Élite 2026</em> y estar inscrito con otro club en una competencia distinta sin causar conflicto.
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 max-h-72 overflow-y-auto pr-1">
              {membersList.map((member, idx) => (
                <div key={member.id} className="p-3.5 rounded-2xl bg-[var(--bg-main)] border border-[var(--border-card)] flex items-center justify-between gap-3 text-xs">
                  <div className="flex items-center gap-3">
                    <Avatar fallback={member.name} size="md" status="online" />
                    <div>
                      <span className="font-extrabold text-sm text-white block">{member.name}</span>
                      <span className="text-[var(--text-muted)] font-mono text-[11px]">@{member.gamertag}</span>
                    </div>
                  </div>

                  <div className="flex items-center gap-2">
                    <Badge variant="cyan">{member.position}</Badge>
                    <span className="text-[10px] font-mono font-bold px-2 py-0.5 rounded bg-slate-900 text-emerald-400 border border-emerald-700">
                      Habilitado
                    </span>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* TAB 2: RECLUTAMIENTO & VACANTES */}
        {activeTab === 'EQUIPO_RECLUTAMIENTO' && (
          <div className="space-y-4">
            <div className="space-y-1">
              <h4 className="font-black text-sm uppercase text-white">Publicar Vacantes de Reclutamiento</h4>
              <p className="text-xs text-[var(--text-secondary)]">
                Las posiciones agregadas aparecerán en el Mercado de Traspasos para atraer atletas libres.
              </p>
            </div>

            <div className="flex items-center gap-2">
              <input
                type="text"
                placeholder="ej. DFC, AWPer, Duelista, MID..."
                value={newVacantInput}
                onChange={(e) => setNewVacantInput(e.target.value)}
                className="flex-1 px-4 py-2.5 rounded-xl input-theme border border-[var(--border-card)] text-xs font-extrabold uppercase"
              />
              <Button onClick={handleAddVacant} size="sm" className="font-bold text-xs bg-[var(--accent-cyan)] text-slate-950">
                <Plus className="w-4 h-4 mr-1" />
                Agregar Vacante
              </Button>
            </div>

            <div className="space-y-2 pt-2">
              <span className="text-xs font-bold uppercase text-white block">Vacantes Activas:</span>
              <div className="flex items-center gap-2 flex-wrap">
                {currentTeam.vacantPositions.map((pos) => (
                  <span key={pos} className="px-3.5 py-1.5 rounded-xl bg-amber-950/80 border border-amber-500/40 text-amber-300 font-mono font-bold text-xs flex items-center gap-2.5">
                    <span>+ Vacante: {pos}</span>
                    <button onClick={() => handleRemoveVacant(pos)} className="text-amber-400 hover:text-rose-400">
                      <Trash2 className="w-3.5 h-3.5" />
                    </button>
                  </span>
                ))}
              </div>
            </div>
          </div>
        )}

        {/* TAB 3: ALINEACIÓN MATCHDAY */}
        {activeTab === 'EQUIPO_MATCHDAY' && (
          <div className="space-y-4">
            <div className="flex items-center justify-between border-b border-[var(--border-card)] pb-3">
              <div>
                <h4 className="font-black text-sm uppercase text-white">Alineación Titular Matchday</h4>
                <p className="text-xs text-[var(--text-secondary)]">Haz clic para convocar a los titulares del partido</p>
              </div>
              <Badge variant="cyan" className="font-mono font-bold">{starters.length} Titulares Seleccionados</Badge>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              {membersList.map((m) => {
                const isSelected = starters.includes(m.id);

                return (
                  <button
                    key={m.id}
                    onClick={() => handleToggleStarter(m.id)}
                    className={`p-3.5 rounded-2xl border text-left flex items-center justify-between transition-all ${
                      isSelected
                        ? 'bg-emerald-950/60 border-emerald-500/60 shadow-lg'
                        : 'bg-[var(--bg-main)] border-[var(--border-card)] opacity-75 hover:opacity-100'
                    }`}
                  >
                    <div className="flex items-center gap-3">
                      <Avatar fallback={m.name} size="sm" />
                      <div>
                        <span className="font-extrabold text-xs text-white block">{m.name}</span>
                        <span className="text-[10px] text-[var(--text-muted)] font-mono">@{m.gamertag} • {m.position}</span>
                      </div>
                    </div>

                    <div className={`w-6 h-6 rounded-full flex items-center justify-center font-bold text-xs ${isSelected ? 'bg-emerald-500 text-slate-950' : 'bg-slate-800 text-slate-500'}`}>
                      {isSelected ? <Check className="w-4 h-4" /> : '+'}
                    </div>
                  </button>
                );
              })}
            </div>
          </div>
        )}

        {/* TAB 4: AJUSTES CLUB */}
        {activeTab === 'EQUIPO_AJUSTES' && (
          <div className="space-y-4 text-xs font-semibold">
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="space-y-1.5">
                <label className="text-xs font-bold uppercase text-white block">Nombre del Club</label>
                <input
                  type="text"
                  value={currentTeam.name}
                  onChange={(e) => setCurrentTeam({ ...currentTeam, name: e.target.value.toUpperCase() })}
                  className="w-full px-3.5 py-2.5 rounded-xl input-theme border border-[var(--border-card)] font-black uppercase text-xs"
                />
              </div>

              <div className="space-y-1.5">
                <label className="text-xs font-bold uppercase text-white block">Tag / Sigla</label>
                <input
                  type="text"
                  value={currentTeam.tag}
                  onChange={(e) => setCurrentTeam({ ...currentTeam, tag: e.target.value.toUpperCase() })}
                  className="w-full px-3.5 py-2.5 rounded-xl input-theme border border-[var(--border-card)] font-black uppercase text-xs"
                />
              </div>
            </div>

            <div className="space-y-1.5">
              <label className="text-xs font-bold uppercase text-white block">Descripción del Club</label>
              <textarea
                rows={3}
                value={currentTeam.description}
                onChange={(e) => setCurrentTeam({ ...currentTeam, description: e.target.value })}
                className="w-full px-3.5 py-2.5 rounded-xl input-theme border border-[var(--border-card)] font-medium text-xs"
              />
            </div>
          </div>
        )}

        {/* Footer */}
        <div className="flex items-center justify-end border-t border-[var(--border-card)] pt-4">
          <Button onClick={onClose} size="sm" className="font-bold text-xs bg-purple-600 hover:bg-purple-500 text-white">
            Guardar & Cerrar
          </Button>
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import Link from 'next/link';
import Image from 'next/image';
import { TeamData } from '@/lib/data-store';
import { Badge } from '@/components/ui/badge';
import { Avatar } from '@/components/ui/avatar';
import { Button } from '@/components/ui/button';
import { SubSubNavbar, SubSubTabOption } from '@/components/layout/sub-sub-navbar';
import { ClubManagementModal } from '@/components/teams/club-management-modal';
import {
  Users, Calendar, ArrowRightLeft, BarChart3, History, Monitor, Award, CheckCircle2, MessageSquare, Sparkles, Settings
} from 'lucide-react';

import { getNewTeamSquadAction } from '@/app/actions/new-squads';
import { getSentContractsByTeamAction } from '@/app/actions/new-transfers';
import { GAMES_CATALOG } from '@/lib/games-data';
import { ClassificationView } from '@/components/tournaments/classification-view';
import { FixtureScheduleView } from '@/components/tournaments/fixture-schedule-view';
import { shouldBypassImageOptimization } from '@/lib/image-utils';

interface TeamProfileViewProps {
  team: TeamData;
  onBack?: () => void;
  brandColor?: string;
}

export type ProfileTab = 'plantilla' | 'posiciones' | 'calendario' | 'traspasos' | 'estadisticas' | 'historico';

export function TeamProfileView({ team, brandColor = '#00F0FF' }: TeamProfileViewProps) {
  const [activeTab, setActiveTab] = useState<ProfileTab>('plantilla');
  const [isManageModalOpen, setIsManageModalOpen] = useState(false);

  const [squad, setSquad] = useState<any[]>([]);
  const [contracts, setContracts] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  React.useEffect(() => {
    async function loadData() {
      setIsLoading(true);
      try {
        const [sqRes, cRes] = await Promise.all([
          getNewTeamSquadAction(team.id),
          getSentContractsByTeamAction(team.id)
        ]);
        if (sqRes.success) setSquad(sqRes.squad);
        if (cRes.success) setContracts(cRes.offers);
      } catch {}
      setIsLoading(false);
    }
    loadData();
  }, [team.id]);

  const game = GAMES_CATALOG[(team as any).gameSlug || 'eafc26'];

  // Dynamic theme color for team profile matching the active game
  const activeColor = brandColor || team.color || '#00F0FF';

  // Sub-Sub-Menu Tabs Definition following the system standard
  const profileSubSubTabs: SubSubTabOption<ProfileTab>[] = [
    { id: 'plantilla', label: 'Plantilla Roster', icon: <Users className="w-3.5 h-3.5" />, badge: 8 },
    { id: 'posiciones', label: 'Posiciones Liga', icon: <Award className="w-3.5 h-3.5" /> },
    { id: 'calendario', label: 'Calendario Partidos', icon: <Calendar className="w-3.5 h-3.5" /> },
    { id: 'traspasos', label: 'Fichajes & Bajas', icon: <ArrowRightLeft className="w-3.5 h-3.5" /> },
    { id: 'estadisticas', label: 'Estadísticas', icon: <BarChart3 className="w-3.5 h-3.5" /> },
    { id: 'historico', label: 'Histórico & Palmarés', icon: <History className="w-3.5 h-3.5" /> },
  ];

  // Group real squad by organization
  const squadByOrg = squad.reduce((acc: any, player: any) => {
    const orgs = player.original_orgs && player.original_orgs.length > 0 ? player.original_orgs : ['Plantilla Base'];
    orgs.forEach((org: string) => {
      if (!acc[org]) acc[org] = [];
      if (!acc[org].find((p: any) => p.user_id === player.user_id)) {
         acc[org].push(player);
      }
    });
    return acc;
  }, {});

  const vacantPositions = ['DFC', 'LI', 'MCD'];

  const teamBanner = team?.bannerUrl || '/images/hero.jpg';
  const teamLogo = team?.logoUrl || (team as TeamData & { logo?: string }).logo;
  const teamLogoText = team?.logoText || team?.tag || team?.name?.substring(0, 3)?.toUpperCase() || 'TP';
  const teamName = team?.name || 'Escuadra eSports';
  const teamTag = team?.tag || 'TP';
  const teamDesc = team?.description || 'Escuadra registrada en el circuito eSports.';

  return (
    <div className="space-y-6 sm:space-y-8 animate-in fade-in duration-300 -mt-px">
      {/* 1. Full-Width Edge-to-Edge Banner Background Header (100% Unfiltered Image) */}
      <div className="relative w-full left-1/2 right-1/2 -ml-[50vw] -mr-[50vw] w-screen bg-slate-950 border-b border-[var(--border-card)] shadow-2xl overflow-hidden min-h-[240px] sm:min-h-[340px] flex flex-col justify-end">
        {/* Full Bleed Banner Image Graphic (Pure 100% Opacity, Zero Filter) */}
        <div className="absolute inset-0 z-0">
          <Image
            src={teamBanner}
            alt={teamName}
            fill
            sizes="100vw"
            priority
            unoptimized={shouldBypassImageOptimization(teamBanner)}
            onError={(e) => {
              e.currentTarget.src = '/images/default/banner-default.jpg';
            }}
            className="object-cover opacity-100"
          />
          {/* Bottom Fade gradient for text readability only */}
          <div className="absolute inset-0 bg-gradient-to-t from-slate-950 via-slate-950/40 to-transparent" />
        </div>

        {/* Content Box Layered Over the Full Width Banner */}
        <div className="max-w-7xl mx-auto w-full px-4 sm:px-6 lg:px-8 py-4 sm:py-8 relative z-10 flex flex-col sm:flex-row sm:items-end justify-between gap-4 sm:gap-6">
          <div className="flex flex-row items-center gap-3 sm:gap-6">
            {/* Team Crest Shield */}
            <div
              className="relative w-16 h-16 sm:w-24 sm:h-24 rounded-xl sm:rounded-2xl bg-slate-950 border-2 sm:border-4 flex items-center justify-center font-black text-lg sm:text-3xl shadow-2xl flex-shrink-0 overflow-hidden"
              style={{ borderColor: activeColor, color: activeColor }}
            >
              {teamLogo ? (
                <Image
                  src={teamLogo}
                  alt={teamName}
                  fill
                  sizes="96px"
                  unoptimized={shouldBypassImageOptimization(teamLogo)}
                  onError={(e) => {
                    e.currentTarget.src = '/images/default/logo-default.png';
                  }}
                  className="object-cover"
                />
              ) : (
                teamLogoText
              )}
            </div>

            {/* Team Details */}
            <div className="space-y-1">
              <div className="flex items-center gap-2 flex-wrap">
                <h1 className="text-xl sm:text-3xl font-black text-white tracking-tight uppercase drop-shadow-md">
                  {teamName}
                </h1>
                <span
                  className="px-2.5 py-0.5 rounded-md text-xs font-mono font-bold border"
                  style={{
                    backgroundColor: `color-mix(in srgb, ${activeColor} 30%, transparent)`,
                    borderColor: activeColor,
                    color: '#FFFFFF',
                  }}
                >
                  {teamTag}
                </span>
              </div>

              <p className="text-xs sm:text-sm text-slate-200 font-medium line-clamp-1 drop-shadow-sm">
                {teamDesc}
              </p>

              <div className="flex items-center gap-3 text-xs text-slate-300 pt-1 flex-wrap font-semibold">
                <span className="flex items-center gap-1">
                  <Monitor className="w-3.5 h-3.5" style={{ color: activeColor }} />
                  {team.platform}
                </span>
                <span>•</span>
                <span className="flex items-center gap-1 text-emerald-400 font-bold">
                  <CheckCircle2 className="w-3.5 h-3.5" />
                  {team.status}
                </span>
                <span>•</span>
                <span>Capitán: <strong className="text-white">{team.captainName || (team as any).captain}</strong></span>
              </div>
            </div>
          </div>

          {/* Action Buttons: Contact Captain & Manage Club */}
          <div className="flex items-center gap-2 flex-wrap">
            <Button
              onClick={() => setIsManageModalOpen(true)}
              className="font-extrabold text-xs uppercase tracking-wider bg-purple-600 hover:bg-purple-500 text-white shadow-xl flex items-center gap-1.5"
            >
              <Settings className="w-4 h-4" />
              Gestión de Club (Administrar)
            </Button>

            <Link href="/mensajes">
              <Button
                className="font-extrabold text-xs uppercase tracking-wider bg-gradient-to-r from-cyan-500 to-purple-600 hover:from-cyan-400 hover:to-purple-500 text-white shadow-xl flex items-center gap-2"
              >
                <MessageSquare className="w-4 h-4" />
                Contactar Capitán ({team.captainName || (team as any).captain})
              </Button>
            </Link>
          </div>
        </div>

        {/* 📌 Standardized Sub-Sub-Navbar Level 3 */}
        <SubSubNavbar
          tabs={profileSubSubTabs}
          activeTab={activeTab}
          onSelectTab={setActiveTab}
          brandColor={activeColor}
        />
      </div>

      {/* Tab Content Display Area */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 space-y-6">

        {/* Vacant Positions Recruitment Strip */}
        <div className="p-4 rounded-2xl glass-panel border border-[var(--border-card)] flex flex-col sm:flex-row sm:items-center justify-between gap-3 shadow-lg">
          <div className="flex items-center gap-2">
            <Sparkles className="w-5 h-5 text-amber-400" />
            <div>
              <span className="text-xs font-black uppercase text-[var(--text-heading)] block">
                Vacantes de Reclutamiento Activas
              </span>
              <span className="text-[11px] text-[var(--text-muted)] font-medium">
                La directiva de {team.name} busca incorporar las siguientes posiciones tácticas:
              </span>
            </div>
          </div>

          <div className="flex items-center gap-1.5 flex-wrap">
            {vacantPositions.map((pos) => (
              <span key={pos} className="px-2.5 py-1 rounded-lg bg-amber-950/80 border border-amber-500/40 text-amber-300 font-mono font-bold text-xs">
                + {pos}
              </span>
            ))}
          </div>
        </div>

        {activeTab === 'plantilla' && (
          <div className="space-y-6">
            {isLoading ? (
              <div className="p-12 text-center text-[var(--text-muted)]">Cargando plantilla...</div>
            ) : Object.keys(squadByOrg).length === 0 ? (
              <div className="p-12 text-center text-[var(--text-muted)] glass-panel rounded-2xl border border-[var(--border-card)]">No hay jugadores registrados.</div>
            ) : (
              Object.entries(squadByOrg).map(([orgName, players]: any) => (
                <div key={orgName} className="p-4 sm:p-6 rounded-2xl glass-panel border border-[var(--border-card)] space-y-4">
                  <h3 className="font-extrabold text-base text-[var(--text-heading)] uppercase border-b border-[var(--border-card)] pb-2 mb-4">
                    Organización: {orgName}
                  </h3>

                  <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                    {players.map((p: any) => (
                      <div key={p.id} className="p-3.5 rounded-xl bg-[var(--bg-card-hover)] border border-[var(--border-card)] flex items-center justify-between gap-3 text-xs">
                        <div className="flex items-center gap-3">
                          <Avatar src={p.avatar_url || p.foto} fallback={p.user_name} size="md" status="online" />
                          <div>
                            <span className="font-bold text-sm text-[var(--text-heading)] block">{p.user_name}</span>
                            <span className="text-[var(--text-muted)] text-[11px] font-mono">{p.gamertag}</span>
                          </div>
                        </div>
                        <Badge variant="cyan">{p.tactical_position || 'DFC'}</Badge>
                      </div>
                    ))}
                  </div>
                </div>
              ))
            )}
          </div>
        )}

        {activeTab === 'posiciones' && game && (
          <div className="rounded-2xl glass-panel border border-[var(--border-card)] overflow-hidden">
            <ClassificationView game={game} hideHeader={true} hideCompFilter={false} hideOrgFilter={true} targetTeamName={team.name} />
          </div>
        )}

        {activeTab === 'calendario' && game && (
          <div className="rounded-2xl glass-panel border border-[var(--border-card)] p-4 sm:p-6">
             <FixtureScheduleView game={game} hideHeader={true} hideOrgFilter={true} targetTeamName={team.name} />
          </div>
        )}

        {activeTab === 'traspasos' && (
          <div className="rounded-2xl glass-panel border border-[var(--border-card)] p-4 sm:p-6 space-y-4">
             <h3 className="font-extrabold text-base text-[var(--text-heading)] uppercase mb-4">Historial de Fichajes y Bajas</h3>
             {isLoading ? (
                <div className="p-12 text-center text-[var(--text-muted)]">Cargando historial...</div>
             ) : contracts.length === 0 ? (
                <div className="p-12 text-center text-[var(--text-muted)]">No hay registros de transferencias.</div>
             ) : (
                <div className="overflow-x-auto">
                  <table className="w-full text-sm text-left">
                    <thead className="text-xs text-[var(--text-muted)] uppercase bg-black/50 border-b border-[var(--border-card)]">
                      <tr>
                        <th className="px-4 py-3">Jugador</th>
                        <th className="px-4 py-3">Organización</th>
                        <th className="px-4 py-3">Fecha</th>
                        <th className="px-4 py-3">Estado</th>
                      </tr>
                    </thead>
                    <tbody>
                      {contracts.map(c => {
                        const orgMatch = c.pitch_message?.match(/\[Organización:\s*([^\]]+)\]/i);
                        const orgName = orgMatch ? orgMatch[1] : 'General';
                        return (
                          <tr key={c.id} className="border-b border-[var(--border-card)] hover:bg-white/5">
                            <td className="px-4 py-3 font-medium flex items-center gap-2">
                              <Avatar src={c.avatar_url} fallback={c.player_name} className="w-6 h-6" /> {c.player_name}
                            </td>
                            <td className="px-4 py-3 text-[var(--text-muted)] uppercase text-xs font-bold">{orgName}</td>
                            <td className="px-4 py-3 text-[var(--text-muted)]">
                              {new Date(c.created_at).toLocaleString()}
                            </td>
                            <td className="px-4 py-3">
                              <Badge variant={
                                c.status === 'ACEPTADO' ? 'emerald' : 
                                c.status === 'RECHAZADO' ? 'rose' : 
                                c.status === 'CONCLUIDO' ? 'slate' : 'cyan'
                              }>
                                {c.status}
                              </Badge>
                            </td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                </div>
             )}
          </div>
        )}

        {(activeTab === 'estadisticas' || activeTab === 'historico') && (
          <div className="p-6 rounded-2xl glass-panel border border-[var(--border-card)] text-center py-12 space-y-2">
            <h4 className="font-black text-lg text-[var(--text-heading)] uppercase">Sección: {activeTab}</h4>
            <p className="text-xs text-[var(--text-muted)]">Información oficial actualizada para la escuadra {team.name} estará disponible próximamente.</p>
          </div>
        )}
      </div>

      {/* Club Management Modal */}
      <ClubManagementModal
        team={team}
        isOpen={isManageModalOpen}
        onClose={() => setIsManageModalOpen(false)}
      />
    </div>
  );
}

'use client';

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import Image from 'next/image';
import { Search, Building2, Trophy, RefreshCw, BarChart2 } from 'lucide-react';
import { GameConfig } from '@/lib/games-data';
import { PageHeader } from '@/components/ui/page-header';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Avatar } from '@/components/ui/avatar';
import { TacticalLoadingSkeleton } from './tactical-loading-skeleton';
import { PlayoffBracket } from './playoff-bracket';
import { getOrganizationsWithStatsAction } from '@/app/actions/organizations';
import { shouldBypassImageOptimization } from '@/lib/image-utils';

interface ClassificationViewProps {
  game: GameConfig;
  initialOrgName?: string;
  initialTournName?: string;
  initialTournId?: string;
  hideOrgFilter?: boolean;
  hideCompFilter?: boolean;
  hideSearchFilter?: boolean;
  hideHeader?: boolean;
  targetTeamName?: string;
}

interface OrgItem {
  id: string | number;
  name: string;
  tag?: string;
  gameSlugs?: string[];
  logoUrl?: string;
}

interface TournItem {
  id: string | number;
  name: string;
  gameSlug?: string;
  organizationName?: string;
  formatType?: string;
  logoUrl?: string;
}

interface TeamStanding {
  name: string;
  tag: string;
  pj: number; // Partidos Jugados
  g: number;  // Ganados
  e: number;  // Empatados
  p: number;  // Perdidos
  gf: number; // Goles a Favor
  gc: number; // Goles en Contra
  dif: number; // Diferencia (GF - GC)
  pts: number; // Puntos
  circuitName: string;
  competitionName: string;
  groupName: string;
}

export function ClassificationView({
  game,
  initialOrgName,
  initialTournName,
  initialTournId,
  hideOrgFilter = false,
  hideCompFilter = false,
  hideSearchFilter = false,
  hideHeader = false,
  targetTeamName,
}: ClassificationViewProps) {
  const brandColor = game.brandColor;

  // States
  const [organizations, setOrganizations] = useState<OrgItem[]>([]);
  const [tournaments, setTournaments] = useState<TournItem[]>([]);

  const [selectedOrgName, setSelectedOrgName] = useState(initialOrgName || 'TODAS');
  const [selectedTournName, setSelectedTournName] = useState(initialTournName || 'TODAS');
  const [searchQuery, setSearchQuery] = useState('');

  const [standings, setStandings] = useState<TeamStanding[]>([]);
  const [allMatches, setAllMatches] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const [activeTabs, setActiveTabs] = useState<Record<string, 'LIGA' | 'PLAYOFF'>>({});

  // 1. Fetch Organizations
  const fetchOrganizationsFromDB = async () => {
    try {
      const res = await getOrganizationsWithStatsAction(game.slug);
      if (res.success && res.organizations) {
        const mapped = res.organizations.map((o: any) => ({
          id: o.id || o.name,
          name: o.name,
          tag: o.tag,
          logoUrl: o.logo_url || o.logoUrl || '/images/default/logo-default.png',
        }));
        setOrganizations(mapped);
      }
    } catch (err) {
      console.error('Error fetching orgs:', err);
    }
  };

  // 2. Fetch Tournaments
  const fetchTournamentsFromDB = async (orgName: string) => {
    try {
      let url = `/api/tournaments?gameSlug=${game.slug}&_t=${Date.now()}`;
      if (orgName !== 'TODAS') url += `&organizationName=${encodeURIComponent(orgName)}`;
      const res = await fetch(url);
      const data = await res.json();
      if (data.success && Array.isArray(data.tournaments)) {
        const mapped = data.tournaments.map((t: any) => {
          // The API swaps them: c.format is returned as format_type, and c.mode_format is returned as format
          let rawFormat = (t.format_type || t.format || 'LIGA').toUpperCase();
          rawFormat = rawFormat.normalize("NFD").replace(/[\u0300-\u036f]/g, ""); // HÍBRIDO -> HIBRIDO

          let parsedFormat = 'LIGA';
          if (rawFormat.includes('PLAYOFF') || rawFormat.includes('ELIMINATORIA')) parsedFormat = 'PLAYOFF';
          else if (rawFormat.includes('HIBRID')) parsedFormat = 'HIBRIDO';

          return {
            id: t.id,
            name: t.name,
            organizationName: t.organization_name,
            formatType: parsedFormat,
            logoUrl: t.logo_url || t.logoUrl || t.banner_url || t.bannerUrl || '/images/default/logo-default.png',
          };
        });

        let filteredMapped = mapped;
        // If targetTeamName is provided, only keep tournaments where this team has matches
        if (targetTeamName) {
           try {
             const mRes = await fetch(`/api/matches?gameSlug=${game.slug}&search=${encodeURIComponent(targetTeamName)}`);
             const mData = await mRes.json();
             if (mData.success && Array.isArray(mData.matches)) {
                const teamTournaments = new Set(mData.matches.map((m: any) => m.tournament_name));
                filteredMapped = mapped.filter((t: any) => teamTournaments.has(t.name));
             }
           } catch {}
        }
        setTournaments(filteredMapped);
      } else {
        setTournaments([]);
      }
    } catch (err) {
      console.error('Error fetching tournaments:', err);
    }
  };

  // 3. Fetch Matches & Calculate Standings
  const fetchAndCalculateStandings = useCallback(async (orgName: string, tournName: string, queryText: string) => {
    try {
      // Pedir TODOS los partidos (no solo FINALIZADOS) para poder poblar la tabla con 0 puntos si no han jugado.
      let url = `/api/matches?gameSlug=${game.slug}&_t=${Date.now()}`;
      if (orgName !== 'TODAS') url += `&organizationName=${encodeURIComponent(orgName)}`;
      if (initialTournId) url += `&tournamentId=${encodeURIComponent(initialTournId)}`;
      else if (tournName !== 'TODAS') url += `&tournamentName=${encodeURIComponent(tournName)}`;
      if (queryText) url += `&search=${encodeURIComponent(queryText)}`;

      const res = await fetch(url);
      const data = await res.json();

      if (data.success && Array.isArray(data.matches)) {
        setAllMatches(data.matches);
        const standingsMap = new Map<string, TeamStanding>();

        data.matches.forEach((m: any) => {
          const homeName = m.home_team_name || 'Equipo Local';
          const homeTag = m.home_team_tag || 'LOC';
          const awayName = m.away_team_name || 'Equipo Visitante';
          const awayTag = m.away_team_tag || 'VIS';

          const scoreHome = m.score_home !== null && m.score_home !== undefined ? Number(m.score_home) : null;
          const scoreAway = m.score_away !== null && m.score_away !== undefined ? Number(m.score_away) : null;

          const compName = m.tournament_name || 'Competencia BD';
          const circName = m.organization_name || 'Organización Oficial BD';
          const groupName = m.group_name || 'GENERAL';

          // Skip playoff rounds from the standings table
          const rNameLower = (m.round_name || '').toLowerCase();
          const isPlayoffRound = ['octavos', 'cuartos', 'semifinal', 'tercer', 'final', 'dieciseisavos'].some(key => rNameLower.includes(key));
          if (isPlayoffRound) return;

          const homeKey = `${circName}_${compName}_${groupName}_${homeName}`;
          const awayKey = `${circName}_${compName}_${groupName}_${awayName}`;

          // Inicializar equipos si no existen (así aparecen con 0pts aunque no hayan jugado)
          if (!standingsMap.has(homeKey)) {
            standingsMap.set(homeKey, { name: homeName, tag: homeTag, pj: 0, g: 0, e: 0, p: 0, gf: 0, gc: 0, dif: 0, pts: 0, circuitName: circName, competitionName: compName, groupName });
          }
          if (!standingsMap.has(awayKey)) {
            standingsMap.set(awayKey, { name: awayName, tag: awayTag, pj: 0, g: 0, e: 0, p: 0, gf: 0, gc: 0, dif: 0, pts: 0, circuitName: circName, competitionName: compName, groupName });
          }

          // Solo sumar puntos y goles si el partido finalizó y tiene resultado válido
          if (m.status !== 'FINALIZADO' || scoreHome === null || scoreAway === null) return;

          const hStats = standingsMap.get(homeKey)!;
          const aStats = standingsMap.get(awayKey)!;

          // Actualizar Local
          hStats.pj += 1;
          hStats.gf += scoreHome;
          hStats.gc += scoreAway;
          hStats.dif = hStats.gf - hStats.gc;

          // Actualizar Visitante
          aStats.pj += 1;
          aStats.gf += scoreAway;
          aStats.gc += scoreHome;
          aStats.dif = aStats.gf - aStats.gc;

          // Puntos y G/E/P
          if (scoreHome > scoreAway) {
            hStats.g += 1;
            hStats.pts += 3;
            aStats.p += 1;
          } else if (scoreHome < scoreAway) {
            aStats.g += 1;
            aStats.pts += 3;
            hStats.p += 1;
          } else {
            hStats.e += 1;
            hStats.pts += 1;
            aStats.e += 1;
            aStats.pts += 1;
          }
        });

        // Convertir Map a Array y Ordenar
        const standingsArray = Array.from(standingsMap.values()).sort((a, b) => {
          if (b.pts !== a.pts) return b.pts - a.pts; // Mayor puntaje
          if (b.dif !== a.dif) return b.dif - a.dif; // Mayor diferencia de gol
          return b.gf - a.gf; // Mayor goles a favor
        });

        setStandings(standingsArray);
      } else {
        setStandings([]);
      }
    } catch (err) {
      console.error('Error fetching standings matches:', err);
      setStandings([]);
    }
  }, [game.slug]);

  // Initial Load
  useEffect(() => {
    let isMounted = true;
    const loadAllInitialData = async () => {
      try {
        const targetOrg = initialOrgName || 'TODAS';
        const targetTourn = initialTournName || 'TODAS';
        await Promise.all([
          fetchOrganizationsFromDB(),
          fetchTournamentsFromDB(targetOrg),
          fetchAndCalculateStandings(targetOrg, targetTourn, ''),
        ]);
      } catch (err) {
        console.error(err);
      } finally {
        if (isMounted) setIsLoading(false);
      }
    };
    loadAllInitialData();
    return () => { isMounted = false; };
  }, [game.slug, fetchAndCalculateStandings, initialOrgName, initialTournName]);

  // Handlers
  const handleSelectOrganization = (orgName: string) => {
    setSelectedOrgName(orgName);
    setSelectedTournName('TODAS');
    fetchTournamentsFromDB(orgName);
    fetchAndCalculateStandings(orgName, 'TODAS', searchQuery);
  };

  const handleSelectTournament = (tournName: string) => {
    setSelectedTournName(tournName);
    fetchAndCalculateStandings(selectedOrgName, tournName, searchQuery);
  };

  // Agrupar Clasificaciones por Organización -> Competencia (Usando tournaments base con fallback a allMatches)
  const groupedTournaments = useMemo(() => {
    const map: Record<string, TournItem[]> = {};

    // Fallback: If API tournaments list is empty, build tournament items from allMatches
    let activeTournaments: TournItem[] = [...tournaments];
    // Fallback: If API tournaments list is empty and we are NOT filtering by a specific team, build tournament items from allMatches
    if (activeTournaments.length === 0 && allMatches.length > 0 && !targetTeamName) {
      const matchTourns = new Map<string, TournItem>();
      allMatches.forEach((m) => {
        const tName = m.tournament_name || 'Competencia BD';
        if (!matchTourns.has(tName)) {
          matchTourns.set(tName, {
            id: m.competition_id || m.tournament_id || tName,
            name: tName,
            gameSlug: game.slug,
            organizationName: m.organization_name || 'Organización Oficial',
            formatType: 'LIGA',
          });
        }
      });
      activeTournaments = Array.from(matchTourns.values());
    }

    let filteredTournaments = activeTournaments;
    if (selectedOrgName !== 'TODAS') {
      filteredTournaments = filteredTournaments.filter(t => (t.organizationName || '').toLowerCase() === selectedOrgName.toLowerCase());
    }
    if (selectedTournName !== 'TODAS') {
      filteredTournaments = filteredTournaments.filter(t => t.name.toLowerCase() === selectedTournName.toLowerCase());
    }

    // Group by organization
    filteredTournaments.forEach((t) => {
      const orgName = t.organizationName || 'Organización Oficial';
      if (!map[orgName]) map[orgName] = [];
      map[orgName].push(t);
    });
    return map;
  }, [tournaments, allMatches, selectedOrgName, selectedTournName, game.slug]);

  // Motor de Estados Vacíos
  const getEmptyStateMessage = () => {
    if (targetTeamName && tournaments.length === 0) {
      return {
        title: 'Sin competencias registradas',
        desc: 'El equipo no se encuentra inscrito en ninguna competencia actualmente.'
      };
    }
    if (searchQuery) {
      return {
        title: `Sin resultados para "${searchQuery}"`,
        desc: 'No existen equipos o competencias que coincidan con la búsqueda ingresada.'
      };
    }
    if (selectedTournName !== 'TODAS') {
      return {
        title: 'Competencia sin resultados oficiales',
        desc: `Actualmente la competencia ${selectedTournName} no tiene partidos finalizados registrados en la plataforma.`
      };
    }
    if (selectedOrgName !== 'TODAS') {
      return {
        title: 'Organización sin tablas de posiciones',
        desc: `No existen competencias con partidos finalizados en la organización ${selectedOrgName}.`
      };
    }
    return {
      title: 'No hay datos de clasificación',
      desc: 'No se encontraron partidos finalizados en la plataforma para generar las tablas de posiciones.'
    };
  };

  const emptyState = getEmptyStateMessage();

  return (
    <div className="w-full max-w-7xl mx-auto space-y-6 sm:space-y-8 pb-16">

      {/* ── 1. ENCABEZADO ──────────────────────────────────────────────────────── */}
      {!hideHeader && (
        <PageHeader
          badgeText={`TEMPORADA OFICIAL / ${game.name.toUpperCase()}`}
          badgeIcon={<BarChart2 className="w-3.5 h-3.5" style={{ color: brandColor, fill: brandColor }} />}
          title="Tabla de Posiciones y Clasificación General"
          highlightTitle="Clasificación"
          description="Sigue de cerca el rendimiento de tu equipo, puntos, diferencia de gol y estadísticas en todas las ligas de TournamentsPro."
          brandColor={brandColor}
        />
      )}

      {isLoading ? (
        <div className="pt-12">
          <TacticalLoadingSkeleton game={game} message={`CALCULANDO CLASIFICACIÓN DE ${game.name.toUpperCase()}...`} />
        </div>
      ) : (
        <>
          {/* ── 2. FILTROS EN TARJETA (GLASS-PANEL) ─────────────────────────────────── */}
          {(!hideSearchFilter || !hideOrgFilter || !hideCompFilter) && (
            <div className="bg-[var(--bg-card)] p-5 sm:p-6 rounded-3xl border border-[var(--border-card)] shadow-xl space-y-5 backdrop-blur-md">

              {/* BUSCADOR */}
              {!hideSearchFilter && (
                <div className="relative w-full">
                  <Search className="w-5 h-5 absolute left-4 top-1/2 -translate-y-1/2 text-[var(--text-muted)]" />
                  <Input
                    placeholder="Buscar por equipo, organización o liga..."
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    onKeyDown={(e) => {
                      if (e.key === 'Enter') {
                        fetchAndCalculateStandings(selectedOrgName, selectedTournName, searchQuery);
                      }
                    }}
                    className="pl-12 py-3.5 text-xs sm:text-sm input-theme rounded-2xl glass-panel shadow-md w-full placeholder:text-[var(--text-muted)]"
                  />
                </div>
              )}

              {/* ORGANIZACIONES */}
              {!hideOrgFilter && (
                <div className="space-y-2 pt-1 font-mono">
                  <div className="flex items-center gap-2 text-[10px] font-bold tracking-widest text-[var(--text-muted)] uppercase">
                    <Building2 className="w-3.5 h-3.5" style={{ color: brandColor }} />
                    <span>ORGANIZACIONES DISPONIBLES EN BD</span>
                  </div>
                  <div className="flex flex-wrap items-center gap-2">
                    <button
                      onClick={() => handleSelectOrganization('TODAS')}
                      className={`px-3.5 py-1.5 rounded-full text-xs font-bold transition-all border flex items-center gap-2 ${
                        selectedOrgName === 'TODAS'
                          ? 'shadow-md font-black'
                          : 'bg-[var(--bg-card)] border-[var(--border-card)] text-[var(--text-muted)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-card-hover)]'
                      }`}
                      style={
                        selectedOrgName === 'TODAS'
                          ? {
                              backgroundColor: `color-mix(in srgb, ${brandColor} 20%, transparent)`,
                              borderColor: brandColor,
                              color: brandColor,
                              boxShadow: `0 0 15px color-mix(in srgb, ${brandColor} 30%, transparent)`,
                            }
                          : undefined
                      }
                    >
                      <Building2 className="w-3.5 h-3.5 shrink-0" />
                      <span>TODAS</span>
                    </button>
                    {organizations.map((org) => {
                      const isActive = selectedOrgName.toUpperCase() === org.name.toUpperCase();
                      return (
                        <button
                          key={org.id}
                          onClick={() => handleSelectOrganization(org.name)}
                          className={`px-3.5 py-1.5 rounded-full text-xs font-bold transition-all border flex items-center gap-2 ${
                            isActive
                              ? 'shadow-md font-black'
                              : 'bg-[var(--bg-card)] border-[var(--border-card)] text-[var(--text-muted)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-card-hover)]'
                          }`}
                          style={
                            isActive
                              ? {
                                  backgroundColor: `color-mix(in srgb, ${brandColor} 20%, transparent)`,
                                  borderColor: brandColor,
                                  color: brandColor,
                                  boxShadow: `0 0 15px color-mix(in srgb, ${brandColor} 30%, transparent)`,
                                }
                              : undefined
                          }
                        >
                          {org.logoUrl ? (
                            <Image
                              src={org.logoUrl}
                              alt={org.name}
                              width={16}
                              height={16}
                              unoptimized={shouldBypassImageOptimization(org.logoUrl)}
                              className="w-4 h-4 object-contain rounded-full filter drop-shadow shrink-0"
                              onError={(e) => {
                                e.currentTarget.style.display = 'none';
                              }}
                            />
                          ) : (
                            <Building2 className="w-3.5 h-3.5 shrink-0" />
                          )}
                          <span>{org.name}</span>
                          {org.tag && <span className="opacity-70 text-[10px]">[{org.tag}]</span>}
                        </button>
                      );
                    })}
                  </div>
                </div>
              )}

              {/* COMPETENCIAS */}
              {!hideCompFilter && (
                <div className="space-y-2 pt-1 font-mono">
                  <div className="flex items-center gap-2 text-[10px] font-bold tracking-widest text-[var(--text-muted)] uppercase">
                    <Trophy className="w-3.5 h-3.5 text-amber-400" />
                    <span>
                      {targetTeamName 
                        ? 'COMPETENCIAS / TORNEOS EN DISPUTA' 
                        : `COMPETENCIAS / TORNEOS DE ${selectedOrgName.toUpperCase()}`}
                    </span>
                  </div>

                  {tournaments.length > 0 && (
                    <div className="flex flex-wrap items-center gap-2">
                      <button
                        onClick={() => handleSelectTournament('TODAS')}
                        className={`px-3.5 py-1.5 rounded-full text-xs font-bold transition-all border flex items-center gap-2 ${
                          selectedTournName === 'TODAS'
                            ? 'shadow-md font-black'
                            : 'bg-[var(--bg-card)] border-[var(--border-card)] text-[var(--text-muted)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-card-hover)]'
                        }`}
                        style={
                          selectedTournName === 'TODAS'
                            ? {
                                backgroundColor: `color-mix(in srgb, ${brandColor} 20%, transparent)`,
                                borderColor: brandColor,
                                color: brandColor,
                                boxShadow: `0 0 15px color-mix(in srgb, ${brandColor} 30%, transparent)`,
                              }
                            : undefined
                        }
                      >
                        <Trophy className="w-3.5 h-3.5 text-amber-400 shrink-0" />
                        <span>TODAS</span>
                      </button>
                    {tournaments.map((comp) => {
                      const isActive = selectedTournName.toUpperCase() === comp.name.toUpperCase();
                      return (
                        <button
                          key={comp.id}
                          onClick={() => handleSelectTournament(comp.name)}
                          className={`px-3.5 py-1.5 rounded-full text-xs font-bold transition-all border flex items-center gap-2 ${
                            isActive
                              ? 'shadow-md font-black'
                              : 'bg-[var(--bg-card)] border-[var(--border-card)] text-[var(--text-muted)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-card-hover)]'
                          }`}
                          style={
                            isActive
                              ? {
                                  backgroundColor: `color-mix(in srgb, ${brandColor} 20%, transparent)`,
                                  borderColor: brandColor,
                                  color: brandColor,
                                  boxShadow: `0 0 15px color-mix(in srgb, ${brandColor} 30%, transparent)`,
                                }
                              : undefined
                          }
                        >
                          {comp.logoUrl ? (
                            <Image
                              src={comp.logoUrl}
                              alt={comp.name}
                              width={16}
                              height={16}
                              unoptimized={shouldBypassImageOptimization(comp.logoUrl)}
                              className="w-4 h-4 object-contain rounded-full filter drop-shadow shrink-0"
                              onError={(e) => {
                                e.currentTarget.style.display = 'none';
                              }}
                            />
                          ) : (
                            <Trophy className="w-3.5 h-3.5 text-amber-400 shrink-0" />
                          )}
                          <span>{comp.name}</span>
                        </button>
                      );
                    })}
                  </div>
                  )}
                </div>
              )}
            </div>
          )}

      {/* ── 3. CONTENIDO PRINCIPAL (Sincronizado) ─────────────────────────────── */}
        <div className="space-y-8 pt-2 animate-fade-up">
          {Object.keys(groupedTournaments).length === 0 ? (

            /* EMPTY STATE */
            <div className="p-12 text-center rounded-3xl glass-panel border border-[var(--border-card)] space-y-4">
              <BarChart2 className="w-12 h-12 mx-auto text-[var(--text-muted)] opacity-60" />
              <h3 className="text-xl font-bold font-display text-[var(--text-heading)]">
                {emptyState.title}
              </h3>
              <p className="text-xs text-[var(--text-muted)] max-w-sm mx-auto">
                {emptyState.desc}
              </p>
              <Button
                variant="outline"
                size="sm"
                onClick={() => {
                  setSearchQuery('');
                  handleSelectOrganization('TODAS');
                }}
                className="text-xs gap-1.5 mt-2"
              >
                <RefreshCw className="w-3.5 h-3.5" />
                Restablecer Filtros
              </Button>
            </div>
          ) : (

            /* STANDINGS POR ORGANIZACIÓN -> COMPETENCIA */
            Object.entries(groupedTournaments).map(([circuitName, comps]) => (
              <div key={circuitName} className="space-y-6">

                {/* Header de la Organización */}
                <div className="flex items-center justify-between border-b border-[var(--border-card)] pb-3">
                  <div className="flex items-center gap-3">
                    <Building2 className="w-6 h-6" style={{ color: brandColor }} />
                    <h2 className="text-xl sm:text-2xl font-extrabold font-display text-[var(--text-heading)] tracking-wider uppercase">
                      {circuitName}
                    </h2>
                  </div>
                </div>

                {/* Sub-grupos por Competencia */}
                {comps.map((compInfo) => {
                  const compName = compInfo.name;
                  const formatType = compInfo.formatType || 'LIGA';

                  // Filter matches for this tournament
                  const compMatches = allMatches.filter(m => 
                    (m.tournament_name || '').toLowerCase() === compName.toLowerCase() ||
                    m.competition_id === compInfo.id || 
                    m.tournament_id === compInfo.id
                  );

                  // Filter standings for this tournament
                  const teamList = standings.filter(t => 
                    t.competitionName.toLowerCase() === compName.toLowerCase()
                  );

                  return (
                    <div key={compName} className="space-y-3">

                    {/* Header de Competencia */}
                    <div className="flex items-center justify-between px-4 py-2.5 bg-[var(--bg-card)] border border-[var(--border-card)] rounded-xl shadow-sm mb-2">
                      <div className="flex items-center gap-3">
                        <div className="p-1.5 rounded-lg bg-amber-500/10 border border-amber-500/30 text-amber-400">
                          <Trophy className="w-4 h-4" />
                        </div>
                        <span className="font-black uppercase text-[var(--text-heading)] tracking-wider text-sm">
                          {compName}
                        </span>
                      </div>
                      <Badge variant="cyan" className="text-[10px] px-2.5 py-0.5 opacity-80">
                        {teamList.length} EQUIPOS
                      </Badge>
                    </div>

                    {/* TABS PARA HIBRIDO */}
                    {formatType === 'HIBRIDO' && (
                      <div className="flex items-center gap-2 mb-4 bg-[var(--bg-card)] border border-[var(--border-card)] p-1 rounded-xl w-fit">
                        <button
                          onClick={() => setActiveTabs(prev => ({ ...prev, [compName]: 'LIGA' }))}
                          className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-colors ${activeTabs[compName] !== 'PLAYOFF' ? 'bg-[var(--accent-cyan-bg)] text-[var(--accent-cyan)] shadow-sm' : 'text-[var(--text-muted)] hover:text-[var(--text-primary)]'}`}
                        >
                          Fase de Grupos
                        </button>
                        <button
                          onClick={() => setActiveTabs(prev => ({ ...prev, [compName]: 'PLAYOFF' }))}
                          className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-colors ${activeTabs[compName] === 'PLAYOFF' ? 'bg-[var(--accent-cyan-bg)] text-[var(--accent-cyan)] shadow-sm' : 'text-[var(--text-muted)] hover:text-[var(--text-primary)]'}`}
                        >
                          Fase Final
                        </button>
                      </div>
                    )}

                    {/* RENDERIZADO CONDICIONAL */}
                    {formatType === 'PLAYOFF' || (formatType === 'HIBRIDO' && activeTabs[compName] === 'PLAYOFF') ? (
                      <div className="bg-[var(--bg-card)] border border-[var(--border-card)] rounded-2xl p-4 shadow-xl">
                        <PlayoffBracket matches={compMatches} brandColor={brandColor} />
                      </div>
                    ) : (
                      <div className="space-y-6">
                        {(() => {
                          const groupsObj: Record<string, typeof teamList> = {};
                          teamList.forEach(t => {
                            if (!groupsObj[t.groupName]) groupsObj[t.groupName] = [];
                            groupsObj[t.groupName].push(t);
                          });

                          // Sort groups alphabetically (Grupo A, Grupo B, etc.)
                          const sortedGroups = Object.entries(groupsObj).sort((a, b) => a[0].localeCompare(b[0]));

                          return sortedGroups.map(([gName, gTeams]) => (
                            <div key={gName} className="w-full overflow-x-auto rounded-2xl border border-[var(--border-card)] glass-panel shadow-xl">
                              {sortedGroups.length > 1 && (
                                <div className="px-4 py-3 bg-[var(--bg-card)] border-b border-[var(--border-card)] text-sm font-black uppercase text-[var(--accent-cyan)] tracking-wider">
                                  {gName}
                                </div>
                              )}
                              <table className="w-full text-left border-collapse min-w-[720px]">
                                <thead>
                                  <tr className="bg-[var(--bg-card)] border-b border-[var(--border-card)] text-[10px] font-black uppercase text-[var(--text-muted)] tracking-wider">
                                    <th className="p-3.5 w-16 text-center">Pos</th>
                                    <th className="p-3.5 text-left text-[var(--accent-cyan)]">Club / Equipo</th>
                                    <th className="p-3.5 w-12 text-center" title="Partidos Jugados">PJ</th>
                                    <th className="p-3.5 w-12 text-center text-emerald-400" title="Ganados">G</th>
                                    <th className="p-3.5 w-12 text-center text-amber-400" title="Empatados">E</th>
                                    <th className="p-3.5 w-12 text-center text-rose-400" title="Perdidos">P</th>
                                    <th className="p-3.5 w-12 text-center" title="Goles a Favor">GF</th>
                                    <th className="p-3.5 w-12 text-center" title="Goles en Contra">GC</th>
                                    <th className="p-3.5 w-12 text-center" title="Diferencia de Goles">DIF</th>
                                    <th className="p-3.5 w-16 text-center text-[var(--accent-cyan)] text-xs">PTS</th>
                                  </tr>
                                </thead>
                                <tbody className="divide-y divide-[var(--border-card)] text-xs">
                                  {gTeams.map((team, index) => {
                                    const position = index + 1;
                                    let posStyles = 'text-[var(--text-secondary)] font-bold';
                                    if (position === 1) posStyles = 'text-amber-400 bg-amber-500/10 border border-amber-500/30 rounded px-1.5 py-0.5 shadow-sm';
                                    else if (position === 2) posStyles = 'text-[var(--text-primary)] bg-[var(--bg-main)] border border-[var(--border-card)] rounded px-1.5 py-0.5';
                                    else if (position === 3) posStyles = 'text-orange-500 bg-orange-500/10 border border-orange-500/30 rounded px-1.5 py-0.5';

                                    const isBottom = position > gTeams.length - 3 && gTeams.length > 5;

                                    return (
                                      <tr key={team.name} className={`hover:bg-[var(--bg-card-hover)] transition-colors group ${isBottom ? 'opacity-80' : ''}`}>
                                        <td className="p-3.5 text-center">
                                          <span className={posStyles}>{position}</span>
                                        </td>
                                        <td className="p-3.5">
                                          <div className="flex items-center gap-3">
                                            <Avatar fallback={team.tag} size="sm" className="ring-1 ring-[var(--border-card)] shrink-0" />
                                            <span className={`font-extrabold font-display text-sm truncate max-w-[200px] transition-colors ${position <= 3 ? 'text-[var(--text-primary)] group-hover:text-amber-400' : 'text-[var(--text-heading)]'}`} style={{ ':hover': { color: brandColor } } as any}>
                                              {team.name}
                                            </span>
                                          </div>
                                        </td>
                                        <td className="p-3.5 text-center font-bold text-[var(--text-secondary)]">{team.pj}</td>
                                        <td className="p-3.5 text-center font-black text-emerald-400/80">{team.g}</td>
                                        <td className="p-3.5 text-center font-bold text-amber-400/80">{team.e}</td>
                                        <td className="p-3.5 text-center font-bold text-rose-400/80">{team.p}</td>
                                        <td className="p-3.5 text-center font-semibold text-[var(--text-muted)]">{team.gf}</td>
                                        <td className="p-3.5 text-center font-semibold text-[var(--text-muted)]">{team.gc}</td>
                                        <td className="p-3.5 text-center font-black">
                                          <span className={team.dif > 0 ? 'text-emerald-400' : team.dif < 0 ? 'text-rose-400' : 'text-[var(--text-muted)]'}>
                                            {team.dif > 0 ? `+${team.dif}` : team.dif}
                                          </span>
                                        </td>
                                        <td className="p-3.5 text-center">
                                          <span className="px-2 py-1 bg-[var(--bg-main)] border border-[var(--border-card)] rounded font-black text-sm shadow-sm transition-colors" style={{ color: brandColor }}>
                                            {team.pts}
                                          </span>
                                        </td>
                                      </tr>
                                    );
                                  })}
                                </tbody>
                              </table>
                            </div>
                          ));
                        })()}
                      </div>
                    )}
                  </div>
                );
              })}
              </div>
            ))
          )}
        </div>
        </>
      )}
    </div>
  );
}

