'use client';

import React, { useState, useEffect } from 'react';
import { Button } from '@/components/ui/button';
import { getAthleteTransferHistoryAction, approveExtraordinaryTransferAction, rejectExtraordinaryTransferAction } from '@/app/actions/transfers';
import {
  Shield,
  User,
  History,
  AlertTriangle,
  CheckCircle2,
  XCircle,
  ArrowRight,
  Clock,
  Award,
  Flame,
  FileText,
  X,
} from 'lucide-react';

export interface OrganizerTransferReviewModalProps {
  isOpen: boolean;
  onClose: () => void;
  application: {
    id: string;
    teamId: string;
    teamName: string;
    applicantUserId: string;
    applicantName: string;
    applicantGamertag?: string;
    position: string;
    pitchMessage?: string;
    gameSlug: string;
    isExtraordinary: boolean;
    createdAt: string;
  };
  organizerUserId: string;
  organizationId?: string;
  brandColor?: string;
  onSuccess?: () => void;
}

export function OrganizerTransferReviewModal({
  isOpen,
  onClose,
  application,
  organizerUserId,
  organizationId,
  brandColor = 'var(--game-brand)',
  onSuccess,
}: OrganizerTransferReviewModalProps) {
  const [historyLoading, setHistoryLoading] = useState(true);
  const [historyData, setHistoryData] = useState<{
    totalMovements: number;
    recentTransfers: Array<{
      id: string;
      gameSlug: string;
      fromTeamName: string | null;
      toTeamName: string;
      signedAt: string;
      transferType: string;
    }>;
  } | null>(null);

  const [submitting, setSubmitting] = useState(false);
  const [rejectionReason, setRejectionReason] = useState('');
  const [showRejectForm, setShowRejectForm] = useState(false);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  useEffect(() => {
    if (isOpen && application.applicantUserId) {
      setHistoryLoading(true);
      getAthleteTransferHistoryAction(application.applicantUserId, organizationId)
        .then((res) => {
          if (res.success && res.data) {
            setHistoryData(res.data);
          }
        })
        .finally(() => setHistoryLoading(false));
    }
  }, [isOpen, application.applicantUserId, organizationId]);

  if (!isOpen) return null;

  const handleApprove = async () => {
    setSubmitting(true);
    setErrorMsg(null);
    try {
      const res = await approveExtraordinaryTransferAction(application.id, organizerUserId);
      if (res.success) {
        if (onSuccess) onSuccess();
        onClose();
      } else {
        setErrorMsg(res.error || 'Error al aprobar el traspaso.');
      }
    } catch (err: any) {
      setErrorMsg(err.message || 'Error de conexión.');
    } finally {
      setSubmitting(false);
    }
  };

  const handleReject = async () => {
    setSubmitting(true);
    setErrorMsg(null);
    try {
      const res = await rejectExtraordinaryTransferAction(application.id, organizerUserId, rejectionReason);
      if (res.success) {
        if (onSuccess) onSuccess();
        onClose();
      } else {
        setErrorMsg(res.error || 'Error al rechazar el traspaso.');
      }
    } catch (err: any) {
      setErrorMsg(err.message || 'Error de conexión.');
    } finally {
      setSubmitting(false);
    }
  };

  const totalMoves = historyData?.totalMovements || 0;
  const isHighMobility = totalMoves >= 3;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-md animate-fade-in">
      <div
        className="w-full max-w-2xl bg-[var(--bg-card)] border border-[var(--border-card)] rounded-3xl overflow-hidden shadow-2xl space-y-0 text-[var(--text-primary)] relative backdrop-blur-xl max-h-[90vh] flex flex-col"
        style={{ '--modal-brand': brandColor } as React.CSSProperties}
      >
        {/* Header Bar */}
        <div className="px-6 py-4 border-b border-[var(--border-card)] bg-[var(--bg-main)]/80 flex items-center justify-between shrink-0">
          <div className="flex items-center gap-2.5">
            <div className="w-9 h-9 rounded-xl bg-amber-500/10 border border-amber-500/30 flex items-center justify-center text-amber-400">
              <Shield className="w-5 h-5" />
            </div>
            <div>
              <h3 className="font-bold font-display text-base text-[var(--text-heading)] uppercase tracking-tight">
                Evaluación de Traspaso Extraordinario
              </h3>
              <span className="text-[10px] font-mono text-[var(--text-muted)]">
                Panel de Auditoría y Control del Organizador
              </span>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-2 rounded-xl text-[var(--text-muted)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-card-hover)] transition-all"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Scrollable Body */}
        <div className="p-6 overflow-y-auto space-y-6 flex-1">
          {errorMsg && (
            <div className="p-3.5 rounded-2xl bg-rose-950/60 border border-rose-500/40 text-rose-300 text-xs font-mono flex items-center gap-2">
              <AlertTriangle className="w-4 h-4 text-rose-400 shrink-0" />
              <span>{errorMsg}</span>
            </div>
          )}

          {/* 1. Applicant & Transfer Summary */}
          <div className="p-4 rounded-2xl bg-[var(--bg-main)]/60 border border-[var(--border-card)] space-y-3">
            <div className="flex items-center justify-between border-b border-[var(--border-card)] pb-3">
              <div className="flex items-center gap-3">
                <div className="w-12 h-12 rounded-xl bg-[var(--bg-card)] border border-[var(--border-card)] flex items-center justify-center text-[var(--text-heading)] font-black text-lg shadow-md">
                  <User className="w-6 h-6 text-cyan-400" />
                </div>
                <div>
                  <h4 className="font-extrabold text-base text-[var(--text-heading)]">
                    {application.applicantName}
                  </h4>
                  <span className="text-xs font-mono text-cyan-400 font-bold block">
                    @{application.applicantGamertag || 'Atleta'} | Posición: {application.position}
                  </span>
                </div>
              </div>

              <div className="text-right">
                <span className="text-[9px] font-mono font-bold uppercase tracking-wider text-amber-400 bg-amber-950/60 border border-amber-500/40 px-3 py-1 rounded-full inline-block">
                  ⚠️ Fuera de Plazo / En Curso
                </span>
              </div>
            </div>

            {/* Target Team Banner */}
            <div className="flex items-center justify-between text-xs font-mono pt-1">
              <span className="text-[var(--text-muted)] uppercase font-bold">Solicitud de Ingreso a:</span>
              <strong className="text-[var(--accent-emerald)] font-mono text-sm uppercase flex items-center gap-1.5">
                <Shield className="w-4 h-4 text-emerald-400" />
                {application.teamName}
              </strong>
            </div>

            {application.pitchMessage && (
              <div className="p-3 rounded-xl bg-[var(--bg-card)] border border-[var(--border-card)] text-xs text-[var(--text-secondary)] italic">
                &quot;{application.pitchMessage}&quot;
              </div>
            )}
          </div>

          {/* 2. ANTIFRAUD & MOBILITY AUDIT SECTION */}
          <div className="space-y-3">
            <div className="flex items-center justify-between">
              <h4 className="text-xs font-mono font-black uppercase text-[var(--text-muted)] tracking-wider flex items-center gap-2">
                <History className="w-4 h-4 text-purple-400" />
                Auditoría de Movimientos e Histórico de Clubes
              </h4>

              {/* Total Movements Counter Badge */}
              <div
                className={`px-3 py-1 rounded-xl text-xs font-mono font-black border flex items-center gap-1.5 ${
                  isHighMobility
                    ? 'bg-rose-950/60 border-rose-500/50 text-rose-300 shadow-[0_0_12px_rgba(244,63,94,0.2)]'
                    : 'bg-emerald-950/60 border-emerald-500/50 text-emerald-300'
                }`}
              >
                {isHighMobility && <AlertTriangle className="w-3.5 h-3.5 text-rose-400 animate-pulse" />}
                <span>{totalMoves} MOVIMIENTOS DE CLUB</span>
              </div>
            </div>

            {isHighMobility && (
              <div className="p-3 rounded-xl bg-amber-950/40 border border-amber-500/30 text-amber-300 text-[11px] font-mono flex items-start gap-2">
                <AlertTriangle className="w-4 h-4 text-amber-400 shrink-0 mt-0.5" />
                <span>
                  <strong>Advertencia Antifraude:</strong> Este atleta posee {totalMoves} cambios de equipo registrados en la organización. Verifica que no viole la normativa de máximo de traspasos por temporada.
                </span>
              </div>
            )}

            {/* Timeline List of Last Teams Played For */}
            {historyLoading ? (
              <div className="p-6 text-center text-xs font-mono text-[var(--text-muted)] animate-pulse">
                Consultando historial de fichajes en BD...
              </div>
            ) : historyData?.recentTransfers && historyData.recentTransfers.length > 0 ? (
              <div className="space-y-2 max-h-44 overflow-y-auto pr-1">
                {historyData.recentTransfers.map((t, idx) => (
                  <div
                    key={t.id || idx}
                    className="p-2.5 rounded-xl bg-[var(--bg-main)]/70 border border-[var(--border-card)] flex items-center justify-between text-xs font-mono"
                  >
                    <div className="flex items-center gap-2 truncate">
                      <span className="text-[var(--text-muted)] text-[10px]">
                        {new Date(t.signedAt).toLocaleDateString()}
                      </span>
                      <span className="text-[var(--text-muted)]">{t.fromTeamName || 'Agente Libre'}</span>
                      <ArrowRight className="w-3 h-3 text-[var(--text-muted)] shrink-0" />
                      <strong className="text-[var(--text-heading)] truncate">{t.toTeamName}</strong>
                    </div>
                    <span className="text-[9px] uppercase px-2 py-0.5 rounded-md bg-[var(--bg-card)] border border-[var(--border-card)] text-cyan-400 shrink-0">
                      {t.transferType}
                    </span>
                  </div>
                ))}
              </div>
            ) : (
              <div className="p-4 text-center rounded-xl bg-[var(--bg-main)]/40 border border-[var(--border-card)] text-xs font-mono text-[var(--text-muted)]">
                Sin traspasos previos registrados en esta organización (Atleta Limpio).
              </div>
            )}
          </div>

          {/* Rejection Form Field */}
          {showRejectForm && (
            <div className="space-y-2 p-3.5 rounded-2xl bg-rose-950/30 border border-rose-500/30 animate-fade-in">
              <label className="text-xs font-mono font-bold text-rose-300 block">
                Motivo del Rechazo (Visible para el Atleta y Capitán):
              </label>
              <textarea
                value={rejectionReason}
                onChange={(e) => setRejectionReason(e.target.value)}
                placeholder="Ejemplo: Exceso de cambios de club en la misma temporada o violacion del reglamento..."
                className="w-full h-20 p-2.5 rounded-xl bg-[var(--bg-main)] border border-[var(--border-card)] text-xs font-mono text-[var(--text-primary)] focus:outline-none focus:border-rose-500"
              />
            </div>
          )}
        </div>

        {/* Footer Action Buttons */}
        <div className="px-6 py-4 border-t border-[var(--border-card)] bg-[var(--bg-main)]/80 flex items-center justify-end gap-3 shrink-0">
          {!showRejectForm ? (
            <>
              <Button
                variant="outline"
                onClick={() => setShowRejectForm(true)}
                className="text-xs font-mono border-rose-500/40 text-rose-400 hover:bg-rose-950/40"
              >
                <XCircle className="w-4 h-4 mr-1.5" />
                Rechazar Traspaso
              </Button>
              <Button
                onClick={handleApprove}
                disabled={submitting}
                className="text-xs font-mono font-bold bg-emerald-600 hover:bg-emerald-500 text-white shadow-[0_0_15px_rgba(16,185,129,0.3)]"
              >
                <CheckCircle2 className="w-4 h-4 mr-1.5" />
                {submitting ? 'Procesando...' : 'Aprobar y Registrar Fichaje'}
              </Button>
            </>
          ) : (
            <>
              <Button
                variant="ghost"
                onClick={() => setShowRejectForm(false)}
                className="text-xs font-mono"
              >
                Cancelar
              </Button>
              <Button
                onClick={handleReject}
                disabled={submitting || !rejectionReason.trim()}
                className="text-xs font-mono font-bold bg-rose-600 hover:bg-rose-500 text-white shadow-[0_0_15px_rgba(244,63,94,0.3)]"
              >
                {submitting ? 'Guardando...' : 'Confirmar Rechazo'}
              </Button>
            </>
          )}
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect, useCallback } from 'react';
import Link from 'next/link';
import { TransferListing } from '@/lib/data-store';
import { GAMES_CATALOG, GameConfig } from '@/lib/games-data';
import { Button } from '@/components/ui/button';
import { FilterBar } from '@/components/ui/filter-bar';
import { PageHeader } from '@/components/ui/page-header';
import { EsportsCard } from '@/components/ui/esports-card';
import {
  createTransferPostAction,
  getTransferPostsAction,
  getCompletedTransfersAction,
  getGameConfigurationAction,
} from '@/app/actions/transfers';
import {
  ArrowRightLeft,
  UserCheck,
  Shield,
  Plus,
  Clock,
  AlertCircle,
  Lock,
  LogIn,
  UserPlus,
  Calendar,
  Trophy,
  X,
  Database,
} from 'lucide-react';

import { TacticalLoadingSkeleton } from '@/components/tournaments/tactical-loading-skeleton';
import { useAuth } from '@/components/providers/auth-provider';

interface TransferMarketProps {
  game?: GameConfig;
}

export function TransferMarket({ game }: TransferMarketProps) {
  const { activeGameSlug, currentUser } = useAuth();
  const currentGameSlug = game?.slug || activeGameSlug || 'eafc26';
  const currentGameObj = GAMES_CATALOG[currentGameSlug] || GAMES_CATALOG['eafc26'];

  // Dynamic Game Configuration Loaded directly from MySQL Database
  const [dbGameConfig, setDbGameConfig] = useState<{
    maxSquadCap: number;
    maxTransfersPerWindow: number;
    postExpirationDays: number;
    positions: string[];
  }>({
    maxSquadCap: currentGameSlug === 'eafc26' ? 20 : 7,
    maxTransfersPerWindow: 3,
    postExpirationDays: 7,
    positions: currentGameObj?.positions || ['MCO', 'DFC', 'LD', 'LI', 'MCD', 'MC', 'DC'],
  });

  useEffect(() => {
    getGameConfigurationAction(currentGameSlug).then((res) => {
      if (res.success && res.data) {
        setDbGameConfig({
          maxSquadCap: res.data.maxSquadCap,
          maxTransfersPerWindow: res.data.maxTransfersPerWindow,
          postExpirationDays: res.data.postExpirationDays,
          positions: res.data.positions,
        });
      }
    });
  }, [currentGameSlug]);

  const [activeTab, setActiveTab] = useState<'ALL' | 'JUGADOR_BUSCA_CLUB' | 'CLUB_RECLUTA_JUGADOR' | 'REALIZADOS'>('ALL');
  const [timeFilter, setTimeFilter] = useState<'ALL' | 'TODAY' | '3_DAYS' | '7_DAYS' | 'OLDEST'>('ALL');
  const [searchTerm, setSearchTerm] = useState('');
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [isLoadingDB, setIsLoadingDB] = useState(true);

  // Form State for creating a new Transfer Listing
  const [listingType, setListingType] = useState<'JUGADOR_BUSCA_CLUB' | 'CLUB_RECLUTA_JUGADOR'>('JUGADOR_BUSCA_CLUB');
  const [positionInput, setPositionInput] = useState('');
  const [messageInput, setMessageInput] = useState('');
  const [platformInput, setPlatformInput] = useState('CROSSPLAY');
  const [submitting, setSubmitting] = useState(false);

  const openCreateModal = () => {
    const nextPosition = dbGameConfig.positions.includes(positionInput)
      ? positionInput
      : dbGameConfig.positions[0] || '';
    setPositionInput(nextPosition);
    setShowCreateModal(true);
  };

  const [transfers, setTransfers] = useState<TransferListing[]>([]);
  const [completedTransfers, setCompletedTransfers] = useState<any[]>([]);

  // Function to reload active listings from DB
  const loadActiveListings = useCallback(() => {
    const apiTimeFilter = timeFilter === 'OLDEST' ? 'ALL' : timeFilter;
    getTransferPostsAction(currentGameSlug, apiTimeFilter)
      .then((res) => {
        if (res.success && res.data && Array.isArray(res.data) && res.data.length > 0) {
          const mappedDbPosts: TransferListing[] = res.data.map((p: any) => ({
            id: p.id,
            type: p.type,
            userId: p.userId || p.user_id,
            userName: p.userName,
            userGamertag: p.userGamertag,
            teamName: p.teamName || undefined,
            gameSlug: p.gameSlug as any,
            position: p.position,
            platform: p.platform,
            status: p.status === 'ACTIVO' ? 'DISPONIBLE' : p.status,
            date: new Date(p.createdAt).toLocaleDateString(),
            message: p.message,
          }));
          setTransfers(mappedDbPosts);
        } else {
          setTransfers([]);
        }
      })
      .catch((err) => {
        console.error('Error al cargar publicaciones de BD:', err);
      })
      .finally(() => setIsLoadingDB(false));
  }, [currentGameSlug, timeFilter]);

  // Function to load completed historic transfers
  const loadCompletedTransfers = useCallback(() => {
    setIsLoadingDB(true);
    getCompletedTransfersAction(currentGameSlug)
      .then((res) => {
        if (res.success && res.data) {
          setCompletedTransfers(res.data);
        } else {
          setCompletedTransfers([]);
        }
      })
      .catch((err) => {
        console.error('Error al cargar traspasos realizados:', err);
        setCompletedTransfers([]);
      })
      .finally(() => setIsLoadingDB(false));
  }, [currentGameSlug]);

  useEffect(() => {
    const timer = window.setTimeout(() => {
      if (activeTab === 'REALIZADOS') {
        loadCompletedTransfers();
      } else {
        loadActiveListings();
      }
    }, 0);
    return () => window.clearTimeout(timer);
  }, [activeTab, loadActiveListings, loadCompletedTransfers]);

  let filteredTransfers = transfers.filter((item) => {
    const matchesGame = item.gameSlug === currentGameSlug;
    const matchesTab = activeTab === 'ALL' || item.type === activeTab;
    const matchesSearch =
      item.userName.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.userGamertag.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.position.toLowerCase().includes(searchTerm.toLowerCase()) ||
      (item.teamName && item.teamName.toLowerCase().includes(searchTerm.toLowerCase()));
    return matchesGame && matchesTab && matchesSearch;
  });

  if (timeFilter === 'OLDEST') {
    filteredTransfers = [...filteredTransfers].reverse();
  }

  let filteredCompletedTransfers = completedTransfers.filter((item) => {
    const search = searchTerm.toLowerCase();
    return (
      item.playerName.toLowerCase().includes(search) ||
      item.playerGamertag.toLowerCase().includes(search) ||
      item.fromTeamName.toLowerCase().includes(search) ||
      item.toTeamName.toLowerCase().includes(search)
    );
  });

  if (timeFilter === 'OLDEST') {
    filteredCompletedTransfers = [...filteredCompletedTransfers].reverse();
  }

  const handleCreateListing = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentUser) return;
    if (!positionInput.trim() || !messageInput.trim()) return;

    setSubmitting(true);
    try {
      const teamNameVal = listingType === 'CLUB_RECLUTA_JUGADOR' ? (currentUser as any).teamName || (currentUser as any).team || 'Escuadra Oficial' : undefined;
      const teamIdVal = listingType === 'CLUB_RECLUTA_JUGADOR' ? (currentUser as any).teamId || (currentUser as any).team_id : undefined;

      // 1. Optimistic UI update: Immediately insert new listing into local state
      const newListing: TransferListing = {
        id: `tmp-${Date.now()}`,
        type: listingType,
        userName: currentUser.name || 'Atleta Oficial',
        userGamertag: currentUser.gamertag || 'Gamertag',
        teamName: teamNameVal,
        gameSlug: currentGameSlug as any,
        position: positionInput.trim(),
        platform: platformInput,
        status: 'DISPONIBLE',
        date: new Date().toLocaleDateString(),
        message: messageInput.trim(),
      };

      setTransfers((prev) => [
        newListing,
        ...prev.filter((p) => !(p.userGamertag === currentUser.gamertag && p.type === listingType)),
      ]);

      // Switch active tab and reset time filter to ensure new post is visible
      setActiveTab(listingType);
      setTimeFilter('ALL');

      // 2. Persist to MySQL database with 7-day expiration rule & auto-replace previous active post
      await createTransferPostAction({
        gameSlug: currentGameSlug,
        type: listingType,
        userId: currentUser.id,
        userName: currentUser.name || 'Atleta Oficial',
        userGamertag: currentUser.gamertag || 'Gamertag',
        teamId: teamIdVal,
        teamName: teamNameVal,
        position: positionInput.trim(),
        platform: platformInput,
        message: messageInput.trim(),
      });

      setShowCreateModal(false);
      setPositionInput('');
      setMessageInput('');

      // 🔄 RELOAD FROM DATABASE
      loadActiveListings();
    } catch (err) {
      console.error('Error al publicar anuncio:', err);
    } finally {
      setSubmitting(false);
    }
  };

  const hasTeam = Boolean((currentUser as any)?.teamId || (currentUser as any)?.team || (currentUser as any)?.role === 'Capitán' || (currentUser as any)?.role === 'DT' || (currentUser as any)?.role === 'Manager' || currentUser?.role === 'Administrador');

  return (
    <div className="space-y-6 text-[var(--text-primary)]">
      {/* 🚀 Top Control Strip & Page Header */}
      <div className="space-y-4">
        <PageHeader
          badgeText="MERCADO DE TRASPASOS"
          badgeIcon={
            <ArrowRightLeft
              className="w-3.5 h-3.5"
              style={{ color: currentGameObj.brandColor, fill: currentGameObj.brandColor }}
            />
          }
          title="Agencia Libre & Fichajes"
          highlightTitle="Transferencias"
          description={`Conecta directamente atletas disponibles y escuadras en búsqueda de fichajes para competir al más alto nivel en ${currentGameObj.name}.`}
          brandColor={currentGameObj.brandColor}
        />

        {/* Squad Cap Rule & Expiry Banner - Loaded Dynamically from MySQL */}
        <div className="p-4 rounded-2xl bg-[var(--bg-card)] border border-[var(--border-card)] flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3 shadow-sm backdrop-blur-md">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-cyan-500/10 border border-cyan-500/30 flex items-center justify-center text-cyan-400 shrink-0">
              <Database className="w-5 h-5" />
            </div>
            <div>
              <span className="text-xs font-mono font-bold text-[var(--text-heading)] uppercase block flex items-center gap-1.5">
                Reglamento de Plantilla MySQL ({currentGameObj.name})
              </span>
              <p className="text-[11px] text-[var(--text-muted)] font-mono">
                Capacidad máxima BD: <strong className="text-cyan-400">{dbGameConfig.maxSquadCap} Atletas</strong>. Máx. fichajes/temporada: <strong className="text-amber-400">{dbGameConfig.maxTransfersPerWindow}</strong>. Expiración BD: <strong>{dbGameConfig.postExpirationDays} días</strong>.
              </p>
            </div>
          </div>

          <Button
            onClick={openCreateModal}
            className="font-bold text-xs shrink-0 rounded-xl shadow-md flex items-center gap-1.5"
            style={{
              backgroundColor: currentGameObj.brandColor,
              color: '#020617',
              boxShadow: `0 0 15px color-mix(in srgb, ${currentGameObj.brandColor} 30%, transparent)`,
            }}
          >
            <Plus className="w-4 h-4" />
            Publicar en Mercado
          </Button>
        </div>
      </div>

      {/* ── BARRA DE FILTROS UNIFICADA CON SELECTORES ─────────────────────────── */}
      <div className="space-y-4">
        <FilterBar
          searchPlaceholder="Buscar por posición, gamertag o nombre de club..."
          searchValue={searchTerm}
          onSearchChange={setSearchTerm}
          options={[
            { id: 'ALL', label: 'TODAS LAS PUBLICACIONES' },
            { id: 'JUGADOR_BUSCA_CLUB', label: '🏃 AGENCIA LIBRE (ATLETAS)' },
            { id: 'CLUB_RECLUTA_JUGADOR', label: '🛡️ RECLUTAMIENTO (CLUBES)' },
            { id: 'REALIZADOS', label: '🏆 TRASPASOS REALIZADOS' },
          ]}
          activeFilter={activeTab}
          onFilterChange={(fId) => setActiveTab(fId as any)}
          renderAsSelect={true}
          count={activeTab === 'REALIZADOS' ? filteredCompletedTransfers.length : filteredTransfers.length}
          countLabel={activeTab === 'REALIZADOS' ? 'FICHADOS' : 'PUBLICACIONES ACTIVAS'}
          brandColor={currentGameObj.brandColor}
        />

        {/* SELECTOR DE ANTIGÜEDAD Y ORDEN */}
        <div className="flex items-center justify-between sm:justify-end gap-2 bg-[var(--bg-card)] border border-[var(--border-card)] px-4 py-2.5 rounded-2xl shadow-sm backdrop-blur-md font-mono">
          <div className="flex items-center gap-2">
            <Calendar className="w-4 h-4 shrink-0" style={{ color: currentGameObj.brandColor }} />
            <span className="text-xs font-bold text-[var(--text-muted)] uppercase shrink-0">Antigüedad:</span>
          </div>
          <select
            value={timeFilter}
            onChange={(e) => setTimeFilter(e.target.value as any)}
            className="bg-[var(--bg-main)] border border-[var(--border-card)] px-3 py-1.5 rounded-xl text-xs font-bold text-[var(--text-heading)] focus:outline-none cursor-pointer focus:border-[var(--border-card-hover)] transition-colors"
            style={{
              borderColor: `color-mix(in srgb, ${currentGameObj.brandColor} 40%, var(--border-card))`,
            }}
          >
            <option value="ALL" className="bg-[#0b101b] text-slate-100">
              🗓️ Todos ({dbGameConfig.postExpirationDays} Días)
            </option>
            <option value="TODAY" className="bg-[#0b101b] text-slate-100">
              ⚡ Hoy (Últimas 24H)
            </option>
            <option value="3_DAYS" className="bg-[#0b101b] text-slate-100">
              📅 Últimos 3 Días
            </option>
            <option value="7_DAYS" className="bg-[#0b101b] text-slate-100">
              🗓️ Últimos {dbGameConfig.postExpirationDays} Días
            </option>
            <option value="OLDEST" className="bg-[#0b101b] text-slate-100">
              ⏳ Más Antiguos Primero
            </option>
          </select>
        </div>
      </div>

      {/* 🏆 TRASPASOS REALIZADOS SECTION */}
      {activeTab === 'REALIZADOS' ? (
        isLoadingDB ? (
          <div className="py-8">
            <TacticalLoadingSkeleton
              game={currentGameObj}
              message={`CARGANDO HISTORIAL DE TRASPASOS REALIZADOS PARA ${currentGameObj.name}...`}
            />
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredCompletedTransfers.map((item, index) => (
              <EsportsCard
                key={item.id}
                href="#"
                title={`${item.playerName} (@${item.playerGamertag})`}
                subtitle={`🎮 ${currentGameObj.name}`}
                description={`Fichaje confirmado: El atleta fue incorporado exitosamente a la plantilla de ${item.toTeamName}.`}
                tag={item.transferType}
                badges={[
                  {
                    text: 'FICHAJE EXITOSO',
                    variant: 'emerald',
                  },
                ]}
                stats={[
                  { icon: <Shield className="w-3.5 h-3.5 text-amber-400" />, label: 'Origen', value: item.fromTeamName },
                  { icon: <Shield className="w-3.5 h-3.5 text-emerald-400" />, label: 'Destino', value: item.toTeamName },
                ]}
                footerLeft={
                  <span className="flex items-center gap-1 text-[11px] text-[var(--text-muted)] font-mono">
                    <Clock className="w-3.5 h-3.5 text-cyan-400" />
                    <span>{new Date(item.signedAt).toLocaleDateString()}</span>
                  </span>
                }
                actionText="VER MOVIMIENTO AUDITADO"
                brandColor={currentGameObj.brandColor}
                animationDelay={index * 50}
              />
            ))}

            {filteredCompletedTransfers.length === 0 && (
              <div className="col-span-full py-16 text-center border border-dashed border-[var(--border-card)] rounded-3xl bg-[var(--bg-card)]/40 space-y-3 font-mono">
